pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (two items perfectly fill the bin).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect 2-step fit: strong reward.
        let gap = (post - nxt).abs();
        if gap < 0.5 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of match.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space that is too small
            // to be useful (wasted residual).
            let wasted = post;
            if wasted < 10.0 {
                score += 20.0; // tiny unusable sliver
            } else {
                score += 5.0 + 0.1 * wasted;
            }
        }

        // If the next item fits *only* here among fitting bins, encourage using it.
        if next_item_size <= post_residual && fitting_bins_count <= 2 {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize post_residual (best-fit behavior).
        score -= 10.0;
    }

    // Last-chance bin for the current item: strong incentive to use it
    // rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize bins whose residual is far below the mean (already tight bins
    // are valuable; wasting them on a loose fit is bad), reward bins with
    // residual near the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 110.0
            - 20.0 * (step_index as f64 / total_items.max(1) as f64)
            - 2.0 * open_bins_count as f64;
        // If next item would fit perfectly in the residual of an existing bin,
        // opening a new bin is unattractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score = base + 40.0;
        } else {
            score = base + (post_residual as f64 - mean_residual).abs() * 0.2;
        }
    }

    // Mild preference for filling bins early in the stream.
    score -= 3.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: later on, prefer using existing bins more aggressively.
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    score *= 1.0 + 0.35 * progress; // penalize leftover space more as stream advances

    // Reward tight fits: small post_residual gets a strong discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item could exactly fill this bin's
    // post-residual, reward heavily; if next item won't fit here, penalize
    // mildly (wasted capacity for the future).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item chain
        } else if next_item_size > post_residual {
            score += 6.0; // next item can't use leftover space
        } else {
            score -= 5.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the current item fits poorly
        // everywhere else (large post_residual in existing bins) and there
        // are already many open bins with fragmented space.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 10.0 + 8.0 * fragmentation + 0.5 * open_bins_count as f64;
        // But discourage opening new bins early when existing bins fit well.
        if fitting_bins_count > 0 && post_residual < 20 {
            score += 20.0;
        }
    } else {
        // Mild preference for bins whose residual deviates from the mean
        // (consolidate similar-fill bins, keep a spread of residual sizes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Encourage balancing: prefer bins with residual above the mean slightly,
    // so low-residual bins stay reserved for small items.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make empty bins less attractive unless current bins would waste space
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mean residual coupling: penalize placements far from mean residual usage
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // Stream progression: slightly favor consolidation late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fill
    } else if post_residual <= 10 {
        // Unusable-ish dead space: strongly penalize.
        score += 300.0 - (post_residual as f64) * 10.0;
    } else if post_residual <= 20 {
        // Marginal gap: moderate penalty.
        score += 60.0 - (post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score += 80.0; // leaves dead space after next item
        } else if post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is above the mean (keeps spread balanced),
    // but only mildly so dead-space logic dominates.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let bad_gap_elsewhere = mean_residual > 0.0 && mean_residual < 12.0;
        if bad_gap_elsewhere && open_bins_count > 0 {
            score -= 100.0;
        } else {
            score += 90.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..=15)
    // are toxic — they will almost never be filled by future items.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 + (15 - post_residual) as f64 / 15.0);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    } else if post_residual > 50 {
        // Large residual is healthy, keep it flexible.
        score -= 10.0;
    }

    // Dead space is worse when the bin is already deep in the stream
    // (few chances left to fill the gap).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward; if the
    // post-residual is just barely below the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins when few are open.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if the average residual is large, prefer bins
    // that consume more slack (tighter fits) to consolidate.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the dead space is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when every open bin would create unusable dead space.
    if bin_residual == bin_capacity {
        // Baseline mild penalty so tight fits in open bins win.
        score += 20.0;
        // But if the item is large relative to capacity and open bins are
        // fragmented, a new bin is attractive.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual (0..1)
    let pr = post_residual as f64 / bin_capacity as f64;
    let ir = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: penalize large post_residual quadratically,
    // scaled by stream progress (later in stream => tighter packing desired).
    let progress_sq = progress * progress;
    score += 40.0 * pr * pr * (0.5 + progress_sq);

    // Reward near-full fits with a smooth saturating term
    score -= 25.0 * (1.0 - pr) * (1.0 - pr) * ir;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins far from mean residual (prefer balanced residuals)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 8.0 * dev * dev;

    // Lookahead coupling: if next item fits in the post-residual, reward; otherwise penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            let slack = (post_residual as f64 - nx) / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nx - post_residual as f64) / bin_capacity as f64;
            score += 12.0 * gap * gap;
        }
    }

    // Mild penalty for many open bins, smoothed by progress
    score += 0.5 * open_bins_count as f64 * (0.3 + progress);

    // New-bin candidate handling: only attractive early or when residual would be wasted
    if bin_residual == bin_capacity {
        let waste = 20.0 * pr * pr * (1.0 - progress);
        score = 35.0 + progress * 30.0 + waste - (1.0 - ir) * 10.0;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when a unique fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is
    // for typical item sizes (1..100). Classes keyed on integer division.
    let class = post_residual / 10; // 0..10 harmonic class
    let phase = post_residual % 10; // fine phase within class

    // Dead-space penalty: residuals in awkward ranges (1..9, 11..19, 21..29)
    // are hard to fill by future items; smooth-fill residuals (0, 50, 100-ish)
    // are valuable. Use a sinusoidal harmonic on the class index.
    let class_f = class as f64;
    let harmonic = ((class_f * std::f64::consts::PI / 5.0).sin()).abs();
    score += harmonic * 12.0;

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward residuals that exactly match plausible next-item sizes.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // reward leaving room for the lookahead item
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // post_residual cannot host the next item: penalize wasted class
            score += 25.0 + phase as f64;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current bin's post-residual is small/awkward) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = (post_residual as f64).min(1.0); // placeholder to keep types used
        let _ = tight_fit;
        // Prefer opening a fresh bin when mean residual across open bins is low
        // (open bins are mostly full) or when many bins are open and this item
        // would leave a nasty small residual in any of them.
        let nasty = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score = 200.0
            - 120.0 * (1.0 - progress)
            - 3.0 * open_bins_count as f64
            - 0.5 * mean_residual
            + 80.0 * nasty;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can always host the next item: mild bonus
            score -= 20.0;
        }
    }

    // Small refinement: prefer tighter fits within same class via phase.
    score -= phase as f64 * 0.5;

    // Slight global pressure to consolidate into fewer bins early.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful (below min item size 1..=100
    // means residual < ~20 is nearly dead unless next item is tiny).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling: penalize post_residual that can't fit the next item,
    // reward post_residual that fits next_item_size exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // residual stays useful: reward proportional to how snugly next item fits later
            score -= 12.0 * (nxt / post_residual as f64);
        } else if post_residual > 0 {
            // dead space relative to the lookahead: penalize more early in the stream
            score += (nxt - post_residual as f64) * (1.5 + 2.0 * (1.0 - progress));
        }
        // Perfect two-item closure bonus: item + next item exactly fills residual
        if (item_size + next_item_size) == bin_residual {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize post_residual hard
        score += 10.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty so we don't spread items too thin
    else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(8.0);
    }

    // Global state: prefer bins with residual below mean (more filled bins),
    // penalize dipping into unusually empty bins.
    if (bin_residual as f64) > mean_residual * 1.05 {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    } else {
        score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Too many open bins: encourage consolidation, discourage opening new bins.
    if open_bins_count > 8 {
        score += 2.0 * (open_bins_count as f64 - 8.0).min(20.0);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and no tight fit exists,
        // or when few bins are open. Penalize by default; relax for big items late in stream.
        let base = 45.0
            - 0.35 * item_size as f64
            - 20.0 * progress
            - if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += base.max(-10.0);
    }

    // Slight preference for exact-fill closure overall.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10) can
    // practically use are heavily penalized. A gap of 1..=9 is "dead" unless a
    // tiny item arrives later; treat small gaps as wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    }

    // Tight-fit reward: fraction of residual consumed.
    let fill_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    score -= 25.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or open-bin residuals are bloated.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let bloat = mean_residual / bin_capacity as f64;
        // Base cost of a fresh bin, discounted by stream pressure and bloat.
        let mut new_bin_score = 85.0 - 20.0 * progress + 30.0 * bloat;
        // Large items waste less in a fresh bin.
        new_bin_score -= 0.4 * item_size as f64;
        // Lookahead: if next item pairs well with the leftover (post_residual),
        // a fresh bin is more attractive.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                new_bin_score -= 15.0;
            } else {
                new_bin_score += 10.0;
            }
        }
        // If this bin is a last chance elsewhere, discourage opening a new one.
        if fitting_bins_count >= 1 {
            new_bin_score += 25.0;
        }
        score = score.min(new_bin_score + 200.0); // keep ordering sane
        score = new_bin_score;
    } else {
        // Open-bin count pressure: mildly discourage spreading across many bins.
        score += 1.5 * open_bins_count as f64;
        // Lookahead coupling: if leftover after placement can host the next item,
        // this placement is chain-friendly; reward it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (item sizes >= 1, but practically small gaps below the typical item
    // floor are wasted). Penalize them super-linearly.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fills that leave room plausibly matching the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover smaller than next item: dead space for the lookahead
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress) * 0.8;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small relative to item or many bins exist.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 || pressure < 0.25 {
            score -= 30.0 + 20.0 * (1.0 - pressure);
        } else {
            score += 15.0 + open_bins_count as f64;
        }
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it cannot hold even a mid-sized item (threshold ~10)
    // or cannot hold the lookahead item.
    if post_residual > 0 {
        let dead_threshold = 9u32;
        if post_residual <= dead_threshold {
            score += 40.0 * (dead_threshold as f64 - post_residual as f64 + 1.0);
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Gap unusable for the known next item: partial dead-space penalty.
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Usable residual: mild reward proportional to remaining space.
            score -= 0.2 * post_residual as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements into already-crowded bin pools,
    // but reward using last-chance bins (fitting_bins_count == 1).
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Neutral baseline: prefer it over dead-space-creating fits,
        // but lose to tight fits in open bins.
        score = 15.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= 50 {
            // Large item starting a fresh bin is fine.
            score -= 5.0;
        }
    }

    // Progression coupling: early in the stream, allow slightly more
    // aggressive bin opening to build good residual structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // Mean residual coupling: if open bins are already loose on average,
    // discourage adding more slack.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10, minimum item size) are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Partially usable small gaps (10..=20) are also risky.
    else if post_residual <= 20 && post_residual > 0 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual == 0 is perfect).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Prefer bins whose residual is close to the item (relative fit quality).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post-residual is nonzero but cannot hold the next item, slight penalty.
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin; tuned so poor fits elsewhere lose.
        score = 45.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the NEXT item fits the post-residual perfectly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            if gap == 0.0 {
                score -= 500.0;
            } else {
                score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item won't fit: penalize proportionally to wasted lookahead potential.
            score += 30.0 * (nxt - post_residual as f64) / nxt.max(1.0);
        }
    }

    // Penalize leaving residuals below the minimum item size (unusable dead space),
    // unless post_residual is 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter;
    // prefer filling tighter bins to consolidate waste.
    let cap = bin_capacity as f64;
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score -= 25.0 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make empty bins mildly attractive only when item is large
    // and current bin fit is poor; otherwise discourage spreading across bins.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        if fit_ratio > 0.7 {
            score -= 20.0 * (fit_ratio - 0.7) * 10.0;
        } else {
            score += 40.0;
        }
    }

    // Late-stream consolidation: as stream progresses, favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (<10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score += 15.0;
    }

    // Reward if the leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = 70.0 + 0.5 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in stream, opening fresh bins is cheap; later it is costly.
        score += 30.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild tie-breaking toward bins with residual close to item size (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Slight nudge using mean residual: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps left after placement are wasted.
    // Quadratic penalty grows as post_residual shrinks toward unusable sizes.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Penalize small leftovers heavily (dead space), scaled by capacity.
        let deadness = 1.0 - (pr / bin_capacity as f64);
        score += 3.0 * deadness * deadness * (bin_capacity as f64 - pr);
        // Harsh penalty for residuals below 10 (near-unusable slivers).
        if pr < 10.0 {
            score += 60.0 + 4.0 * (10.0 - pr);
        } else if pr < 25.0 {
            score += 15.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to item size (fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Open bins pressure: discourage spreading across many open bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // placing in this open bin would leave a bad gap AND the item is large.
    if bin_residual == bin_capacity {
        // Neutral base for the fresh bin.
        score = (bin_capacity - item_size) as f64;
        // Favor opening a new bin for large items (they pair well with future items).
        if item_size >= 50 {
            score -= 10.0;
        }
        // If many bins are open, resist opening more.
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item would NOT fit the post residual but would fit a fresh bin,
    // slightly penalize blocking it.
    if next_item_size > post_residual && bin_residual != bin_capacity {
        score += 5.0;
    }

    // Early stream: be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized (they become waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward snug fits relative to the item size (small slack ratio).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 20.0 * fit_ratio.min(3.0);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize adding more bins when many are open,
    // making consolidation attractive.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: if the next item fits into the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would NOT fit in post-residual, mild penalty for blocking.
    if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Prefer reusing existing bins unless current bin is a bad fit.
        // Base cost for opening a new bin, reduced early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 40.0 * progress - 0.3 * open_bins_count as f64;
        // If no open bin can even fit the item, opening is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // 2-step lookahead: reward if the next item fits into post_residual,
    // extra reward for a near-exact match (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.35 * slack;
        if slack == 0.0 {
            score -= 15.0; // perfect 2-item chain fill
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving dead space.
        score += 0.25 * post_residual as f64;
        // If next item is small, dead space is more forgivable.
        if next_item_size <= post_residual + 10 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins with less residual than average
    // are "dirtier" — prefer filling them to consolidate waste.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.30 * diff;
    } else {
        // New-bin candidate: penalize mildly so it only wins when
        // no open bin offers a decent fit or a lookahead chain.
        score += 6.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 3.0;
        }
        // Early in stream, opening bins is cheaper; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for bins that are relatively full already.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill;

    // Many open bins: consolidate harder.
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1, but practically small gaps) are waste.
    // Penalize gaps below a "useful threshold" superlinearly.
    let gap = post_residual as f64;
    let useful_threshold = 12.0;
    if gap < useful_threshold {
        score += (useful_threshold - gap) * (useful_threshold - gap) * 1.5;
    }

    // Reward near-perfect fits.
    if gap <= 3.0 {
        score -= 30.0;
    } else if gap <= 8.0 {
        score -= 10.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: prefer spreading load when few bins are open,
    // prefer consolidation (avoid opening new bins) when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += bin_pressure * 0.8 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item: penalize.
        score += 6.0;
    }

    // New-bin candidate: only attractive when the current item is large
    // relative to remaining residuals (poor fit everywhere) or no bins fit.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64) - (item_size as f64);
        // Base cost of opening a bin; reduced when item is big.
        score = 40.0 - 0.3 * (item_size as f64) + 0.5 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        let _ = poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += 3.0 * tightness * (1.0 + progress);

    // Penalize dead space that cannot fit the average next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else if post_residual == next_item_size {
            score -= 6.0; // perfect lookahead fit
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0 * (1.0 - tightness);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins below mean residual are "fuller", favor them.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere (large item, high mean residual, many bins).
    if bin_residual == bin_capacity {
        let waste_penalty = (bin_capacity - item_size) as f64;
        let mut nb = waste_penalty * 0.9;
        nb += (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 4.0; // new bin can still host next item
        }
        if fitting_bins_count == 0 {
            nb -= 100.0; // forced new bin
        }
        // Early in stream, opening bins is cheaper; later, consolidate.
        nb += 20.0 * (1.0 - progress);
        score += nb;
    }

    // Slight preference for bins whose residual stays "usable" (>= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills relative to capacity scale.
    score *= 0.5 + 0.5 * (bin_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Strong reward for perfect two-item packing (post_residual == next_item_size).
            score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item doesn't fit: penalize leftover dead space.
            score += 0.15 * (nxt - post);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps bins interchangeable (flexible).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-preferred when the stream is early
    // and current bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is attractive if the item is small relative to capacity
        // and remaining bins are fragmented (high mean residual).
        score = 25.0 + 0.3 * mean_residual * (1.0 - progress) - (item_size as f64);
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 - item_size as f64 {
            score -= 20.0; // new bin can host current + next item together
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

