    // Lookahead: if the next item exactly fits the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 && (post_residual as f64) < dead_threshold {
        // Next item can't use this dead space anyway -> slightly worse.
        score += 2.0;
    }

    // Mild preference for bins tighter than the current mean residual
    // (concentrate waste into few bins).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
