    // over opening a new bin (unless the new-bin candidate wins otherwise).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive by default, but allow it when the
    // item leaves a huge unusable gap in every bin (large post_residual here is
    // fine for an empty bin, so its raw score stays low).
    if bin_residual == bin_capacity {
        score = post + 30.0 - 0.0;
        // Early in stream, opening bins is cheap; late, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        if next > 0.0 && next <= post {
            score -= 10.0; // empty bin chains well with next item
        }
    }

    // Mild reward for keeping very small post_residual (waste minimization).
    score -= 0.3 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize tiny dead space that is hard to reuse (post_residual small but nonzero).
    if post_residual > 0 && post_residual < 10 {
