    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting residual.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is poor. Penalize the empty bin, scaled by how well any
    // existing bin could fit (approximated via mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 15.0 + 10.0 * progress;
        // If mean residual across open bins is large, opening new bins is wasteful.
        nb += (mean_residual / bin_capacity as f64) * 20.0;
        // If few bins can fit the item, a new bin is more acceptable.
        if fitting_bins_count == 0 {
            nb -= 40.0;
        } else if fitting_bins_count == 1 {
            nb -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        if progress > 0.8 {
            nb += 10.0;
        }
        score += nb;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Global residual balance: prefer bins whose residual is below the mean
    // (i.e., use up the emptier-feeling bins less; keep large residuals for
    // future large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
