    }

    // Prefer bins below mean residual (packing fuller bins first), smoothly.
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 20.0 - 25.0 * size_frac * size_frac - 10.0 * progress;
