}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac; // quadratic penalty on dead space

    // Harmonic class of post_residual: residual mod 10 buckets
    let r_mod = post_residual % 10;
    // Residuals that are "harmonic" (divisible-friendly) are less penalized
    let harmonic_bonus = match post_residual {
        0 => -25.0,               // perfect fit
        r if r <= 10 => -8.0,     // small residual, likely fillable
        r if r % 20 == 0 => -6.0, // harmonic multiple of 20
        r if r % 10 == 0 => -4.0, // multiple of 10
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Penalize odd/awkward remainders slightly
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 2.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward bins that can also host the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize bins that strand the next item
            score += 6.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        // Base cost of a new bin
        score += 15.0;
        // If many bins fit the item, opening new bin is wasteful
        score += 5.0 * fitting_bins_count as f64;
        // If item leaves a bad residual in any bin, new bin more attractive
        let best_possible_waste = item_size % 10;
        if waste_frac > 0.5 && (item_size as f64) < mean_residual {
            score -= 10.0;
        }
        let _ = best_possible_waste;
    }

    // Stream progression: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer fuller bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Small tie-breaker noise-free coupling with open bin count
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // a future item are pure waste -> heavy penalty.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        // Dead space: penalty grows as the gap shrinks toward zero.
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits (small but still usable residuals).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // This is the new-bin candidate.
        score += 25.0 + 8.0 * open_bins_count as f64;
        // But if the item would leave a nicely sized gap matching the next item,
        // opening a fresh bin can still win (handled by the lookahead below).
    } else {
        // Reward reusing existing bins, more so when bins are plentiful.
        score -= 5.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this placement (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit in the gap: penalize gaps just below next_item_size.
            if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
                score += (next_item_size as f64 - post_residual as f64) * 3.0;
            }
        }
    }

    // Mild stream-phase term: early on, keep bins flexible (favor moderate residuals);
    // late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual context: if this bin's residual is far below the mean,
    // it's the " fullest" bin — finishing it off is good.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward when the NEXT item exactly fills this bin ---
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly consumes the leftover space.
        if post_residual == next_item_size {
            score -= 100.0;
        } else {
            // Penalize proportional to how badly post_residual mismatches next_item_size.
            score += lookahead_gap * 0.6;
        }
        // If the next item can still fit after this placement, mild reward.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // --- Relative residual vs mean residual: prefer bins tighter than average ---
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.4;

    // --- Last-chance bonus: this is the only bin that can fit the item ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // --- Penalize creating large unusable dead space (nothing in [1..=10] fits) ---
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small dead space is fine, it's sealed
    }
    if post_residual >= 10 && post_residual <= 20 {
        score += 10.0; // awkward mid-range gap that only tiny items can use
    }

    // --- Prefer filling nearly-full bins first (best-fit flavor) ---
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // --- Late in stream: be more aggressive about closing bins tightly ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += rel * progress * 0.3;

    // --- Many open bins: discourage spreading; prefer tight bins even more ---
    if open_bins_count > 4 {
        score += (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // New empty bin should only win when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: fraction of the bin filled by this placement
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    // Reward tight fits super-linearly
    score -= 60.0 * fill * fill;

    // Penalize small unusable dead space (waste pockets)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size {
        // residual smaller than current item: space is "dead" for this item
        score -= 8.0;
    }

    // Lookahead: does the next item fit in the post-residual? Reward that.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let snug = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to the gap
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating (low residual bins)
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= crowding * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin, more so early and when alternatives exist
    if bin_residual == bin_capacity {
        let alt_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 30.0 + 12.0 * alt_pressure + 40.0 * (1.0 - progress);
        // But if item is huge relative to mean residual space, opening is less bad
        let mean_fit = mean_residual >= item_size as f64;
        if mean_fit {
            score += 25.0;
        }
    }

    // Mild time-horizon shaping: later in stream, be greedier about tight fits
    score -= 15.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, softly warped by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear coupling: small post residuals are more acceptable late in the stream
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize dead space quadratically (unusable gaps)
    score += 0.15 * pr_norm * pr_norm * cap * (1.0 - progress);

    // Lookahead: reward bins whose post residual fits next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it before opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (pr_norm);

    // Prefer bins with residual close to item size (tight fit reward)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 40.0 * tightness * tightness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot" of capacity it lands in.
    // Classes: 0 (perfect), small dead space, half-fill, large residual.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect closure
    } else if post <= quarter {
        score -= 25.0; // tight fit, small dead space
    } else if post <= half {
        score -= 8.0; // mid residual, still reusable
    } else {
        score += 10.0; // large residual: wasteful
    }

    // Modulo-class coupling: if the next item fits exactly into the post-residual
    // (post_residual % next_item_size == 0), this bin is a harmonic successor.
    if next_item_size > 0 {
        if post >= next_item_size {
            if post % next_item_size == 0 {
                score -= 30.0; // exact subdivision available for next item
            } else if post - next_item_size <= quarter {
                score -= 15.0; // next item leaves near-perfect residue
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize proportional dead space
            score += 0.25 * (next_item_size - post) as f64;
        }
    }

    // Integer-division threshold on residual before placement: bins whose residual
    // is in the "awkward" band (just above item_size) are precious; prefer using them.
    let slack = bin_residual - item_size;
    if slack <= quarter {
        score -= 12.0;
    } else if slack > half {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless residual is tiny and useless).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make an empty bin moderately attractive only when
    // open bins are fragmented (high mean residual, many bins) or late stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let fragmentation = (mean_residual / cap_f - 0.5).max(0.0);
        score = cap_f * 0.35 + 40.0 * fragmentation + 30.0 * progress
            - if next_item_size > 0 && next_item_size >= bin_capacity / 2 { 25.0 } else { 0.0 };
        if fitting_bins_count == 1 {
            score += 35.0; // don't abandon the sole fitting bin
        }
    }

    // Mild preference to fill fewer bins when many are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 range).
    // Treat gaps < 12 as dead space, with a superlinear penalty.
    if post_residual > 0 && post_residual < 12 {
        score += (13.0 - post_residual as f64) * (13.0 - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Perfect fit for the lookahead item too: very desirable.
    if next_item_size > 0 && post_residual == next_item_size as f64 as u32 {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer packing into existing bins
    // (subtract), making new bins less attractive as open_bins_count grows.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    score -= pressure;

    // Penalize opening a new bin (residual == capacity) progressively.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Dead space relative to mean residual: leaving a gap much smaller than the
    // average residual means this bin's leftover is likely unusable.
    if mean_residual > 0.0 && (post_residual as f64) < mean_residual * 0.35 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead: if the next item cannot use the post_residual, penalize mildly.
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 && post_residual > 0 {
        score += 10.0;
    }

    // Stream progression: late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead match (within a small slack).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 40.0 - 2.5 * slack;
        } else {
            score -= 15.0 / (1.0 + slack);
        }
    }
    // If the next item cannot fit here, mildly penalize (dead space trap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    // Penalize creating residuals far below the mean residual (fragmentation risk),
    // but only when the residual is still meaningfully large.
    if post_residual > 0 {
        let frag = (mean_residual - post_residual as f64).abs();
        score += 0.15 * frag;
        // Small unusable leftovers are dead space: penalize sharply.
        if post_residual < 10 {
            score += 25.0 - 2.0 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64;

    // Late in the stream, prefer closing bins tightly (leaner residual weighting).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Discourage opening a new bin when existing bins can take the item.
            score += 55.0 + 2.0 * fitting_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that no future item can plausibly use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            score -= 4.0 * (nx / 100.0);
        } else if (bin_residual as f64) >= nx && post_residual < nx {
            // this placement blocks a perfect next-item fit in this bin
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented or full
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let late = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // open new bin when existing residuals are small relative to item
        score += 20.0 - 12.0 * fragmentation / 100.0 - 6.0 * late - pressure.min(10.0);
        // discourage new bins when current bin fits item perfectly
        if item_size as f64 >= mean_residual - 2.0 {
            score -= 9.0;
        }
    }

    // Global state coupling: prefer filling bins with large residuals early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0 * (1.0 - progress);

    // Penalize spreading across too many open bins
    score += 0.15 * open_bins_count as f64 * fit_ratio;

    // Reward bins whose residual is close to the mean (keeps bin sizes uniform)
    score -= 0.5 * (bin_residual as f64 - mean_residual).abs() / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post residual)
    let mut score = pr as f64;

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, small residuals are fine; later, wasted space hurts more.
    let waste_penalty = x * x * (1.0 + 2.0 * progress) + 0.5 * x * x * x * progress;
    score += 40.0 * waste_penalty;

    // Reward near-perfect fits with a smooth quartic bump
    let perfect = 1.0 - x;
    score -= 25.0 * perfect * perfect * perfect * perfect * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - x * x);
    }

    // Lookahead coupling: if the next item fits the post residual, reward;
    // smooth interaction between post residual and next item size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = x * cap - ni;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 15.0 * (1.0 - g * g) * (1.0 - progress * 0.5);
        } else {
            let g = (-gap) / cap;
            score += 10.0 * g * g;
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate similar residuals), smoothed via squared deviation.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + progress);

    // Slight penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: neutralize its raw advantage when open bins exist
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable
    // since item sizes >= 10 (and >= 1 in general) — penalize small nonzero residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 100.0;
    }

    // Integer-division thresholds: residuals divisible into common size classes
    // are more reusable. Reward residuals that are multiples of 10 or 25.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead pairing: if the next item exactly fills the post residual,
    // this bin is a perfect chain — big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: keep the bin attractive
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the residual: penalize proportionally to waste
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is huge
    // relative to capacity or mean residuals are all tiny.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 || (mean_residual < 15.0 && open_bins_count > 0) {
            score -= 5.0;
        } else {
            score += 40.0;
        }
    }

    // Late in the stream: prefer closing bins tightly (minimize residual waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=dead_zone)
    // are useless; penalize them quadratically to strongly prefer bins that fill up.
    let dead_zone: f64 = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_zone {
        score += (dead_zone - pr) * (dead_zone - pr) * 3.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if pr <= 5.0 {
        score -= 20.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Penalize leaving a gap that exactly matches nothing useful: if post_residual
    // is smaller than the next item, that space is likely wasted.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead synergy: reward if the post residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, favor compacting into existing bins
    // rather than spreading; with few open bins, a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (pr / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below average, it is a
    // good compaction target; if far above average, using it wastes bulk space.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate: neutral-ish base, opened only when existing fits are poor.
    if bin_residual == bin_capacity {
        score = 55.0 + pressure * 0.5 - 8.0 * tightness;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing a big item now with a big next item in a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Penalize large leftover dead space nonlinearly (waste grows superlinearly)
    let pr = post_residual as f64;
    score += 0.35 * (pr / 100.0) * (pr / 100.0) * 100.0;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            score += 6.0 * (ns / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many fitting bins: mild penalty to encourage tighter, more constrained fits
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Global state coupling: if mean residual is high, prefer filling existing bins
    if mean_residual > item_size as f64 {
        score -= 0.08 * mean_residual;
    }

    // New-bin candidate handling: discourage opening new bins early, allow late
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 25.0 - 20.0 * progress;
        // Opening a new bin is attractive if it leaves room for the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 * progress;
        }
    }

    // Tight fit bonus: near-exact fills are golden
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Time horizon: as stream ends, prefer minimizing residual across open bins
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear polynomial shaping.
    // Small residuals are good (tight fit); the quadratic term penalizes
    // leaving very large unusable gaps, growing with stream progress.
    let mut score = pr
        + 30.0 * norm_pr * norm_pr * (0.4 + 0.6 * progress)
        + 15.0 * norm_pr * norm_pr * norm_pr * progress;

    // Smooth coupling: reward tight fits (small post_residual) more strongly
    // as the stream progresses (bins get "sealed" over time).
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin smoothly (quadratic in how well next item fills it).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let fill = n / pr.max(1.0);
            score -= 20.0 * fill * fill;
        } else {
            // next item cannot use the leftover: mild penalty scaled by gap
            score += 8.0 * ((n - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Crowding effect: with many open bins, prefer consolidating into
    // below-average residual bins (smooth interaction with mean_residual).
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 5.0 * crowd * (mean_residual - pr).max(0.0) / cap;

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large relative to capacity or early in the stream.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score = cap * (1.0 - item_frac) * (1.0 - 0.5 * progress)
            + 10.0 * (1.0 - item_frac) * item_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        return -1000.0;
    }

    // Dead space: post_residual too small to ever hold the smallest item (1..100).
    // Harmonic classes: post_residual in 1..=9 is nearly useless; penalize hard.
    if post_residual < 10 {
        score += 400.0;
    } else {
        // Classify post_residual into capacity-fraction buckets; residual that
        // can still host large items (>= half capacity) is valuable.
        if post_residual >= bin_capacity / 2 {
            score -= 30.0;
        } else if post_residual >= bin_capacity / 3 {
            score -= 10.0;
        }
        // Modulo classes: residuals that are multiples of common item sizes
        // (e.g. 10, 20, 25, 50) are more likely to be exactly filled later.
        let r = post_residual as i64;
        if r % 10 == 0 {
            score -= 8.0;
        }
        if r % 25 == 0 || r % 50 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly favor this bin (creates a chain of tight fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            // Next item fits: good, but leave some slack preference.
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 60.0; // near-exact chain
            } else {
                score -= 20.0 / (1.0 + slack / 50.0);
            }
        } else {
            // Next item will NOT fit here -> this residual becomes dead space.
            score += 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // and the fit would leave awkward leftovers.
        if post_residual < 10 && open_bins_count > 0 {
            score -= 100.0; // prefer fresh bin over wrecking a bin
        } else {
            score += 40.0 + mean_residual * 0.3; // default: reuse open bins
        }
        // Early stream: keep bins consolidated; late stream: allow spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    // Mild pressure toward fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Tie-break with mean residual: prefer bins below mean residual
    // (i.e., fuller than average) to consolidate load.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1, but
    // practically small gaps waste capacity) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Semi-dead zone: only very small items can use it; mild penalty.
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fills relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // packing into existing bins and avoid opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure;

    // New-bin candidate: penalize by default; only attractive when no good
    // existing fit exists (large item, few fitting bins, high mean residual).
    if bin_residual == bin_capacity {
        let mut new_bin_score = 55.0 + 4.0 * pressure;
        if item_size > 60 {
            new_bin_score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            new_bin_score -= 50.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            new_bin_score -= 15.0;
        }
        score = new_bin_score;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover anyway; slight bonus for
        // using the bin now.
        score -= 5.0;
    }

    // Stream progression: early on, be more selective about dead space;
    // late in stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 20.0 * progress;
    }
    if post_residual == 0 {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.4; // exact chain fit best
            if slack == 0.0 {
                score -= 200.0; // perfect 2-step chain
            }
        } else {
            // Dead space relative to lookahead item.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare against mean residual: prefer filling bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = post_residual as f64;
        score += 60.0 + waste * 0.5;
        // New bin is acceptable only if item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 120.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // Many open bins: discourage adding more.
        score += open_bins_count as f64 * 5.0;
    } else {
        // Reward placing large items into tight existing bins.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, but tiny dead space (<10)
    // that nothing can use is penalized relative to a perfectly filled bin.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 15.0; // dead space too small for any item
    } else {
        score -= 20.0 / pr; // mild reward for smaller leftovers
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // partial credit proportional to how well next item consumes leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item won't fit here; slight penalty if leftover becomes dead
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins exist
    // and mean residual suggests capacity is available; reward it early in stream
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // opening new bins is cheap early, expensive late or when bins are empty-ish
        score += 30.0 * progress;
        score += 40.0 * (1.0 - avg_fullness);
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Prefer bins below mean residual (keeps distribution balanced, avoids many
    // half-empty bins): a bin with residual larger than mean is less attractive.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Slight preference for bins that are already heavily used.
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * used;

    // Late in the stream, consolidation matters more: penalize leaving large gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (pr / 100.0);

    // Mild penalty for proliferation of open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Penalize small-but-nonzero post-residual (dead space) via smooth quadratic well
    let dead = (norm_pr - 0.15) * (norm_pr - 0.15);
    score += 12.0 * dead * (1.0 - norm_pr);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer bins with residual below mean residual (compact packing) smoothly
    score += 0.4 * (mean_residual - pr);

    // Lookahead: reward if next item fits in post-residual, penalize otherwise
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((next_item_size as f64) - pr).abs() / cap;
        score += fits_next * (-6.0) * (1.0 - gap) + (1.0 - fits_next) * 4.0 * gap;
    }

    // Smooth pressure term: many open bins -> favor consolidation
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * progress;
    score -= 6.0 * pressure * (1.0 - norm_pr);

    // New-bin candidate: make empty bins mildly unattractive unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 5.0 + 8.0 * (1.0 - progress) - 6.0 * (mean_residual / cap) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" residue classes (multiples of small harmonics) are reusable,
    // so reward them; awkward residues create dead space, penalize them.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: best possible outcome.
        score -= 60.0;
    } else if pr % 10 == 0 {
        // Leftover aligned with the item-size grid (10..80 range) -> reusable.
        score -= 12.0;
        if pr >= 10 && pr <= 20 {
            score -= 8.0; // small aligned gap, easily filled later
        }
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else if pr % 2 == 0 {
        score -= 1.5;
    } else {
        // Odd, unaligned dead space: penalize extra.
        score += 4.0;
    }

    // Integer-division thresholds: classify leftover by quotient bands.
    let band = pr / 25; // 0: tiny, 1: small, 2: medium, 3: large
    match band {
        0 => score -= 6.0,             // nearly full bin, excellent
        1 => score -= 2.0,             // decent fill
        2 => score += 3.0,             // half-empty, mediocre
        _ => score += 8.0,             // mostly empty, wasteful use of this bin
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match: next item size divides or aligns with leftover.
            if pr % next_item_size.max(1) == 0 {
                score -= 14.0;
            } else {
                score -= 7.0;
            }
        } else {
            // Next item cannot use the leftover at all.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // Last item: prefer zero waste strongly.
        score += pr as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += pressure;
        // Late in the stream, opening new bins is costly; early, it's fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // A new bin is good if the item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.3;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are already perfect fits, but gaps that cannot
    // hold the next item are likely dead weight.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap unusable by lookahead item
        }
        if post_residual < 10 {
            score += 40.0; // tiny dead space, near-wasted capacity
        }
    } else {
        score -= 30.0; // perfect closure of the bin
    }

    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many bins open, prefer consolidating;
    // with few bins open, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is the "small" bin — use it up to reduce fragmentation.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Late in the stream, be more conservative: keep gaps small.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins attractive only when no open bin
    // offers a good fit; otherwise keep them slightly penalized.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fills (dead space is the enemy).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, this is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it fits.
            score -= 50.0 + (post_residual - next_item_size) as f64 * -0.5;
            // If next item fills the bin completely after placement, extra reward.
            if post_residual - next_item_size == 0 {
                score -= 300.0;
            }
        } else {
            // Next item does NOT fit: penalize leaving residual that is too small
            // to be useful (dead space for the next step).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare post_residual against mean residual: keeping residuals balanced
    // preserves future packing flexibility.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: if this is the only bin that can fit the item, prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist and could fit the item,
    // unless the item is huge and the fit into existing bins is poor.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0;
        // New bin is more attractive late in the stream when consolidation
        // matters less, and for large items that leave bad residuals elsewhere.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
        if item_size >= 50 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (chain potential).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 * chain_tightness;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving a sliver too small for the next item (dead space risk),
        // scaled by how small the sliver is relative to capacity.
        let sliver = post_residual as f64;
        if sliver > 0.0 && sliver < next_item_size as f64 {
            score += 2.0 * (sliver / bin_capacity as f64) * (1.0 - sliver / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Penalize opening a new bin mildly; more so early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 20.0 * (1.0 - progress);
        // But if the item is huge relative to typical residual, new bin is fine.
        score -= 0.1 * item_size as f64;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    // Mildly prefer bins with larger residual when many bins are open (consolidation).
    score -= 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Waste-avoidance: penalize residual that is small but nonzero (hard-to-use).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and fill fraction
    let pr = post_residual as f64;
    let prn = pr / cap;
    let fill = 1.0 - prn;

    // Non-linear polynomial coupling: reward high fill with a superlinear term
    score -= 40.0 * fill * fill * fill;

    // Smooth interaction between progress and residual: later in the stream,
    // small residuals become more valuable (tight packing matters more)
    score -= 25.0 * fill * fill * t;

    // Penalize residuals that are polynomially "wasted" — dead space grows
    // quadratically with prn, damped as stream progresses (less room to be picky)
    score += 12.0 * prn * prn * (1.0 - 0.5 * t);

    // Cubic coupling of residual with mean residual deviation:
    // prefer bins whose residual is close to the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * fill;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // reward this placement polynomially
    if next_item_size > 0 && next_item_size <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 15.0 * nx * (1.0 - nx) * (1.0 + t);
    }

    // Mild penalty for proliferating bins early in the stream
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that are exactly filled.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space in (0..10) is nearly unusable
    // (items >= 10 in original regime), so penalize small nonzero residuals hard.
    let small_gap = post_residual > 0 && post_residual < 10;
    if small_gap {
        score += 40.0;
    }

    // Quantize post_residual into capacity-fraction classes (harmonic classes).
    // Residuals that are multiples of common item sizes are more reusable.
    let reusable = post_residual % 10 == 0 || post_residual % 20 == 0;
    if reusable && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but imperfectly; reward proportionally to tightness.
        let tight = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - tight / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: dead space risk.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large/fragmented relative to the item.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it competitive only for big items.
        score = bin_capacity as f64 * 0.55 + (item_size as f64) * 0.3;
        // Open new bin early in stream when few bins exist and mean residual is high.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual > 60.0 && progress < 0.5 {
            score -= 30.0;
        }
        // Don't open a new bin if some open bin fits nearly perfectly.
        if bin_residual.saturating_sub(item_size) < 5 && fitting_bins_count > 0 {
            score += 200.0;
        }
    } else {
        // Existing bin: reward tightness relative to item size.
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * fit_ratio;
        // Penalize leaving residual far from mean (fragmentation balancing).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        // Prefer using bins with fewer open alternatives (consolidation).
        if fitting_bins_count <= 2 {
            score -= 8.0;
        }
    }

    // Mild stream-progress term: late in stream, favor closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (item sizes >= 1, but practically small gaps below the typical item
    // floor are wasted). Penalize them super-linearly.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fills that leave room plausibly matching the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover smaller than next item: dead space for the lookahead
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress) * 0.8;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small relative to item or many bins exist.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 || pressure < 0.25 {
            score -= 30.0 + 20.0 * (1.0 - pressure);
        } else {
            score += 15.0 + open_bins_count as f64;
        }
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 30.0 - chain_left * 0.4; // good chain, penalize leftover slack mildly
        } else {
            // next item cannot use the post residual: dead space risk
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when lookahead is absent.
    let dev = post_residual as f64 - mean_residual;
    if next_item_size == 0 {
        score += dev * 0.25;
    } else {
        score += dev * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize near-empty new-bin candidate slightly when decent fits exist elsewhere;
    // but prefer a fresh bin if post_residual would be tiny (bad fit in existing bins).
    if bin_residual == bin_capacity {
        score += 15.0; // default: prefer existing bins
        if post_residual < 10 && bin_residual >= item_size {
            score -= 40.0; // opening fresh bin beats stuffing awkwardly
        }
    }

    // Small waste-avoidance term: exact fills are excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Late-stream tightening: fewer bins matter more as stream completes.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful (below min item size 1..=100
    // means residual < ~20 is nearly dead unless next item is tiny).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling: penalize post_residual that can't fit the next item,
    // reward post_residual that fits next_item_size exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // residual stays useful: reward proportional to how snugly next item fits later
            score -= 12.0 * (nxt / post_residual as f64);
        } else if post_residual > 0 {
            // dead space relative to the lookahead: penalize more early in the stream
            score += (nxt - post_residual as f64) * (1.5 + 2.0 * (1.0 - progress));
        }
        // Perfect two-item closure bonus: item + next item exactly fills residual
        if (item_size + next_item_size) == bin_residual {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize post_residual hard
        score += 10.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty so we don't spread items too thin
    else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(8.0);
    }

    // Global state: prefer bins with residual below mean (more filled bins),
    // penalize dipping into unusually empty bins.
    if (bin_residual as f64) > mean_residual * 1.05 {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    } else {
        score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Too many open bins: encourage consolidation, discourage opening new bins.
    if open_bins_count > 8 {
        score += 2.0 * (open_bins_count as f64 - 8.0).min(20.0);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and no tight fit exists,
        // or when few bins are open. Penalize by default; relax for big items late in stream.
        let base = 45.0
            - 0.35 * item_size as f64
            - 20.0 * progress
            - if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += base.max(-10.0);
    }

    // Slight preference for exact-fill closure overall.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer tight fits (small post-residual), non-linearly scaled
    let mut score = pr as f64;

    // Smooth polynomial coupling between post-residual and stream progress:
    // early on, waste matters less; late, compact bins are critical.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (norm_pr * norm_pr) * cap * 0.3;

    // Penalize mid-range dead space (quadratic bump around half-full residual)
    let dead = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 8.0 * dead * (1.0 - progress);

    // Reward filling a bin nearly exactly (smooth exponential affinity)
    score -= 6.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let tightness = 1.0 - (post_residual as f64 - next_item_size as f64).abs() / cap;
        score -= 4.0 * fits_next * tightness.max(0.0);
        // Penalize leaving a gap just smaller than the next item (unusable sliver)
        let sliver = if (post_residual as f64) < (next_item_size as f64) { 1.0 } else { 0.0 };
        score += 3.0 * sliver * (next_item_size as f64 - post_residual as f64) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 5.0 + 10.0 * (1.0 - fragmentation.min(1.0)) - 20.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quarter / eighth / sixteenth buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tiny dead space is the worst outcome: unusable slivers.
    if post_residual > 0 && post_residual < sixteenth {
        score += 25.0;
    }

    // Class reward: post_residual landing on a "harmonic" residue class
    // (multiples of eighth) is reusable by many item sizes.
    if post_residual % eighth == 0 {
        score -= 12.0;
    } else if post_residual % sixteenth == 0 {
        score -= 6.0;
    }

    // Post-residual in the "medium" band [quarter, 2*quarter) is prime space
    // for typical items; penalize destroying it with a poor fit.
    if post_residual >= quarter && post_residual < 2 * quarter {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or nearly, this placement chains nicely.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use the post-residual: mild penalty scaled
            // by how much space is wasted relative to next item size.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Tightness reward: the smaller the pre-fit residual relative to item,
    // the better the fill.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness.min(1.0);

    // New-bin candidate: neutral-to-slightly-high baseline so it wins only
    // when open bins offer genuinely poor fits. Encourage opening fresh bins
    // early in the stream and when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 18.0
            + 10.0 * progress
            + (open_bins_count as f64).sqrt() * 2.0
            - if next_item_size > 0 && next_item_size >= item_size { 6.0 } else { 0.0 };
    }

    // Mean-residual coupling: when open bins are already slack on average,
    // avoid stuffing this bin if it leaves an awkward residue.
    if post_residual > 0 && post_residual < quarter && (mean_residual / cap) > 0.5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the next item
    // (or any item) are wasted — penalize them quadratically.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap cannot host the lookahead item -> likely dead space.
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        if post_residual < 10 {
            // Very small unusable sliver: heavy quadratic penalty.
            score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 0.8;
        }
    }

    // Reward tight fits (small waste relative to bin capacity).
    let waste = (bin_capacity - post_residual - item_size) as f64;
    score -= 30.0 * (1.0 - waste / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many
    // bins are already open (open-bin pressure) and early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * (1.0 - progress);
    } else {
        // Mild pressure: prefer filling existing bins when many are open.
        score += 0.15 * open_bins_count as f64;
    }

    // Slight preference for bins with residuals near the mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Lookahead synergy: if the post-residual exactly fits the next item,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with non-linear reward.
    score -= (bin_residual as f64 - item_size as f64 + 1.0).powi(2) * 0.02;

    // 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            // Perfect chain: item fits now, next item fits exactly after.
            score -= 45.0 + nxt * 0.3;
        } else if post >= nxt {
            // Next item still fits here: mild reward scaled by closeness.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted residual.
            score += diff * 0.25;
        }
    } else {
        // Last item: just minimize post_residual strongly.
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins that are already low-residual.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin unattractive unless
    // no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Empty bin default score ~ capacity; open bins with post_residual
        // much smaller than capacity win. Penalize new bin more when many
        // bins are already open (avoid bin proliferation).
        score += open_bins_count as f64 * 2.0 + progress * 10.0;
        // If item is large relative to capacity, opening fresh bin is fine.
        score -= item_size as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: reward tight fits quadratically.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * tightness * tightness * bin_capacity as f64;

    // Perfect fit is nearly free.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, this bin is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    }
    // Lookahead conflict: placing here leaves a residual that barely fails the next item,
    // creating dead space; penalize slightly.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins with high mean residual: encourage consolidation into fuller bins.
    if open_bins_count > 3 && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 0.6 * bin_capacity as f64
            + 30.0 * (1.0 - progress)
            - 55.0 * scarcity
            + 2.0 * open_bins_count as f64;
        // If the next item could also pair with this fresh bin, mild bonus.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, non-linearly warped by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Quadratic coupling: large residuals late in stream are penalized more (wasted space)
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction term: smooth preference for tight fits that intensifies over time
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 1.5 * progress);

    // Lookahead coupling: reward residuals that can still hold the next item (smooth, non-piecewise)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_margin = (pr - nx) / cap;
        score -= 5.0 * fit_margin.max(-1.0) * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward scaled by stream position
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mean-residual deviation coupling: penalize bins far from the mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + progress);

    // Mild penalty for opening new bins when many bins are open early
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals that are "nice" multiples / near-multiples of common item classes
    // (e.g. divisible by 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let mut reusability = 0.0f64;
    if pr == 0 {
        reusability = 12.0; // perfect fit: strongly reward
    } else if pr % 50 == 0 {
        reusability = 8.0;
    } else if pr % 25 == 0 {
        reusability = 6.0;
    } else if pr % 20 == 0 {
        reusability = 5.0;
    } else if pr % 10 == 0 {
        reusability = 4.0;
    } else if pr % 5 == 0 {
        reusability = 2.0;
    } else if pr < 10 {
        reusability = 6.0; // tiny dead space: nearly as good as full
    }
    score -= reusability;

    // Penalize awkward residuals via integer-division thresholds.
    // Residual in (0,10) is dead space unless exactly 0; residual in
    // mid ranges is usable. Use quotient of pr / 10 as a harmonic class.
    let class = pr / 10; // 0..=10
    let class_penalty = match class {
        0 => 10.0,       // 1..9: nearly dead space (unless pr==0, already rewarded)
        1 => 6.0,        // 10..19
        2 => 4.0,        // 20..29
        3 => 2.5,        // 30..39
        4 => 1.5,        // 40..49
        5 => 1.0,        // 50..59
        6 => 0.5,        // 60..69
        7 => 0.25,       // 70..79
        8 => 0.1,        // 80..89
        _ => 0.0,        // 90..99: very reusable
    };
    score += class_penalty;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily (harmonic match between classes).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if pr >= next_item_size {
            // next item fits, but leftover after that matters
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 || pr2 == 0 {
                score -= 7.0;
            } else if pr2 < 10 {
                score -= 3.0;
            } else {
                score -= 1.0;
            }
        } else {
            // next item will NOT fit here: mild penalty proportional to mismatch
            let mismatch = (next_item_size - pr) as f64;
            score += 0.05 * mismatch;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: neutral baseline; open a new bin only when
    // all existing fits would leave poor residuals or when mean residual is
    // already fragmented.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: its post_residual == capacity already dominates,
        // add a small adaptive offset based on fragmentation of open bins.
        let frag = if open_bins_count > 0 { mean_residual / (bin_capacity as f64) } else { 0.0 };
        score += 4.0 * frag;
        // late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 3.0 * progress;
    }

    // Prefer bins whose residual is close to the item (tight fit) via
    // harmonic ratio term.
    if bin_residual > 0 {
        let ratio = item_size as f64 / bin_residual as f64;
        score -= 3.0 * ratio * ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward (subtract) to strongly prefer exact closures.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: small non-zero gaps are "unusable" if they
    // can't fit even the smallest plausible item; penalize them hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_useful = if next_item_size > 0 { (next_item_size as f64).min(80.0) } else { 1.0 };
    if post_residual > 0 && (post_residual as f64) < min_useful {
        // Dead space: gap smaller than the next item (or tiny in general).
        score += 30.0 + 10.0 * (1.0 - post_residual as f64 / min_useful) + 20.0 * progress;
    }

    // Moderate gaps that are likely reusable: slight reward relative to baseline.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer filling
    // existing bins when alternatives exist. Weight grows with bin count.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= pressure * (item_size as f64 / bin_capacity as f64) * 6.0;
    } else {
        // New-bin candidate: apply pressure in the opposite direction so opening
        // a bin is only chosen when existing bins score very poorly.
        score += pressure * 3.0 + 15.0;
        // But if the item is large and mean residual is small, opening a bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Reward bins whose residual aligns with the next item (lookahead packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Slight preference for tighter bins overall (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fills post_residual (perfect chaining).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 0.5 {
            score -= 30.0;
        } else if next <= post_residual as f64 {
            // Next item fits: residual gets consumed, good.
            score -= 6.0 * (next / (post_residual as f64 + 1.0));
        } else {
            // Next item cannot use this residual: penalize proportional to wasted space.
            score += 4.0 * (post_residual as f64).min(next) / next;
        }
    }

    // Relative to mean residual: bins with less residual than average are more "committed";
    // prefer filling them rather than leaving them as dead space.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 5.0 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64 > 20.0 && item_size < 40);
        if poor_fit {
            score -= 15.0;
        } else {
            score += 40.0;
        }
        // Late in stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for using more bins when many are open with fragmented space.
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is just above item size.
    let tightness = (bin_residual - item_size.min(bin_residual)) as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Perfect-fill bonus: exact or near-exact fill is gold.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 8.0 * (next_item_size as f64 / 100.0);
            // chain fit: next item leaves little dead space too
            if post_residual - next_item_size <= 10 {
                score -= 8.0;
            }
        } else {
            // penalize leaving a sliver the next item cannot use
            let sliver = post_residual as f64;
            if sliver < next_item_size as f64 && sliver > 0.0 {
                score += 6.0 * (1.0 - sliver / (next_item_size as f64));
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    score -= 5.0 * fullness * progress;

    // Mean-residual coupling: when mean residual is low, wasting space hurts more.
    if mean_residual > 0.0 {
        let waste = post_residual as f64 / mean_residual;
        score += 4.0 * (waste - 1.0).abs().min(3.0);
    }

    // New-bin candidate: neutral-ish baseline, slightly above good fits,
    // but attractive when no open bin fits well (post_residual here = capacity - item).
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        // discourage opening bins early in the stream unless item is large
        score += 10.0 * (1.0 - progress);
        // encourage new bin for large items that would strand small residuals
        if item_size > 50 {
            score -= 8.0;
        }
        // if many bins fit, prefer reusing them
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping.
    let mut score = pr * (1.0 + 0.9 * norm_pr);

    // Smooth stream-progress coupling: early on, tolerate residual waste less;
    // later, tight packing (small post_residual) is rewarded more aggressively.
    let prog_coupling = 0.5 + 1.5 * progress;
    score *= prog_coupling + 0.8 * norm_pr * (1.0 - progress);

    // Reward bins whose post-residual matches the lookahead item (smooth interaction).
    if next > 0.0 {
        let match_term = 1.0 - ((pr - next) / cap).abs();
        score -= 6.0 * match_term * match_term * (0.4 + 0.6 * progress);
    } else {
        // Last item: strongly prefer filling a bin as completely as possible.
        score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Penalize bins with residual far above mean (fragmented state), smooth coupling.
    score += 0.35 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    // Last-chance bin: smooth sigmoid-like reward scaled by item fit quality.
    if fitting_bins_count == 1 {
        let fit_quality = norm_item * (1.0 - norm_pr);
        score -= 5.0 * (0.5 + fit_quality);
    }

    // Mild penalty for spreading across many bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral baseline with slight smooth pressure against
    // opening bins early, but allowing it when the item is large.
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.4 * norm_item) + 4.0 * progress * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small" classes are good (little waste), large classes are bad.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual: treat residual in
    // harmonic bands. Band index k = post_residual / 10 (0..10).
    let band = post_residual / 10;
    // Perfect-fit classes: residuals that are multiples of 5 or 10 are
    // more reusable by typical item sizes.
    let harmonic_bonus = if post_residual % 10 == 0 {
        -6.0
    } else if post_residual % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty grows superlinearly in the upper bands
    // (residual > 50 is "half-empty" waste if we leave it).
    if band >= 5 {
        score += (band as f64 - 4.0) * 4.0 * (1.0 + frac);
    }

    // Coupling with next item: if next item exactly fits post_residual,
    // strongly reward; if next item fits, mild reward; if next item is
    // close to post_residual but doesn't fit, penalize (near-miss waste).
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == post_residual {
            score -= 15.0;
        } else if nxt <= post_residual {
            // how well the leftover after next item lands in harmonic class
            let rem = post_residual - nxt;
            if rem % 10 == 0 {
                score -= 8.0;
            } else if rem % 5 == 0 {
                score -= 4.0;
            } else {
                score -= 1.0;
            }
        } else if nxt > post_residual && nxt - post_residual <= 10 {
            // near-miss: this residual will likely strand
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - frac);
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the item is large relative to capacity or no
    // open bin fits well.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        // base penalty so open bins with decent fits win
        score = cap as f64 * 1.5;
        // large items prefer fresh bins
        score -= size_frac * 120.0;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // many open bins -> discourage spreading
        score += (open_bins_count as f64).sqrt() * 5.0;
        // if mean residual across open bins is small, opening fresh is fine
        score -= (mean_residual / cap).max(0.0) * 20.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can serve the next item too
        }
    }

    // Mild tie-break toward bins with below-average residual (tighter bins first).
    score += ((bin_residual as f64 - mean_residual) / cap) * 2.0;

    // Small modular dither on item class to break ties deterministically.
    score += ((item_size % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any realistic item are wasted.
    // Treat post_residual in (0, 10] as fully dead: penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate gets penalized proportionally to open_bins_count).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But allow new bins early in the stream or when existing residuals are large.
        score -= 0.5 * mean_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    } else {
        // Reward keeping residual near mean to balance bins.
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    // Lookahead: if the next item would fit exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit in leftover: slight penalty for creating stranded space.
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this bin a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if !is_new_bin {
        // ---- 2-step lookahead matching ----
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            // Perfect match: post_residual exactly equals next item size -> strongly reward
            if post_residual as f64 == nxt {
                score -= 60.0;
            }
            // Post residual can still fit the next item: reward closeness to it
            if post_residual >= next_item_size {
                let gap = post_residual as f64 - nxt;
                // Reward tight fits (small gap), scaled by lookahead importance
                score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            } else {
                // Post residual cannot fit next item: penalize dead space,
                // especially when the leftover is small and unusable
                let dead = post_residual as f64;
                score += 12.0 * (dead / 40.0).min(1.0);
            }
        }

        // ---- Relative to mean residual ----
        // Prefer bins whose post residual is below the mean residual
        // (i.e., filling fuller-than-average bins tightens the pool)
        let pr = post_residual as f64;
        score += 0.35 * (pr - mean_residual);

        // ---- Last-chance bonus ----
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // ---- Tightness reward ----
        // Reward small post residuals nonlinearly
        score -= 8.0 * (-pr / 30.0).exp();

        // ---- Late stream: be more aggressive about closing bins tightly ----
        if progress > 0.7 {
            score -= 6.0 * progress;
        }
    } else {
        // ---- New bin candidate ----
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;

        // If no open bin fits, opening a new bin is necessary
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            // The only fitting bin: still prefer using it unless it would waste badly
            let waste = bin_residual as f64 - item_size as f64;
            if waste > 50.0 {
                score -= 40.0;
            }
        }

        // Lookahead: if next item is large and no open bin could hold both,
        // opening fresh space is more attractive
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 20.0;
        }

        // Early in the stream, opening bins is cheaper (more future to amortize)
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual close to item size means low waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are useless dead space
    // (too small for typical items), but reward exact-ish fills.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    } else if pr == 0.0 {
        score -= 40.0; // perfect fit is excellent
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual can't host next item: penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global state coupling: many open bins with large mean residual
    // suggests we should consolidate rather than spread.
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in the stream, be more open to new bins;
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or existing bins are nearly full on average.
    if bin_residual == bin_capacity {
        let avg_fill = mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = (1.0 - avg_fill) * (1.0 - item_frac);
        score += 45.0 * pressure + 10.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: minimize post residual, but with a smooth non-linear penalty
    // that grows superlinearly as post residual approaches unusable sizes.
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth interaction: stream progress amplifies the cost of wasted space,
    // since late in the stream consolidation matters more.
    let progress_coupling = progress * norm_post * (post - norm_post * cap * 0.5);
    score += 1.5 * progress_coupling;

    // Smooth reward for leaving room that matches the next item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (post - nxt).abs();
        let lookahead_reward = (1.0 - fit_gap / cap).max(0.0);
        score -= 8.0 * lookahead_reward * lookahead_reward * (0.5 + progress);
    }

    // Last-chance bin: smooth penalty if we waste a scarce fitting option,
    // scaled by how many bins are open (congestion coupling).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let congestion = (open_bins_count as f64).ln().max(1.0);
        score += 6.0 * congestion * (1.0 - item_size as f64 / cap);
    }

    // Mild smooth pull toward bins whose residual deviates from the mean,
    // encouraging homogenization of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Smooth preference for tighter bins overall (smaller residual = better fit).
    score += 0.5 * norm_post * norm_post * norm_post * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and mod 20
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Dead space penalty: residuals that are hard to fill (small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Harmonic classes: residuals divisible by 10 are "good" classes
    if r10 == 0 {
        score -= 6.0;
    } else if r10 >= 5 {
        score -= 2.0;
    } else {
        score += 4.0;
    }
    // mod 20 refinement
    if r20 == 0 {
        score -= 3.0;
    } else if r20 == 10 {
        score -= 1.5;
    }

    // Integer division thresholds on post_residual
    let q = post_residual / 10;
    if q >= 8 {
        score -= 5.0; // near-empty bin, plenty of room
    } else if q <= 1 && post_residual > 0 {
        score += 8.0; // nearly full bin, waste of a slot
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0;
        }
        // harmonic match: post_residual % next_item_size == 0
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 {
            score -= 12.0; // open bins nearly full -> open fresh bin
        } else {
            score += 20.0 + 15.0 * pressure; // prefer using open bins
        }
    }

    // Progression: early stream, be frugal; late stream, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: penalize bins far from mean (imbalance)
    score += 0.5 * ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space is nearly worthless
    } else if post_residual < 20 {
        score += 15.0; // small gap, hard to reuse
    } else {
        // Larger usable gaps are mildly rewarded relative to post_residual baseline
        score -= 5.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space penalty scaled by how well post_residual could host the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size as f64 {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        } else if next_item_size as f64 <= post_residual as f64 {
            score -= 10.0; // gap remains useful for the lookahead item
        }
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + progress);
    if bin_residual < bin_capacity {
        score -= pressure; // reward using an already-open bin
    } else {
        score += pressure * 0.5; // penalize opening a new bin when pressure is high
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (better consolidation)
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual chains
    // tightly with the next item's size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain (gap == 0) gets the biggest discount.
        score -= 45.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: leftover cannot host the next item.
        score += 10.0 + 0.1 * (post_residual as f64);
    }

    // Last-chance bin: only open bin that fits this item -> strong preference
    // to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Nothing open can fit: opening a new bin is mandatory.
            score -= 100.0;
        } else {
            // Penalize opening a new bin when alternatives exist;
            // penalty scales with how much slack is already floating around.
            score += 25.0 + mean_residual;
        }
    }

    // Mild global pressure: prefer filling bins in bins with below-average
    // residual (tighter bins first), keeping larger residuals for big items.
    score += 0.08 * mean_residual;

    // Slight stream-progression calibration: later in the stream, waste
    // matters more, so tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: subtract more as post_residual shrinks (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that few items could use: residual < 10 is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }
    // Penalize if next item cannot fit here but this bin is otherwise attractive.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin should generally score worse than good fits.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        // But late in the stream, opening fresh bins is cheap to avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidating.
    if mean_residual > (item_size as f64) * 1.5 && bin_residual >= item_size {
        score -= 4.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // Mild penalty for using bins with much larger residual than needed (save big gaps).
    if bin_residual > item_size + 40 {
        score += 2.0;
    }

    // Early stream: slightly discourage hoarding too many bins.
    if step_index < total_items / 10 && open_bins_count > 3 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on (progress~0): mildly favor larger post_residual (keep bins flexible).
    // Late (progress~1): strongly favor small post_residual (tight packing).
    let mut score = pr * (1.0 + 2.0 * progress * progress) - 30.0 * progress * norm_item;

    // Smooth penalty for dead space that is too small to ever be useful,
    // scaled by remaining stream length.
    let dead_weight = (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 20.0 * dead_weight * (1.0 - progress);

    // Reward near-perfect fits with a smooth bump (Gaussian-like on normalized residual).
    score -= 15.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Last-chance bonus: if this is the only fitting bin, penalize alternatives implicitly
    // by rewarding this bin smoothly.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: smooth reward if next item fits in post_residual.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let tightness = 1.0 - ((post_residual as i64 - next_item_size as i64).abs() as f64 / cap);
        score -= 12.0 * fits_next * tightness;
    } else {
        // Last item: maximize tightness only.
        score = pr;
    }

    // Mild dispersion penalty: avoid bins far from mean residual to keep options balanced.
    score += 0.05 * (pr - mean_residual).abs();

    // Slight preference for consolidating into fewer bins as open bin count grows.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is
    // for typical item sizes (1..100). Classes keyed on integer division.
    let class = post_residual / 10; // 0..10 harmonic class
    let phase = post_residual % 10; // fine phase within class

    // Dead-space penalty: residuals in awkward ranges (1..9, 11..19, 21..29)
    // are hard to fill by future items; smooth-fill residuals (0, 50, 100-ish)
    // are valuable. Use a sinusoidal harmonic on the class index.
    let class_f = class as f64;
    let harmonic = ((class_f * std::f64::consts::PI / 5.0).sin()).abs();
    score += harmonic * 12.0;

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward residuals that exactly match plausible next-item sizes.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // reward leaving room for the lookahead item
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // post_residual cannot host the next item: penalize wasted class
            score += 25.0 + phase as f64;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., current bin's post-residual is small/awkward) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = (post_residual as f64).min(1.0); // placeholder to keep types used
        let _ = tight_fit;
        // Prefer opening a fresh bin when mean residual across open bins is low
        // (open bins are mostly full) or when many bins are open and this item
        // would leave a nasty small residual in any of them.
        let nasty = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score = 200.0
            - 120.0 * (1.0 - progress)
            - 3.0 * open_bins_count as f64
            - 0.5 * mean_residual
            + 80.0 * nasty;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can always host the next item: mild bonus
            score -= 20.0;
        }
    }

    // Small refinement: prefer tighter fits within same class via phase.
    score -= phase as f64 * 0.5;

    // Slight global pressure to consolidate into fewer bins early.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are useless.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // perfect fit — strongly favored
    } else if post_residual < 10 {
        // unusable dead space for typical streams: heavy penalty
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        // small gap: risky, likely dead space
        score += 12.0;
    } else if post_residual >= 50 {
        // large leftover is reusable — mild reward
        score -= 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Deviation from mean residual: prefer bins whose residual differs from the mean
    // (pairs large-gap bin with big item, keeps mean spread useful).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // leaves a perfect slot for next item
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 8.0; // next item fits snugly
        } else if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 5.0; // next item won't fit here
        }
    }

    // New-bin candidate: only attractive when item is large or no good fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tight_fit_elsewhere = fitting_bins_count > 0 && post_residual <= 15;
        if tight_fit_elsewhere {
            score += 500.0; // never open a new bin when a tight fit exists
        } else {
            score += 20.0 + 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
            score -= 15.0 * (1.0 - progress); // early on, opening bins is cheap
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference: tightest fit wins.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        if diff < 0.5 {
            score -= 60.0; // exact lookahead match: place here
        } else if post_residual as f64 > look {
            score -= 25.0 / diff; // next item still fits after placement
        } else {
            // next item won't fit: penalize dead space proportionally
            score += 8.0 + diff * 0.15;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins that bring
    // residual toward the mean (balance closing bins evenly).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize very small unusable residuals (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }
    // Perfect closure reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins would leave
    // large dead space or are scarce relative to stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (mean_residual + 1.0);
        // default: discourage opening a new bin
        score = 45.0 + open_pressure * 2.0 - progress * 10.0;
        // if the current item is large relative to capacity, new bin is fine
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // if lookahead won't fit anywhere reasonable, allow a fresh bin
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize creating dead space that cannot fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless it enables a great fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer using bins with below-average residual (consolidate waste).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.05;
    }

    // Slight preference for bins among many open bins (reduce bin count pressure).
    score -= open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // post residual normalized [0,1)

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, waste matters slightly more per unit; later, very small residuals become dead space
    let p = progress;
    let poly = 0.3 + 1.2 * p * p - 0.6 * p * p * p;
    score += norm_pr * norm_pr * poly * cap * 0.15;

    // Reward using bins that are already open (penalize new bins) more strongly late in stream
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    let open_penalty = (open_bins_count as f64).ln().max(1.0);
    if is_new_bin {
        score += 25.0 + 40.0 * p + 5.0 * open_penalty;
    } else {
        score -= 6.0 * open_penalty * (1.0 - norm_pr);
    }

    // Scarcity: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 + 20.0 * p;
    }

    // Lookahead: if next item fits exactly into the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1e-9 {
            score -= 15.0;
        } else if nxt <= pr {
            // next item fits but leaves more waste: mild penalty proportional to leftover
            let left = (pr - nxt) / cap;
            score += 8.0 * left * left * cap * 0.1;
        } else {
            // next item won't fit here: slightly penalize large post residuals
            score += 5.0 * norm_pr * (1.0 + p);
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter than average)
    let dev = (mean_residual - pr) / cap;
    score -= 10.0 * dev * (1.0 - dev * dev).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity-fraction bands.
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50

    // Reward tight fits: exact or near-exact fills get strong discounts.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo arithmetic: dead space that is a multiple of common item sizes
    // (10, 20, 25, 50) is reusable, so discount it.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= (pr / 10) as f64 * 4.0;
    }
    if pr % 25 == 0 {
        score -= 15.0;
    }
    if pr % half == 0 && pr > 0 {
        score -= 20.0;
    }
    // Penalize awkward residuals (prime-ish / not divisible by small classes).
    if pr > 0 && pr % 10 != 0 && pr < 10 {
        score += 25.0;
    }

    // Integer-division thresholds on post_residual: residuals in (0, quarter]
    // are near-dead; penalize unless the discount above already applied.
    if pr > 0 && pr / quarter == 0 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving this residual.
        score += 5.0;
    }

    // Last-chance bin: if only one bin fits, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // residuals are poor (large, awkward) or the item is huge.
    if bin_residual == bin_capacity {
        let awkward_open = mean_residual > 30.0;
        if item_size > 3 * quarter || awkward_open || open_bins_count == 0 {
            score -= 40.0;
        } else {
            score += 150.0;
        }
    }

    // Slight preference for bins below mean residual (filling emptier bins first
    // keeps tight bins for tight items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the smallest item
    // (sizes >= 1, so any gap is technically usable; but gaps < 5 are near-worthless).
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits proportionally (fill ratio of the bin).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize leaving a gap that exactly fails to fit the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it attractive early, expensive late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score = 45.0 + 60.0 * progress + 5.0 * open_bins_count as f64;
        // A new bin is good if the item is huge and nothing fits well.
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild pull toward bins with residual close to the item (best-fit core).
    score += 0.1 * ((bin_residual - item_size) as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) super-linearly.
    if post_residual <= 5 {
        score -= 60.0 - (post_residual as f64) * 8.0;
    } else if post_residual <= 15 {
        score -= 20.0 - (post_residual as f64) * 0.8;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= (30.0 - gap).max(0.0) * 0.9;
        } else {
            // Next item cannot fit here: penalize leaving a mid-sized dead
            // space that likely becomes unusable.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += (next_item_size as f64 - dead) * 0.35;
            }
        }
    }

    // Compare residual against mean residual of open bins: prefer bins that
    // are already relatively full (small residual) to consolidate load.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.25;
    } else {
        score += (residual_f - mean_residual) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the
    // stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 40.0 * progress + open_bins_count as f64 * 2.0;
        // But if the lookahead matches perfectly in a fresh bin, soften it.
        if next_item_size > 0 && (next_item_size + item_size) as f64 >= bin_capacity as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on be conservative, later exploit tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill achieved by this placement.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward high fill more strongly as the stream progresses.
    score -= 30.0 * fill * (0.6 + 0.8 * progress);

    // Penalize small dead space non-linearly: residuals < 10 are nearly unusable
    // (min item size 10), so punish them heavily to encourage exact-ish packing.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Moderate penalty for medium dead space that could still fit lookahead item.
    if post_residual >= 10 {
        let usable = if (next_item_size as u32) > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score -= 6.0 * usable;
        // If the next item fits exactly into the post residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive when decent fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin.
        score += 25.0;
        // If this bin is the only fitting option, opening is unavoidable-ish.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // When many open bins exist with large mean residual, prefer reusing them.
        score += 0.15 * mean_residual + 0.5 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        score += 10.0 * progress;
    } else {
        // Reward tight fits relative to current mean residual of open bins.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Prefer placing large items into bins with proportionally matching residual
    // (best-fit coupling between item and bin slack).
    let ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * ratio * ratio;

    // Slight preference for keeping fewer bins open early (delay bin proliferation).
    if progress < 0.3 {
        score += 0.8 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr;

    // Smooth polynomial coupling with stream progress:
    // early on, waste is cheap; later, residual space becomes more valuable
    let progress_coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress * progress);
    score += 12.0 * progress_coupling;

    // Cubic term: strongly punish mid-range residuals that are neither tiny nor large
    let mid_range = norm_pr * (1.0 - norm_pr);
    score -= 8.0 * mid_range * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * (pr - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        // penalize blocking the next item
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mean residual interaction: placing into a bin far below mean residual
    // (leaving big gaps elsewhere) is mildly encouraged
    score -= 0.5 * (mean_residual - pr).max(0.0) / (1.0 + open_bins_count as f64);

    // New-bin candidate: mild penalty so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 buckets (capacity fractions of 10).
    let r = post_residual % 10;
    let harmonic_bonus = match r {
        0 => 40.0,               // perfect decade fit
        5 => 25.0,               // half-decade usable
        1 | 9 => 5.0,            // nearly decade
        2 | 8 => 2.0,
        _ => 0.0,                // awkward residues
    };
    score -= harmonic_bonus;

    // Integer-division threshold classes on post_residual.
    let q = post_residual / 10;
    if q >= 8 {
        score += 15.0;           // leaving a huge residual: wasteful placement
    } else if q >= 5 {
        score -= 8.0;           // mid residual still valuable
    } else if q == 0 {
        score -= 20.0;          // nearly perfect packing
    }

    // Lookahead coupling: does post_residual serve the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here too: strong reward, scaled by tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - (slack / 40.0) * 10.0;
            // Harmonic chain bonus: both residuals in good classes
            if (post_residual - next_item_size) % 10 <= 2 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: penalize dead space proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 60.0) * 12.0;
            // If residual is so small no future item (min size 1) is likely useful
            if post_residual < 3 {
                score -= 10.0;
            }
        }
    } else {
        // Last item: prefer closing bins as tightly as possible
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Scarcity of fitting bins raises the value of any usable bin.
    if fitting_bins_count >= 2 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Mean residual coupling: placing into a bin far from mean residual
    // balances the pool; reward shrinking below-mean bins.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.15; // below-mean residual (tight bin) slightly favored
    } else {
        score += dev * 0.05;
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    // Many open bins: discourage leaving large residuals scattered.
    if open_bins_count > 4 {
        score += (post_residual as f64 / 100.0) * (open_bins_count as f64 * 0.8);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && next_item_size > mean_residual as u32 { 4.0 } else { 0.0 };
        score += 10.0 + desperation - (fitting_bins_count as f64) * 4.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fill
    } else if post_residual <= 10 {
        // Unusable-ish dead space: strongly penalize.
        score += 300.0 - (post_residual as f64) * 10.0;
    } else if post_residual <= 20 {
        // Marginal gap: moderate penalty.
        score += 60.0 - (post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score += 80.0; // leaves dead space after next item
        } else if post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is above the mean (keeps spread balanced),
    // but only mildly so dead-space logic dominates.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let bad_gap_elsewhere = mean_residual > 0.0 && mean_residual < 12.0;
        if bad_gap_elsewhere && open_bins_count > 0 {
            score -= 100.0;
        } else {
            score += 90.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled relative to capacity.
    score = (post_residual as f64) * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let pr = post_residual as i64;
        let ni = next_item_size as i64;
        let diff = (pr - ni).abs() as f64;
        // Perfect match for the next item: strong reward.
        if pr == ni {
            score -= 60.0;
        } else if ni < pr {
            // Next item fits in the leftover: mild reward proportional to match quality.
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item would NOT fit: penalize leaving a gap that can't serve lookahead.
            score += 15.0 + 0.3 * diff;
        }
        // Bonus if post_residual can hold next item exactly or near-exactly (nonlinear coupling).
        let match_frac = diff / (bin_capacity as f64);
        score -= 20.0 * (-match_frac * 8.0).exp();
    }

    // Relative-to-mean-residual term: prefer bins whose post_residual is below average
    // (compact bins), penalize bins that stay far above mean residual (wasteful).
    let pr_f = post_residual as f64;
    score += 0.5 * (pr_f - mean_residual);

    // Penalize large unusable dead space (post_residual too small for typical future items).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0; // dead space: nothing (min size 1..100 range) may use it reliably
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when no good open bin exists.
    if bin_residual == bin_capacity {
        // Slight penalty so tight fits in existing bins win; reduced when many bins open.
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Small progression-aware tightening: as stream advances, weight tightness more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (non-linear coupling on residual).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else {
        // Penalize dead space quadratically for large leftover gaps.
        score += (post_residual as f64).powi(2) / 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize proportionally to wasted potential
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        // Penalize opening a new bin early in the stream or when many bins are open.
        score += 20.0 + 2.0 * open_bins_count as f64 * 0.5
            + 30.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // But allow new bin if mean residual of open bins is small (fragmentation high)
        // and current item is large relative to typical leftover.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 40.0 + pressure * 0.3;
        }
    } else {
        // Prefer filling bins whose residual is close to item size (best-fit flavor).
        score += (bin_residual - item_size) as f64 * 0.15;
        // Slight preference for fuller bins (small residual) among open bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Time horizon: later in the stream, be greedier about tight fits.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global fragmentation pressure: many open bins with large mean residual
    // favors consolidating into existing bins.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger leftovers; late, punish them harder.
    let progress_weight = 0.4 + 1.6 * progress * progress;
    score += progress_weight * (post * post) / cap;

    // Reward high fill ratio non-linearly.
    score -= 8.0 * fill * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Scarcity pressure: few fitting bins -> favor this bin.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: penalize so it's chosen only when fits are bad,
    // with the penalty decaying as the stream progresses.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0 * (1.0 - 0.5 * progress);
        // If the next item would fit the fresh residual perfectly, soften penalty.
        if next_item_size > 0 && (next_item_size as f64 - post).abs() < 1e-9 {
            penalty -= 20.0;
        }
        // If next item is large relative to typical residual, opening fresh helps.
        if next_item_size as f64 > mean_residual + 10.0 {
            penalty -= 10.0 * progress;
        }
        score += penalty;
    } else {
        // Lookahead: reward bins whose post_residual can host the next item.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0 + 4.0 * (1.0 - post / cap);
        } else if next_item_size > 0 {
            // Dead space for the lookahead item: penalize proportionally.
            let waste = next_item_size as f64 - post;
            score += 0.15 * waste * (1.0 + progress);
        }
    }

    // Mild preference to balance residuals against the mean (smooth coupling).
    score += 0.05 * (post - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

