    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    }

    // Dead-space penalty: residuals in (20, 40) are hard to fill with items >= 10
    if post_residual > 20 && post_residual < 40 {
