            let pair_res = post_residual - next_item_size;
            score -= 20.0 - (pair_res as f64) * 0.3;
        } else {
            // next item won't fit here: penalize wasting the slot
            score += 8.0;
            // bonus if next item is small and could use leftover later
            if next_class == 0 && post_residual >= 10 {
                score -= 4.0;
            }
        }
        // modulo arithmetic: residual divisible into chunks usable by next item
        if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 10.0; // exact tiling possible
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost; attractive only if item is huge
        // or current bins are very fragmented.
        score += 15.0;
        if item_class == 3 {
            score -= 25.0; // huge items prefer fresh bins
        }
        score += (mean_residual / bin_capacity as f64) * 20.0; // more fragmentation -> prefer new bin
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    } else {
        // Prefer filling bins with low residual (compact bins first)
        score += (bin_residual as f64 - mean_residual) * 0.4;
    }

    // Progress-based modulation: early stream, be picky; late stream, close bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual <= 10 {
        score -= 10.0 * (1.0 - progress); // closure more valuable early
    } else {
        score -= 5.0 * progress; // late stream: fill anything
    }

    // Penalize leaving residual that no typical class can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver below min item size
    }

    // Class coupling: large item into large-residual bin is harmonious
    if item_class as f64 * 25.0 <= bin_residual as f64 / 2.0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are dead space; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0 * (1.0 - (post_residual as f64) / 15.0);
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // If this bin can exactly absorb the item, strongly favor it.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, allow opening a new bin for better future packing.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 5.0 * pressure;

    // New-bin candidate: only attractive when the fit into open bins would be
    // poor (large post_residual) or when the next item may need the space.
    if bin_residual == bin_capacity {
        score += 15.0; // baseline cost of opening a new bin
        if post_residual as f64 > mean_residual {
            score -= 10.0; // item is small relative to typical gaps -> fine in a new bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // pairing potential in a fresh bin
            score -= (bin_capacity - item_size - next_item_size) as f64 * 0.3;
        }
    } else {
        // Avoid wasting a large residual on a small item if the next item
        // could use this bin better.
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Slight late-stream bias: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits well into the post-residual space (small leftover after two placements)
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step_waste = post_residual - next_item_size;
        score -= (bin_capacity as f64 - two_step_waste as f64) * 0.35;
        // extra bonus if the two-step leftover is tiny
        if two_step_waste <= 5 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to the shortfall
        let shortfall = next_item_size - post_residual;
        score += shortfall as f64 * 0.6;
    }

    // Penalize creating dead space far from mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Large post-residual is generally bad (wasted space) unless it matches lookahead
    if post_residual > 60 {
        score += (post_residual as f64 - 60.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight bias toward tighter bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / bin_capacity as f64) * (10.0 - 10.0 * progress);

    // Prefer consolidating into fewer bins
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * fill_ratio * fill_ratio * (item_size as f64);

    // Penalize unusable dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowding penalty: with many open bins, prefer reusing existing ones over new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 8.0 + 12.0 * progress + 0.5 * open_bins_count as f64;
        // Opening a new bin is fine if mean residual across open bins is large (fragmented state).
        if mean_residual > 40.0 && fitting_bins_count > 0 {
            score -= 5.0;
        }
    } else {
        // Existing bin: slight reward scaled by how full the bin already is.
        score -= 1.5 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    // Global state: if mean residual is low, avoid spreading waste; prefer best fit.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Time horizon: early in stream, be more liberal with new bins; late, consolidate.
    score -= (1.0 - progress) * 2.0 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (0.5 + progress) - pr_norm * progress * 0.8;
    score += poly * cap * 0.6;

    // Reward tight fits, stronger later in the stream (smooth sigmoid-ish term)
    let tight = 1.0 - pr_norm;
    score -= tight * tight * (20.0 + 30.0 * progress);

    // Penalize waste relative to mean residual across open bins
    score += (pr - mean_residual).powi(2) / (cap * 4.0);

    // Last-chance bin bonus (only bin that fits)
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space the next item can use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 15.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += (nx - pr).min(cap) * 0.3;
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bucket into deciles of capacity.
    let class = (post_residual * 10) / bin_capacity; // 0..10
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: harmonic classes 0-2 (residual < 30) get strong bonuses.
    match class {
        0 => score -= 40.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 5.0,
        4 => score -= 2.0,
        _ => {}
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain completion).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt_class = (next_item_size * 10) / bin_capacity;
            // Prefer bins whose leftover class matches the next item's class magnitude.
            score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
            // Penalize if next item cannot fit anywhere else later (dead space risk).
            if next_item_size > post_residual && class >= 3 {
                score += 6.0;
            }
            let _ = nxt_class;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 20.0;
        }
    }

    // New-bin candidate: penalize opening a bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 30.0 - 25.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer consolidation into open bins.
        score += 20.0 * progress;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild penalty for wasting space relative to mean residual (avoid hoarding big holes).
    if post_residual as f64 > mean_residual + 20.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer bins that end up tight (low post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps in the awkward mid-range (unusable for typical items) get a
    // milder penalty, scaled by how awkward they are.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills (post_residual <= 2) strongly.
    if post_residual <= 2 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; also slightly favor bins whose
    // residual is below the mean (denser bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // item fits poorly everywhere else. Give it a moderate default score
    // so tight fits in existing bins beat it.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream with few bins, opening fresh can be fine.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect chain -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect 2-chain fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 45.0; // perfect lookahead match
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - diff / bin_capacity as f64).powi(2);
        } else {
            // next item won't fit here; dead space penalty grows with gap
            score += 8.0 + 0.35 * diff;
        }
    } else {
        // Last item: prefer tightest possible fit
        score -= 5.0;
    }

    // Penalize creating very small unusable slivers (dead space < min item ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward filling bins tighter than the current mean residual
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize opening a new bin when other bins fit, unless residual is very low
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still supports the lookahead
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted opportunity.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // If current item leaves a lot of space and next item is large, opening fresh is fine.
        if next_item_size > 0 && post_residual > next_item_size as u32 {
            score -= 20.0;
        }
        // If the item is huge relative to capacity, fresh bin is natural.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Few open bins with large mean residual -> prefer reusing.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 5.0;
    }

    // Time horizon: early in the stream, be more willing to open bins (future flexibility);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 5.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Coupling: tight fit matters more when bins are scarce relative to items.
    let scarcity = open_bins_count as f64 / (total_items.max(1) as f64);
    score -= 20.0 * fit_ratio * scarcity.min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - 0.5 * norm_pr * (1.0 - progress);
    score += 30.0 * poly;

    // Favor tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += 8.0 + 12.0 * progress;
        } else {
            score -= 5.0 * (1.0 - norm_pr);
        }
    }

    // New-bin candidate: mild penalty early, growing acceptance later
    if bin_residual == bin_capacity {
        score += 15.0 - 30.0 * progress;
    }

    // Dead-space penalty scaled by mean residual dispersion
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small moduli.
    let r4 = post_residual % 4;
    let r10 = post_residual % 10;
    let r5 = post_residual % 5;

    // Residuals that are "harmonically useful" for typical item sizes (multiples of 5/10).
    if r10 == 0 && post_residual > 0 {
        score -= 6.0; // residual aligns with common item sizes
    } else if r5 == 0 && post_residual > 0 {
        score -= 3.0;
    } else {
        // Odd / prime-ish residuals are dead space; penalize.
        score += 2.0 + (r4 as f64) * 0.75;
    }

    // Very small unusable post_residual is fine (bin nearly full).
    if post_residual <= 2 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Lookahead coupling: does next item fit exactly or partially into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 15.0; // perfect pair with lookahead
            } else if slack % 10 == 0 {
                score -= 9.0;
            } else if slack % 5 == 0 {
                score -= 5.0;
            } else if slack < 10 {
                score += 1.0;
            }
        } else {
            // Next item cannot use this residual; penalize proportionally to waste.
            let waste = next_item_size as f64 - post_residual as f64;
            score += (waste / 20.0).min(6.0);
        }
    }

    // Integer-division threshold classes on post_residual.
    let cls = post_residual / 10; // class 0..10
    score += match cls {
        0 => -4.0,           // 0-9: almost closed
        1 => 0.0,            // 10-19: small gap
        2 => -2.5,           // 20-29: fits medium items
        3 | 4 => -1.5,       // 30-49
        5 | 6 => -3.0,       // 50-69: versatile
        _ => 1.0,            // large residual: better keep for big items
    };

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Best-fit pressure among many candidates: tighten toward exact fill.
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 8.0;
        let late = (step_index as f64) / (total_items.max(1) as f64);
        if crowded || open_bins_count == 0 {
            score -= 4.0 + late * 3.0;
        } else {
            score += 8.0 + mean_residual * 0.5; // prefer filling open bins
        }
    }

    // Mild preference to spread across bins when many are open with big residuals.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10, minimum item size) are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Partially usable small gaps (10..=20) are also risky.
    else if post_residual <= 20 && post_residual > 0 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual == 0 is perfect).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Prefer bins whose residual is close to the item (relative fit quality).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post-residual is nonzero but cannot hold the next item, slight penalty.
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin; tuned so poor fits elsewhere lose.
        score = 45.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer using an existing bin unless the fit there is poor.
        // New bin starts with a high score that can be reduced when
        // existing bins would leave a lot of dead space.
        score = bin_capacity as f64 * 0.75 + post_residual as f64 * 0.5;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches
    // next_item_size exactly (item fills the bin perfectly next step).
    if next_item_size > 0 {
        let post = post_residual as i64;
        let nxt = next_item_size as i64;
        let diff = (post - nxt).abs() as f64;
        if post == nxt {
            // Perfect 2-step completion: strong reward.
            score -= 60.0;
        } else if post > nxt {
            // Next item fits after this one: partial reward scaled by closeness.
            let closeness = 1.0 - diff / (bin_capacity as f64);
            score -= 25.0 * closeness;
        } else {
            // Next item would NOT fit in the residual: penalize dead space
            // that blocks the lookahead item.
            score += 15.0 + diff * 0.3;
        }

        // Also reward residual that can hold a fraction of next item well:
        // split-fit bonus when post_residual is at least half of next item.
        if post >= nxt / 2 && post < nxt {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize post_residual (already the base).
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "tight" bins; placing there to exhaust them is good.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / (bin_capacity as f64);
    } else {
        score += 4.0 * (res - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Late-stream pressure: as the stream progresses, avoid leaving many
    // half-empty bins; tighten selection.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (res / bin_capacity as f64);

    // Small penalty proportional to wasted fraction of the bin.
    score += (res / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: late in the stream, tighten up (favor tight fits more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor small post-residual, amplified late.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * (0.6 + 0.8 * progress);

    // Penalize dead space that is too small for typical future items
    // (residual in (0, next_item_size) is wasted for the lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Perfect-fit bonus: exact fill.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into bins already below mean residual
    // (i.e., emptier bins get filled to balance residuals).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Lookahead coupling: reward if the post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // New-bin candidate: baseline cost of opening a bin, modulated by how badly
    // existing bins would fit (large post_residual on open bins) and stream stage.
    if bin_residual == bin_capacity {
        let mut open_cost = 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            // If some open bin leaves a large unusable remainder, opening is fine.
            open_cost -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
        // Early stream: opening bins is cheap (builds a pool); late: expensive.
        if progress < 0.15 {
            open_cost -= 12.0;
        }
        score += open_cost;
    }

    // Mild penalty for leaving residual in a narrow "hard-to-fill" band (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + t * t) + norm_pr * (0.5 + t);
    score += 8.0 * poly;

    // Reward tight fits, more so later in the stream
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * tightness * (1.0 + 2.0 * t) * 6.0;

    // Penalize dead space relative to mean residual
    score += 2.0 * (pr - mean_residual) / cap * (1.0 + t);

    // Last-chance bin: strong reward for using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 + t);
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 3.0 * (next_item_size as f64 / cap);
    }

    // New-bin candidate handling: acceptable early or when existing bins are crowded
    if is_new_bin {
        let crowding = mean_residual / cap;
        let penalty = 20.0 * (1.0 - t) * (1.0 - t) - 6.0 * crowding * t;
        score += penalty.max(-8.0);
    }

    // Mild penalty for many open bins to discourage bin proliferation
    score += (open_bins_count as f64).sqrt() * 0.3 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes are golden.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Class A: perfect fit — reward heavily.
    if post == 0 {
        score -= 1000.0;
    }
    // Class B: post residual falls in small "fillable" bands (<=20): usable by
    // typical small items later, so mildly reward.
    else if post <= 20 {
        score -= 30.0;
    }
    // Class C: mid residuals (21..=40) are moderately useful.
    else if post <= 40 {
        score -= 10.0;
    }
    // Class D: large residuals (41..=60) are semi-dead space.
    else if post <= 60 {
        score += 15.0;
    }
    // Class E: huge residuals (>60) suggest we wasted a big bin on a small item.
    else {
        score += 40.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 align with
    // item granularity, making them easier to fill later.
    if post % 10 == 0 && post > 0 {
        score -= 12.0;
    } else if post % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0; // awkward off-grid residual
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if (post as u32) >= next_item_size {
            // Next item nests here — strong reward, scaled by tightness.
            let slack = post as f64 - next_item_size as f64;
            score -= 25.0 - slack * 0.3;
            // Exact nesting (post == next) is ideal.
            if post as u32 == next_item_size {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; penalize proportional to overshoot.
            let overshoot = next_item_size as f64 - post as f64;
            score += overshoot * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tighter fits via residual dominance.
        score += 0.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good
    // home (large residual elsewhere) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin: wasteful if decent open bins exist.
        let mut new_bin_cost = 45.0 + 5.0 * open_bins_count as f64;
        // Late in the stream, opening bins is fine (no future to amortize).
        new_bin_cost *= 1.0 - 0.4 * progress;
        // If mean residual of open bins is small, open bins are crowded —
        // a fresh bin becomes more attractive.
        new_bin_cost -= (mean_residual * 0.4).clamp(0.0, 40.0);
        score += new_bin_cost;
        // Fresh bin keeps full capacity; slight bonus for big upcoming items.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Tightness reward: the smaller the leftover relative to capacity, the better.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 8.0;

    // Mild preference to keep bin count low when many bins are open.
    if bin_residual < bin_capacity && post_residual < bin_residual / 2 {
        score -= 5.0; // halving residual = efficient packing
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // size are worthless; penalize them quadratically.
    if post_residual < 10 {
        score += 25.0 + (post_residual as f64) * 2.0;
    }

    // Dead space relative to the lookahead item: a gap the next item cannot
    // use is likely permanent waste.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 12.0 + 0.15 * (post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins exist;
    // slightly encourage consolidation when bin count is low.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (filling emptier bins first keeps
    // tighter bins available).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    // Mild stream-progression term: tighten behavior as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item still fits after placement (chain continuation bonus).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64;
    }
    // Penalize residual that next item cannot use (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual of open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: acceptable only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 200.0
            + 2.0 * open_bins_count as f64
            + (1.0 - (step_index as f64 / total_items.max(1) as f64)) * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize leaving residual that no typical next item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space wedge
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in stream, be conservative (favor filling existing bins);
    // late in stream, allow more freedom.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Global residual pressure: if mean residual is high, prefer filling bins with large residuals.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Penalize opening new bins when many bins already open.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        // but if nothing fits well elsewhere, opening can win
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // reserve fresh bin for upcoming large item
        }
    }

    // Mild reward for bins already partially filled (avoid bin proliferation).
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nr = next_item_size as f64;
    let fit = fitting_bins_count as f64;

    // Normalized post-residual ratio
    let pr_ratio = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tighten bins more aggressively (penalize leftover space harder)
    let tightness = 1.0 + 2.0 * progress * progress;
    score += tightness * pr_ratio * pr_ratio * cap * 0.5;

    // Reward near-perfect fits smoothly (quadratic decay around zero residual)
    let perfect = (1.0 - pr_ratio).powf(6.0);
    score -= 12.0 * perfect * (1.0 + progress);

    // Lookahead coupling: smooth polynomial reward when the next item fits the post-residual
    if nr > 0.0 {
        let slack = pr - nr;
        if slack >= 0.0 {
            let closeness = 1.0 - (slack / cap).powf(2.0);
            score -= 6.0 * closeness * closeness * (0.5 + progress);
        } else {
            let miss = (-slack / cap).powf(2.0);
            score += 4.0 * miss * (1.0 - progress);
        }
    }

    // Penalize wasting the last fitting bin (smooth penalty scaled by scarcity)
    if fit >= 1.0 {
        let scarcity = 1.0 / fit;
        score += 8.0 * scarcity * pr_ratio * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open
    let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * mean_residual / cap;
    score -= 3.0 * open_pressure * (1.0 - pr_ratio);

    // New-bin candidate: only attractive when no open bin is a good smooth fit
    if bin_residual == bin_capacity {
        let mean_tight = 1.0 - (mean_residual / cap);
        score += 5.0 + 10.0 * mean_tight * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items sized 1..100, capacity 100.
    // Class 0: perfect fit (post_residual == 0) -> huge reward.
    // Class 1: tiny dead space (<= 5) -> strong reward.
    // Class 2: medium leftover (6..20) -> mild reward.
    // Class 3: large leftover (> 20) -> penalize (wasteful but reusable).
    let class = match post_residual {
        0 => 0u8,
        1..=5 => 1,
        6..=20 => 2,
        _ => 3,
    };
    match class {
        0 => score -= 60.0,
        1 => score -= 30.0,
        2 => score -= 8.0,
        _ => score += 6.0,
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item-size granularities (10, 20, 25, 50) are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
            // next item leaves a harmonic residual too?
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this leftover: dead-space risk scales
            // with how much of the residual is stranded.
            let stranded = post_residual as f64;
            score += stranded * 0.15;
            if stranded > 30.0 { score += 5.0; }
        }
    } else {
        // Last item: prefer tightest fit, ignore future reusability.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening for a single item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has large post_residual;
    // make it unattractive unless no open bin fits well (post_residual
    // penalty already dominates), with a mild pull toward consolidation.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    } else {
        // Favor filling existing bins more as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress;
    }

    // Prefer bins below the mean residual (tighter bins get filled first),
    // keeping looser bins available for larger future items.
    score += (post_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps nonlinearly.
    // Gaps below ~25 are hard to fill for typical item sizes.
    if post_residual > 0 {
        let dead = if post_residual < 25 {
            (25.0 - post_residual as f64) * 4.0
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward using a bin whose residual would otherwise be wasted
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: strongly prefer it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity; it gets penalized)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins
        score += 20.0 + open_bins_count as f64 * 8.0 * (0.5 + progress);
    } else {
        // Existing bin: slight reward scaled by how many bins are open
        score -= open_bins_count as f64 * 2.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item barely misses the post residual, penalize slightly
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Prefer bins tighter than the mean residual (compact bins)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        let ndiff = diff as f64;
        if diff == 0 {
            // Perfect 2-step fit: huge reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward decays with the gap.
            score -= 40.0 * (1.0 - ndiff / bin_capacity as f64).powf(3.0);
            // Small extra nudge for tight-but-fitting gaps.
            if diff <= 5 {
                score -= 8.0;
            }
        } else {
            // Next item cannot fit: penalize proportionally to the shortfall.
            score += 10.0 + 0.5 * ndiff;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - pr);
    }

    // Non-linear waste penalty: large residuals are increasingly bad.
    score += 0.05 * pr * pr / bin_capacity as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        // As stream progresses, prefer closing out open bins over opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty + 20.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can perfectly serve the next item too.
            if item_size + next_item_size <= bin_capacity {
                score -= 15.0;
            }
        }
    }

    // Slight preference for bins with larger residual before placement
    // (denser packing of already-opened bins).
    score -= 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, this placement chains well.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Dead space risk if next item cannot use the leftover.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // Opening a new bin is attractive if it can host the next item too.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    }

    // Time horizon: later in the stream, be more conservative (prefer filling bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if mean_residual > item_size as f64 * 1.5 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post_residual (tight fits score low)
    let mut score = post;

    // Non-linear polynomial shaping of post_residual: penalize mid-range waste,
    // strongly reward near-zero residual (quartic dip at 0).
    let x = post / cap;
    score += 30.0 * x * x - 40.0 * x * x * x * x;

    // Perfect-fit reward: cubic coupling pulling score down as post -> 0
    score -= 25.0 * (1.0 - x).powi(3) * (item_size as f64 / cap);

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post - nx).abs();
        score -= 20.0 * (-diff / 15.0).exp();
        // smooth interaction: residual-progress coupling with lookahead size
        score += 5.0 * x * (nx / cap) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: bin_residual == bin_capacity means empty bin.
    // Prefer it only late in the stream or when post_residual of a placement
    // would be very wasteful relative to capacity.
    if bin_residual == bin_capacity {
        let waste_pressure = (post / cap).powi(2);
        score += 8.0 + 30.0 * (1.0 - progress) - 25.0 * waste_pressure;
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: penalize bins deviating from mean residual
    // (keeps bin states homogeneous), scaled smoothly by progress.
    let dev = (post - mean_residual).abs() / cap;
    score += 10.0 * dev * dev * (0.5 + progress);

    // Slight preference for using more-full bins early (best-fit bias)
    score -= 5.0 * (1.0 - x) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near capacity multiples (0, small) are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_frac = pr / cap; // fraction of capacity wasted

    // Class A: perfect fit (post_residual == 0) -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class B: tiny residue classes (1..=10) -> near-perfect
        if post_residual <= 10 {
            score -= 120.0;
        }
        // Class C: residue in "dead zone" 31..50 -> unusable for typical items, penalize
        if post_residual >= 31 && post_residual <= 50 {
            score += 60.0;
        }
        // Harmonic divisibility: does next item fit exactly into post_residual?
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if next_item_size == post_residual {
                score -= 400.0; // chain of perfect fits
            } else if next_item_size <= post_residual {
                let chain_res = post_residual - next_item_size;
                // reward chains that end in small residue
                if chain_res <= 10 {
                    score -= 80.0;
                } else if chain_res >= 31 && chain_res <= 50 {
                    score += 25.0;
                }
                // harmonic ratio: next item divides residual nicely (integer division quotient)
                let q = post_residual / next_item_size.max(1);
                if q >= 2 {
                    score -= 15.0 * q as f64; // multiple future items can stack here
                }
            } else {
                // next item cannot use this residual: residual likely dead
                score += 20.0;
            }
        }
    }

    // Last-chance bin: only bin that fits -> reward strongly to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin has high raw residual; make it a fallback.
    if bin_residual == bin_capacity {
        // attractive only if existing bins are heavily fragmented or none fit well
        score = 0.5 * cap + 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open new bin
        }
        if next_item_size > 0 && (next_item_size as f64) >= 0.7 * cap {
            score -= 40.0; // big next item: fresh bin useful
        }
        return score;
    }

    // Tightness coupling: prefer bins whose residual is close to item size (best-fit core)
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score += 30.0 * tightness;

    // Progression: later in stream, be greedier about packing tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 25.0 * progress * (1.0 - pr_frac);

    // Mean residual divergence: placing into a bin far below mean residual consolidates
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps left after placement are wasted.
    // Quadratic penalty grows as post_residual shrinks toward unusable sizes.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Penalize small leftovers heavily (dead space), scaled by capacity.
        let deadness = 1.0 - (pr / bin_capacity as f64);
        score += 3.0 * deadness * deadness * (bin_capacity as f64 - pr);
        // Harsh penalty for residuals below 10 (near-unusable slivers).
        if pr < 10.0 {
            score += 60.0 + 4.0 * (10.0 - pr);
        } else if pr < 25.0 {
            score += 15.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to item size (fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill * fill;

    // Open bins pressure: discourage spreading across many open bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // placing in this open bin would leave a bad gap AND the item is large.
    if bin_residual == bin_capacity {
        // Neutral base for the fresh bin.
        score = (bin_capacity - item_size) as f64;
        // Favor opening a new bin for large items (they pair well with future items).
        if item_size >= 50 {
            score -= 10.0;
        }
        // If many bins are open, resist opening more.
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item would NOT fit the post residual but would fit a fresh bin,
    // slightly penalize blocking it.
    if next_item_size > post_residual && bin_residual != bin_capacity {
        score += 5.0;
    }

    // Early stream: be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: look ahead more aggressively later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: perfect match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            // Perfect 2-step fit: strongly reward.
            score -= 60.0 + 40.0 * progress;
        } else if nxt <= pr {
            // Next item fits: reward proportional to tightness of the pair.
            let pair_tightness = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * pair_tightness + 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leaving dead space beyond next item.
            let dead = pr - nxt;
            score += 0.5 * dead;
        }
    } else {
        // Last item: minimize leftover residual.
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins whose post residual is below average
    // (keeps large residuals available for large future items).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let waste_new = post_residual as f64;
        score += 25.0 + 0.2 * waste_new;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 20.0; // an open bin already has room; don't open a new one
        }
    }

    // Prefer tighter fits overall (small post residual relative to capacity).
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 100.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits (small post_residual already dominates).

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize leaving a residual that is too small for typical future items
        // (dead space below the minimum plausible item size).
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 0.35 * dead;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are already open (consolidation pressure) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 4.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    }

    // Prefer bins whose residual is below the current mean residual
    // (i.e., fill the emptiest-fitting bins first, keeping tight bins tight).
    let deviation = mean_residual - bin_residual as f64;
    score += 0.15 * deviation;

    // Mild reward for bins that become perfectly full.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Early stream: be slightly greedy toward tight fits to build dense bins;
    // late stream: emphasize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits, with non-linear (quartic) shaping of wasted space.
    let mut score = pr as f64 * (1.0 + 2.0 * x * x * (1.0 - x));

    // Smooth polynomial coupling with stream progress: early on tolerate slack,
    // later punish residual waste more aggressively.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score *= 1.0 + 0.6 * p2 + 0.4 * p3;

    // Reward near-exact fills smoothly (small post residual => bonus).
    let tightness = (1.0 - x).powi(6);
    score -= 8.0 * tightness;

    // Last-chance bin: strong smooth discount when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if the next item fits the post residual, reward;
    // smooth via quadratic kernel on the gap.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = (-gap * gap / (cap * cap * 0.25)).exp();
        score -= 6.0 * fit_kernel;
    }

    // Mean-residual coupling: placing into a bin far from the mean residual
    // is penalized smoothly (keeps bin profiles homogeneous).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild pressure against scattering across many bins as stream progresses.
    score += 0.05 * (open_bins_count as f64) * progress;

    // New-bin candidate: default neutral-ish score; make it attractive only
    // when current bin fits are all poor (large residuals) or late stream.
    if bin_residual == bin_capacity {
        let poor_fits = (x - 0.5) * (x - 0.5); // x==1 here, so this is 0.25
        score = cap * (0.9 + 0.3 * progress) - 4.0 * poor_fits * (1.0 + progress);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo classes: residuals divisible by 5 or 10 are more reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    } else {
        // awkward residue penalty, scaled by how small the residual is
        score += (10.0 - (pr % 10) as f64) * (10.0 / (pr as f64 + 5.0));
    }

    // Dead-space penalty: residual too small for the minimum item (1..100 range)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Integer-division thresholds: how many "typical" items still fit
    let slots = pr / 10; // coarse granularity slots
    score -= slots as f64 * 1.5;

    // Lookahead coupling: does post_residual fit the next item exactly / at all?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n == pr {
            score -= 120.0;
        } else if n <= pr {
            let nr = pr - n;
            if nr % 10 == 0 {
                score -= 15.0;
            } else if nr < 10 {
                score += 6.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (post_residual as f64 / cap) * 60.0; // fresh bin has full residual
        let desperation = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        let bad_fit = if item_size as f64 > mean_residual + 5.0 { 15.0 } else { 0.0 };
        score = score - tight + desperation + bad_fit + (1.0 - progress) * 10.0;
    }

    // Mild penalty for fragmenting bins relative to mean residual
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but practically < min item size ~10) are wasted. Penalize heavily.
    let min_item: f64 = 10.0;
    if (post_residual as f64) < min_item {
        score += 200.0 * (min_item - post_residual as f64);
    } else if (post_residual as f64) < 2.0 * min_item {
        // Small-but-usable gaps are risky: mildly penalize.
        score += 0.5 * (2.0 * min_item - post_residual as f64);
    }

    // Reward tight fits: fraction of bin filled by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins early,
    // but relax near the end of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = 2.0 * (1.0 - progress);
    score += pressure * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.2 * ((bin_residual as f64 - item_size as f64).abs());

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else, or the stream is early and many
    // more items are coming (keep flexibility for large future items).
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0;
        let big_next = next_item_size as f64 > bin_capacity as f64 - mean_residual.max(0.0);
        if poor_fit_everywhere || (big_next && progress < 0.5) {
            score -= 40.0;
        } else {
            // Default: prefer reusing an existing bin.
            score += 60.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (creates a perfect follow-up).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover likely dead space.
        score += 0.3 * post_residual as f64;
    }

    // Slight preference for bins below mean residual (filling emptier bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect two-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Partial lookahead credit: how close post_residual is to next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += gap * 0.35;
    }

    // Penalize small dead space (< next typical item) more than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: prefer it only when no good fit exists (large item, big residual waste).
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * (1.0 - progress);
        // But if the item would leave awkward residual in any existing bin, new bin is fine.
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 12.0;
        }
    }

    // Prefer filling bins that are already mostly full (tight packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual nonlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; slight penalty scaled by wasted space.
        score += 0.1 * (post_residual as f64).min(next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins that are already relatively full (small residual).
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    // New-bin candidate handling: make empty bins attractive only when fit quality
    // elsewhere is poor or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_pressure = (mean_residual - item_size as f64).max(0.0);
        score += 30.0 - 0.5 * poor_fit_pressure - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> discourage
    // leaving medium dead space; encourage consolidation.
    if open_bins_count > 4 && mean_residual > 20.0 {
        score += 0.05 * (post_residual as f64 - mean_residual).abs();
    }

    // Late-stream consolidation: near the end, prefer tightest possible fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let mean_res = mean_residual / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize large post_residual more as stream matures (dead space grows costly)
    score += 0.25 * pr * pr / cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item)
    score -= 12.0 * fit_ratio * (1.0 - fit_ratio) * (1.0 + progress);

    // Penalize when bin residual deviates from mean residual (imbalance)
    score += 3.0 * ((bin_residual as f64 / cap - mean_res).abs());

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * (open_bins_count as f64).ln() * (pr / cap);

    // New-bin candidate: make it moderately attractive only when early or very tight fits unavailable
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues divisible by common
    // item sizes (10, 20, 25, 50) are "reusable classes" and get rewarded.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus += 60.0; // perfect fit: zero waste
    } else {
        if pr % 50 == 0 { class_bonus += 25.0; }
        if pr % 25 == 0 { class_bonus += 12.0; }
        if pr % 20 == 0 { class_bonus += 10.0; }
        if pr % 10 == 0 { class_bonus += 8.0; }
        // small residuals are dead space unless they complete the bin
        if pr < 10 { class_bonus -= 30.0 * (10 - pr) as f64 / 10.0; }
        // awkward mid-range residuals (11..19, 21..24) are least reusable
        if pr > 10 && pr < 20 { class_bonus -= 6.0; }
        if pr > 20 && pr < 25 { class_bonus -= 4.0; }
        // large residuals are easy to fill later: mild reward
        if pr >= 60 { class_bonus += 6.0; }
    }
    score -= class_bonus;

    // Lookahead coupling: does the next item's harmonic class match the
    // residual left behind? If next_item divides (or nearly divides) the
    // residual, this placement chains nicely.
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            if pr % n == 0 {
                score -= 18.0; // next item exactly tiles the leftover
            } else {
                let slack = (pr % n) as f64;
                score -= 12.0 * (1.0 - slack / n as f64); // near-tiling reward
            }
        } else {
            // next item won't fit here; leftover must serve later items.
            // penalize proportionally to how stranded the residual is.
            score += 8.0 * (n - pr) as f64 / cap;
        }
    } else {
        // last item: prefer tight closure
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the current item is large or no bin fits well.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // opening fresh is good for big items (they'd wreck small residuals anyway)
        score -= 20.0 * frac;
        // but discourage opening new bins when many bins already fit the item
        score += 3.0 * (fitting_bins_count as f64);
        // early in the stream, fresh bins are cheap; later, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Density term: reward filling a large fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 30.0 * fill * fill;

    // Mean-residual context: when the fleet of open bins is already loose
    // (high mean residual), slightly discourage spreading; prefer tight bins.
    score += 0.15 * (mean_residual - (bin_residual as f64));

    // Mild penalty for proliferating open bins mid-stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual < 10 {
        score += 60.0; // dead space below minimum item size is pure waste
    } else if post_residual <= 20 {
        score += 25.0; // barely usable gap
    }

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: only attractive if no open bin fits well
    // (large residual left open, or current fit would waste a lot).
    if bin_residual == bin_capacity {
        if post_residual >= 60 {
            score -= 25.0; // big item, fresh bin is fine
        } else {
            score += 35.0; // prefer existing bins for small items
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // next item will need another bin anyway
    }

    // Mild progress adaptation: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Mean residual context: prefer bins that don't deviate wildly from the mean residual.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after two placements
            let two_step_left = post_residual - next_item_size;
            score += 0.5 * two_step_left as f64;
            if two_step_left == 0 {
                score -= 200.0;
            }
        } else {
            // next item won't fit here: penalize small dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.3 * (next_item_size as f64 - dead);
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let escape_needed = next_item_size > 0
            && fitting_bins_count > 0
            && (post_residual as f64) > 0.0;
        if escape_needed {
            score += 120.0; // discourage opening new bin when fits exist
        } else {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Penalize leaving a gap just below the next item size.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 15.0 {
                score += 8.0 * (1.0 - gap / 15.0);
            }
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 5.0;
    }

    // Time horizon: early in the stream, be more conservative about filling bins
    // (keep flexibility); late in the stream, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer reusing
    // bins with large residuals (avoid fragmenting); few open bins -> be lenient.
    if open_bins_count > 0 {
        let mean_res = mean_residual;
        if (bin_residual as f64) < mean_res {
            score += 6.0 * (mean_res - bin_residual as f64) / bin_capacity as f64;
        } else {
            score -= 3.0 * (bin_residual as f64 - mean_res) / bin_capacity as f64;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits are poor.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let scarcity_penalty = if fitting_bins_count <= 1 { -20.0 } else { 0.0 };
        let big_item_bonus = if item_size > bin_capacity / 2 { -10.0 } else { 0.0 };
        score += base_penalty + scarcity_penalty + big_item_bonus;
    }

    // Mild preference for bins with residuals just above item size (near-perfect fits).
    let slack = (bin_residual - item_size) as f64;
    score += 0.05 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let cap_f = bin_capacity as f64;

    // Reward tight fits (smooth quadratic coupling with progress)
    score -= 12.0 * fit_ratio * fit_ratio * (0.5 + 0.5 * progress);

    // Penalize large dead space non-linearly
    let dead = post_residual as f64 / cap_f;
    score += 20.0 * dead * dead * dead;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0 + 8.0 * (next_item_size as f64 / cap_f) * (1.0 - progress);
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Prefer bins below mean residual (consolidate waste)
    score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by large chunk sizes
    // are more reusable; penalize "dead" odd residuals.
    let pr = post_residual;
    if pr > 0 {
        let mut reusability = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 { reusability += 1.0; }
        }
        score -= reusability * 6.0;
        // tiny unusable slivers
        if pr < 10 { score += (10 - pr) as f64 * 1.5; }
    } else {
        score -= 25.0; // perfect fit
    }

    // Lookahead: if next item fits the post residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 8.0 - (gap as f64).min(8.0);
            if gap < 10 { score += 2.0; } // near-exact chain
        } else {
            // next item won't fit here: slight penalty proportional to leftover
            score += (next_item_size - pr).min(20) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: base penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream or many open bins with small mean residual -> prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual >= item_size as f64 { score += 10.0; }
        if progress < 0.2 { score += 10.0; }
        // Big item into fresh bin is fine
        if item_size >= bin_capacity / 2 { score -= 15.0; }
    }

    // Prefer tightest fit among comparable residuals (fraction of capacity used).
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 5.0;

    // Many open bins: discourage spreading, reward consolidation.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Modulo coupling between item and residual classes (harmonic alignment).
    if pr > 0 && (item_size + pr) % 100 == 0 { score -= 10.0; }
    if pr > 0 && pr % 2 == 1 && item_size % 2 == 1 && pr > item_size { score += 1.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit even the smallest plausible item are wasted.
    // Treat gaps < 10 as fully dead, and 10..=20 as partially dead.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Penalty on creating many open bins: encourage closing out bins.
    score += 3.0 * (open_bins_count as f64).sqrt();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }

    // Slight preference toward bins with below-average residual (consolidating space).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Early in stream, be a bit more willing to open bins (score new bins lower).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward exact match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: next item exactly fills this bin
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here: good cascade
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement: penalize dead space
            let waste = (post_residual as f64) / (bin_residual as f64).max(1.0);
            score += 20.0 * waste;
        }
    }

    // Relative to mean residual: favor bins already below-average residual
    // (consolidating tight bins), penalize draining unusually-roomy bins
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 8.0 * (1.0 - res_f / mean_residual.max(1.0));
    } else {
        score += 6.0 * ((res_f - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strong penalty to open a new bin instead
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Penalize opening new bins, more so early when few bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 40.0 - 15.0 * progress
            + if next_item_size > 0 && item_size + next_item_size > bin_capacity { 0.0 } else { 25.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item also fits in the resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // Penalize leaving residual that is too small for the next item
            // (dead space relative to lookahead), scaled by how close it is.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new empty bin, more so when many bins are already open
    // and could still absorb items.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if this is the only viable option (no open bin fits), the
        // last-chance penalty on other bins makes it relatively attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Global pressure: if mean residual across open bins is small, prefer
    // placements that keep residual usable (larger post_residual is worse).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.05 * (1.0 - progress);

    // Late in the stream, discourage fragmentation: penalize mid-size residuals
    // that are unlikely to fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0).max(1.0) } else { 0.0 };

    // Tightness of fit: fraction of the bin consumed by this item
    let fill_ratio = item_size as f64 / cap;
    let residual_ratio = post_residual as f64 / cap;

    // Reward good fits: smooth non-linear coupling of fill ratio with progress
    // Later in the stream, tight fits become more valuable (fewer chances left).
    let tight_reward = fill_ratio * fill_ratio * (1.0 - residual_ratio) * (1.0 + 2.0 * progress) * 40.0;
    score -= tight_reward;

    // Penalize unusable dead space: small post_residual that likely cannot host future items.
    // Dead-space penalty grows non-linearly as post_residual shrinks below typical item sizes.
    let dead = if post_residual > 0 {
        let pr = post_residual as f64;
        // smooth decay: how "wasted" the leftover is relative to capacity
        let waste = (1.0 - pr / cap).powi(6);
        waste * (1.0 + progress) * 30.0
    } else {
        0.0
    };
    score += dead;

    // Perfect closure bonus (bin exactly filled)
    if post_residual == 0 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead coupling: if the next item fits into the post_residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let smooth = ((post_residual as f64 - nxt) / cap).powi(2);
            score -= 25.0 * (1.0 - smooth);
        } else {
            // leftover too small for the known next item: penalize proportionally to closeness
            let miss = 1.0 - (nxt - post_residual as f64) / cap;
            score += 20.0 * miss * miss;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, scaled by how much of the bin would be used.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * fill_ratio;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // open bins exist with decent mean residual and early/mid stream.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (open_bins_count as f64 + 3.0)).sqrt();
        score += 45.0 + 30.0 * openness * (1.0 - progress) + 0.15 * mean_residual;
        // But if item is large relative to capacity, new bin is less bad
        score -= 30.0 * fill_ratio * fill_ratio;
    }

    // Mild preference for bins with below-average residual (consolidate emptier space usage)
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * diff * diff.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that are "useful" ---
    // Classify post_residual into coarse buckets via integer division (capacity / 4).
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..=4
    match post_class {
        0 => score -= 18.0,                       // tiny dead space: excellent fit
        1 => score -= 6.0,                        // quarter leftover: good
        2 => score += 2.0,                        // half leftover: mediocre
        3 => score += 8.0,                        // wasteful
        _ => score += 14.0,                       // barely placed anything
    }

    // Modulo-10 harmonic: residuals divisible by 10 pair well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit the post residual exactly or nicely?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;                        // perfect follow-up fit
        } else if next_item_size <= post_residual {
            // Harmonic ratio: next/post fraction near 1 is best
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * ratio;
            // modulo classes matching (both in same 10-bucket) get bonus
            if (next_item_size / 10) == (post_residual / 10) {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize more if this was the only fitting bin
            let progress = step_index as f64 / total_items.max(1) as f64;
            let w = 6.0 + 6.0 * progress;
            score += w * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Last-chance bin logic: if this is the only fitting bin, strongly prefer using it
    // unless post_residual would be a terrible class (dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_class == 0 {
            score -= 8.0; // perfect: fill the last fitting bin with tiny waste
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are quite full
        // (mean residual low) or many bins already struggle to fit.
        let mean_r = mean_residual;
        // Reward new bin when existing bins are cramped; penalize otherwise.
        score += (mean_r / bin_capacity as f64) * 20.0 - 10.0;
        // Early stream: prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
        // If next item is large, a fresh bin is safer.
        if next_item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Fragmentation guard: avoid leaving residuals that nothing in [1,100] typically uses
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-zero residual is fine (dead but tiny)
    } else if post_residual >= 10 && post_residual <= 20 && post_residual % 5 != 0 {
        score += 6.0; // awkward mid-range fragment
    }

    // Balance pressure: many open bins -> tighten selection, keep mean residual low.
    if open_bins_count > 4 {
        score += (post_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat residuals below a "useful threshold" as increasingly costly (quadratic).
    let useful_threshold = 30.0;
    if (post_residual as f64) < useful_threshold && post_residual > 0 {
        let gap = useful_threshold - post_residual as f64;
        score += gap * gap * 2.0;
    }

    // Reward filling bins tightly relative to their residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 50.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins over opening new ones.
    score += open_bins_count as f64 * 3.0;

    // New-bin candidate: empty bin. Only attractive if the item is large
    // or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 150.0 + open_bins_count as f64 * 5.0;
        // If item is huge relative to capacity, new bin is reasonable.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 100.0;
        }
        // Lookahead: if next item is large too, having a fresh bin helps.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) > bin_capacity as f64 {
            score -= 40.0;
        }
    }

    // Lookahead synergy: if next item exactly fits the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    }
    // Penalize if post_residual can't fit the (known) next item and is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 60.0;
    }

    // Slight preference for bins below mean residual (balancing load).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // 2-step lookahead: strongly reward if the next item exactly fills the post_residual,
    // reward if it fits, penalize if the leftover is dead space relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if nxt <= pr {
            // next item fits: better the tighter the future fit
            score -= 25.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit here: leftover risks being dead space
            let waste = pr / bin_capacity as f64;
            score += 20.0 * waste;
            // extra penalty if the leftover is smaller than the smallest plausible item
            if pr < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just minimize post_residual (already base) with slight tightening
        score += 0.5;
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly; scale with how good the
    // average open-bin fit is.
    if bin_residual == bin_capacity {
        score += 40.0;
        // if open bins are on average quite full/fragmented, opening new is less bad
        score -= 0.3 * mean_residual;
        // late in the stream, prefer consolidating into existing bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
    } else {
        // Reward placing into bins that are already relatively full (below-mean residual)
        if (mean_residual - bin_residual as f64).abs() > 1e-9 {
            score -= 0.5 * (mean_residual - bin_residual as f64);
        }
    }

    // Mild penalty for very small post_residual that can't serve typical future items
    // unless it's exactly 0 (perfect closure is best).
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfectly closed bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / min_useful as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; mild penalty for wasting the gap.
            score += 5.0;
        }
    }

    // Prefer bins with below-average residual (consolidate emptiness elsewhere).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be picky (penalize loose fits); late, fill anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive when current fit is bad or bin is nearly full elsewhere.
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.4;
        let scarcity = fitting_bins_count <= 1;
        if bad_fit && !scarcity {
            score -= 20.0;
        } else if scarcity {
            score += 15.0; // still prefer squeezing into the last fitting bin
        } else {
            score += 30.0;
        }
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize dead space below smallest plausible item, smoothly scaled by progress
    let dead = (norm_pr - (next_item_size as f64 / cap)).max(0.0);
    score += 25.0 * dead * dead * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly early, less late (favor consolidation early)
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) * (1.0 - progress) - 5.0 * progress;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0 * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced packing)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // Slight penalty for spreading across many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions (C/4, C/2, 3C/4)
    let q = (bin_capacity / 4).max(1);
    let class = post_residual / q; // 0..=4 harmonic band

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= q / 2 {
        score -= 35.0;
    } else if post_residual <= q {
        score -= 18.0;
    } else if class == 2 {
        score -= 6.0;
    }

    // Penalize dead space that no typical item can use:
    // post_residual in awkward band (just above q, i.e. > q but <= 2q minus small margin)
    if post_residual > q && post_residual < 2 * q - 5 {
        score += 10.0;
    }

    // Modulo coupling with next item: does the next item fit harmonically?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward keeping room for it
            let slack = post_residual - next_item_size;
            score -= 12.0 + (q as f64 - slack as f64).abs() * 0.2;
        } else {
            // next item won't fit: penalize leaving tight-but-wasted space
            let gap = next_item_size - post_residual;
            if gap <= q {
                score += 8.0 + gap as f64 * 0.3;
            }
        }
        // modulo harmony: next_item_size divides residual class nicely
        if next_item_size % q == post_residual % q && post_residual >= next_item_size {
            score -= 7.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > bin_capacity as f64 * 0.5;
        let few_options = fitting_bins_count == 0;
        if large_item || few_options || progress < 0.15 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Mild pull toward bins with residuals near the item size (good fill)
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.05;

    // Mean residual coupling: prefer bins deviating from mean toward smaller residual
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit post_residual but post_residual is tiny, mild extra penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 * (next_item_size - post_residual) as f64 / 10.0;
    }

    // Prefer bins with below-average residual (leave larger residual bins for larger items).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make it moderately unattractive unless open-bin fits are bad,
    // so a fresh bin is chosen only when avoiding dead space is worth it.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / tight fits (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space quadratically, scaled by capacity.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * dead * bin_capacity as f64;
    }

    // 2-step lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain fit: huge reward.
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves some slack: reward proportional to tightness.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 120.0 - 0.8 * slack_after_next;
        } else {
            // Next item cannot follow in this bin: mild penalty,
            // stronger when the leftover is small and unusable.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: bins far below mean residual are tight,
    // prefer packing into them (they are closest to being closed out).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when item is large relative to
    // capacity or stream is early; otherwise keep it costly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill = item_size as f64 / bin_capacity as f64;
        score += 80.0 - 60.0 * fill - 20.0 * progress;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    if open_bins_count > 0 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += 3.0 * tightness * (1.0 + progress);

    // Penalize dead space that cannot fit the average next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else if post_residual == next_item_size {
            score -= 6.0; // perfect lookahead fit
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0 * (1.0 - tightness);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins below mean residual are "fuller", favor them.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere (large item, high mean residual, many bins).
    if bin_residual == bin_capacity {
        let waste_penalty = (bin_capacity - item_size) as f64;
        let mut nb = waste_penalty * 0.9;
        nb += (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 4.0; // new bin can still host next item
        }
        if fitting_bins_count == 0 {
            nb -= 100.0; // forced new bin
        }
        // Early in stream, opening bins is cheaper; later, consolidate.
        nb += 20.0 * (1.0 - progress);
        score += nb;
    }

    // Slight preference for bins whose residual stays "usable" (>= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr * norm_pr);

    // Squared post-residual term: penalize large dead space superlinearly
    score += 0.35 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Tight fit reward: cubic falloff of residual
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: reward if next item fits in post-residual
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        if nxs <= pr {
            let fit_ratio = nxs / pr;
            score -= 8.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);
        } else {
            score += 5.0 * (nxs - pr) / cap;
        }
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Mean residual interaction: prefer bins deviating below mean residual (tighter bins)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev - 6.0 * dev;

    // New-bin candidate: penalize opening a new bin mildly, more so early in stream
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes mod capacity fractions
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit, best possible
    } else {
        // classify residual into harmonic bands: small unusable slivers are bad
        if pr <= 10 {
            score += 15.0; // tiny dead space, nearly unusable
        } else if pr <= 25 {
            score += 5.0; // marginal zone
        } else if pr <= 50 {
            score -= 3.0; // half-capacity class, still useful
        } else {
            score -= 8.0; // large residual, very reusable
        }
    }

    // Integer division coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // quotient of how many next items could chain here
            let chain = pr / next_item_size;
            score -= 4.0 * chain as f64;
        } else {
            // next item cannot fit here: penalize proportionally to waste
            let gap = (next_item_size - pr) as f64;
            score += 2.0 + gap / bin_capacity as f64 * 10.0;
        }
        // harmonic class of next_item_size relative to capacity
        let nk = next_item_size;
        if nk > 50 && pr < nk {
            score += 6.0; // big next item, keep large bins free
        }
    }

    // Last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit = mean_residual / bin_capacity as f64;
        // open new bin if existing bins are fragmented (low mean residual utility)
        score += 20.0 - 25.0 * avg_fit - 10.0 * (1.0 - progress);
        // harmonic modulo on item size: prefer new bin for awkward medium items
        if item_size % 3 == 0 && item_size > 40 {
            score -= 4.0;
        }
    }

    // Reward packing into bins tighter than mean residual (compactness seeking)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.15;
        } else {
            score += (-diff) * 0.10;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: any leftover gap smaller than the smallest
        // plausible item (<= 10) is essentially unusable dead space.
        if post_residual < 10 {
            score += 500.0;
        }
        // Moderate gaps (10..=20) are risky: only next_item_size <= gap can use them.
        else if post_residual < 20 {
            if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
                score -= 30.0; // lookahead item can fill the gap
            } else {
                score += 120.0; // likely dead space
            }
        }
        // Larger gaps: reward if the lookahead item fits well into the gap.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 60.0; // next item nearly fills the residual
            } else {
                score -= 20.0;
            }
        }
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 80.0 * tightness;

    // Open-bin pressure: when many bins are open, discourage spreading; when few
    // bins are open, mildly encourage reusing them instead of opening new ones.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else (large item, few fitting bins) or early in
    // the stream with many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.7;
        let spread_pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        if poor_fit || (fitting_bins_count <= 2 && progress > 0.3) {
            score -= 150.0 + 10.0 * spread_pressure;
        } else {
            score += 250.0 + 20.0 * spread_pressure; // keep using existing bins
        }
    }

    // Slight preference toward bins below mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here later: mild reward scaled by how close the fit is
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + slack);
        } else {
            // next item cannot use post residual: penalize dead space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    } else {
        // last item: just minimize post residual
        score += 0.0;
    }

    // Compare post residual against mean residual across open bins:
    // leaving less than average residual is good (compact bins), more is wasteful
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin slightly when decent fits exist,
    // but reward it if the item is large and residuals are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64;
        if tight {
            score -= 50.0 * progress;
        } else {
            score += 80.0;
        }
    }

    // Small penalty for wasting large chunks of residual on tiny items
    if item_size < 20 && post_residual > 60 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space: next item cannot fit into the leftover.
            let dead = next_item_size - post_residual;
            score += 0.9 * dead as f64;
        } else {
            // Leftover can accommodate the next item: reward.
            let slack = post_residual - next_item_size;
            score -= 0.35 * slack as f64;
            // Perfect chain fit bonus.
            if slack == 0 {
                score -= 6.0;
            }
        }
    } else {
        // Last item: only post_residual matters, tighten hard.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper (room to grow).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many open bins have large residuals, opening new bins wastes capacity.
        let mean_gap = mean_residual - post_residual as f64;
        if mean_gap > 0.0 {
            score += 0.6 * mean_gap;
        }
        // If no existing bin fits well, reduce the new-bin penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit refinement).
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.15 * fit_gap;
        // Prefer using bins with below-average residual (consolidate fuller bins).
        let avg_gap = bin_residual as f64 - mean_residual;
        score += 0.05 * avg_gap;
    }

    // Mild pressure to keep the number of open bins low late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.4 * open_bins_count as f64 * progress;

    // Non-linear coupling: squashed post-residual term to sharply punish mid-range waste.
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let sz = item_size as f64;

    // Base: post residual (tighter fit preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, dead space is tolerable; late, every unit of residual costs more.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * progress * progress;
    score += 30.0 * coupling;

    // Reward filling a bin exactly / near-exact fit via smooth sigmoid-like term
    let tightness = (sz / r).clamp(0.0, 1.0);
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Last chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Penalize opening new bins when many open bins already exist and mean residual is large
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        // Reward keeping mean residual balanced (avoid fragmenting)
        let imbalance = (mean_residual - pr).abs() / cap;
        score += 5.0 * imbalance * imbalance;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // penalize leaving residual that next item cannot use (dead space tendency)
        score += 4.0 * (pr / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post_residual falls into
    // "harmonically useful" small classes (divisors of capacity: 1,2,4,5,10,20,25,50).
    let harmonic: [u32; 8] = [1, 2, 4, 5, 10, 20, 25, 50];
    let mut harmonic_bonus = 0.0;
    for (k, &h) in harmonic.iter().enumerate() {
        if post_residual == h {
            harmonic_bonus = 40.0 + 4.0 * (8 - k) as f64;
        }
    }
    score -= harmonic_bonus;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space: residuals that no future item (>=1) can pair into
    // a harmonically clean class, i.e. post_residual in awkward mid-range.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny slivers are nearly perfect
    } else if post_residual >= 30 && post_residual <= 45 {
        score += 12.0; // awkward dead zone
    }

    // Modulo-class coupling on next_item_size: if the next item exactly
    // consumes the post_residual, this placement chains perfectly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    }
    // Next item fits with small harmonic remainder.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 10 {
            score -= 20.0 - rem as f64;
        } else {
            score += 5.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover: leftover becomes dead space.
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // New-bin candidate handling: empty bin is a fallback. Penalize it
    // moderately so decent fits win, but not so much that a bad fit
    // (large dead space) is chosen over fresh capacity.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0 + mean_residual * 0.15;
        score = 55.0 + pressure;
        // If item is large relative to capacity, new bin is more attractive.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // If next item is large, keep current bins' space for it.
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Late-stream tightening: minimize waste more aggressively near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never serve typical
    // items (1..=100, min item 1) are heavily penalized.
    let dead = if post_residual == 0 {
        0.0 // perfect fit is ideal
    } else if post_residual < 10 {
        60.0 // tiny unusable gap
    } else if post_residual < 25 {
        30.0 // poor gap, fits almost nothing useful
    } else if post_residual < 50 {
        10.0
    } else {
        0.0
    };
    score += dead;

    // Reward near-perfect fits (post_residual small relative to item).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into
    // new/partially filled bins; consolidate instead.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 + progress);
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: default mild penalty so it only wins when open bins
    // would create severe dead space or the fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * progress;
        // But if the item is huge, a fresh bin is often the right call.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by this placement's dead space, penalize.
    if next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Prefer bins below mean residual (tighter bins first) to keep large
    // residuals available for large future items.
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it slightly unattractive by default, but allow
    // opening a new bin when the best fit would leave unusable dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nx).abs();
        // Perfect 2-step fit: strong reward.
        if diff < 0.5 {
            score -= 30.0;
        } else {
            // Penalize dead space that next item cannot use.
            let waste = (pr - nx).max(0.0);
            score += 0.35 * waste;
            // Mild reward if next item still fits with little slack.
            if pr >= nx {
                score -= 0.10 * nx;
            }
            // If next item cannot fit here at all, penalize proportionally
            // to how much space is stranded.
            if pr < nx {
                score += 0.25 * pr;
            }
        }
        // Coupling with mean residual: prefer bins whose post state
        // tracks the fleet average (keeps future options balanced).
        score += 0.08 * (pr - mean_residual).abs();
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Tight fits (small post residual) are generally good, but avoid
    // creating tiny unusable slivers below the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer closing bins tightly (waste matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.30 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize tight fits that strand space.
            score += 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fill_pressure = (bin_capacity as f64 - mean_residual).max(0.0);
        let poor_options = (fitting_bins_count == 0) as f64
            || (mean_residual < item_size as f64 * 0.5);
        let _ = poor_options;
        score += 400.0; // base cost of opening a new bin
        score -= avg_fill_pressure * 0.5;
        score -= progress * 50.0; // late in stream, consolidation matters more
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 100.0; // fresh bin helps large upcoming items
        }
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += (bin_residual as f64) * 0.3;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Slight tilt toward bins below mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic post-residual penalty modulated by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction: dead space penalized more heavily late in the stream
    score += 8.0 * norm_pr.powi(3) * progress;

    // Reward bins whose residual after placement matches the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs() / cap;
        score -= 10.0 * (-fit_gap * fit_gap * 20.0).exp() * (0.4 + 0.6 * progress);
    }

    // Last-chance bonus: smooth sigmoid on fitting_bins_count == 1
    let last_chance = 1.0 / (1.0 + (-(fitting_bins_count as f64 - 1.5)).exp());
    score -= 15.0 * last_chance;

    // Coupling with mean residual: penalize bins far from the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild preference for using existing bins over opening new ones, weakening over time
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 6.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: post_residual modulo buckets. Residuals that are
    // multiples of small divisors are more reusable by future items.
    let pr = post_residual as u32;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        -2.0
    } else {
        4.0 // odd residuals are harder to fill
    };
    score += class_bonus;

    // Integer-division threshold: small dead space (< 10) is nearly unusable
    // given item sizes; penalize it strongly.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward heavily; if next item cannot fit, penalize proportionally.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == pr {
            score -= 40.0;
        } else if nxt < pr {
            let leftover = pr - nxt;
            score -= 10.0 - (leftover as f64).min(10.0);
        } else {
            score += ((nxt - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when existing residuals
    // are poor (high mean residual spread) or few bins fit the item.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        score = cap * 0.9 + mean_frac * 30.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // pairing potential with next item
            if item_size + next_item_size <= bin_capacity {
                score -= 15.0;
            }
        }
    }

    // Mild progression term: later in stream, tighten packing more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    // Penalize bins whose residual is far from the mean (fragmentation).
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item.
    let dead_threshold = 9.0; // below ~10 nothing fits comfortably
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tightness relative to residual (fraction of bin consumed now)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Penalize leaving a gap that the lookahead item cannot use
    if next_item_size > 0 {
        if post_residual > 0 && next_item_size > post_residual {
            score += 8.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: more open bins -> favor consolidating into existing bins,
    // and make the fresh-bin candidate (residual == capacity) less attractive
    // unless the fit into existing bins is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: neutral post_residual is bin_capacity.
        score -= bin_capacity as f64 * 0.5; // offset so it competes fairly
        // Opening a new bin is penalized more when many bins are open
        score += open_bins_count as f64 * 6.0;
        // Early in stream, opening bins is cheaper; later, consolidation matters
        score += (1.0 - progress) * 15.0;
    } else {
        // Existing bin gets a mild consolidation bonus
        score -= 4.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item
    // size (best-fit style), penalize outliers
    let resid_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += resid_gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect chain: next item exactly fills remaining space
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: reward tightest fit
        score -= 30.0;
    }

    // Penalize dead space relative to mean residual (fragmentation pressure)
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.35 * mean_gap.max(0.0);
    score -= 0.15 * (-mean_gap).max(0.0);

    // Last-chance bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening unless current fit is very poor
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 30.0 * fit_quality;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can chain next item too
        }
    }

    // Late in stream: prefer filling existing bins aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly as the item grows.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * (item_size as f64 / 100.0);

    // Penalize leaving dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0; // still reusable zone
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // extra reward if next item fits snugly afterwards too
            let post2 = post_residual - next_item_size;
            if post2 < 10 { score -= 5.0; }
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: prefer open bins generally, but allow
    // opening a fresh bin when existing fits are poor (large post residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (open_bins_count as f64).ln().max(1.0);
        let mut open_cost = 30.0 + 10.0 * congestion * (1.0 - 0.3 * progress);
        // If no open bin fits well, opening is attractive: compare with best-fit proxy.
        if post_residual == 0 {
            open_cost -= 20.0; // perfect fit in a fresh bin (item == 100 case)
        }
        if next_item_size > 0 && bin_capacity as f64 - item_size as f64 >= next_item_size as f64 {
            open_cost -= 10.0;
        }
        score += open_cost;
    } else {
        // Mild penalty for bins whose residual is far from mean (fragmentation signal).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for older bins (close them out) early in the stream.
    score += 3.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, but with a non-linear (quadratic) penalty
    // so that large dead space is punished super-linearly.
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are more acceptable (bins can still be filled);
    // late in the stream, dead space is costly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits with a smooth cubic term in (1 - pr_norm).
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * tightness;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        let next_fits = (pr >= next_item_size as f64) as i32 as f64;
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 15.0 * next_fits * (1.0 - gap) * (1.0 - gap);
    }

    // Mild penalty for spreading across many open bins; smooth in open_bins_count.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / cap.max(1.0));
    score += 0.5 * bin_pressure * (0.5 + progress);

    // New-bin candidate adjustment: an empty bin has high post-residual, which the
    // quadratic term already penalizes; add a mild extra penalty so new bins are
    // opened only when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    let q = post_residual / 10; // 0..10 decile classes
    // Penalize residuals that are "awkward": small but non-zero (dead space)
    if post_residual > 0 {
        let class_penalty = match q {
            0 => 25.0,                 // 1-9: nearly unusable
            1 => 12.0,                 // 10-19
            2 => 6.0,                  // 20-29
            3 => 3.0,                  // 30-39
            4 => 1.0,                  // 40-49
            5 => 0.0,                  // 50-59: sweet spot for medium items
            6 => -1.0,                 // 60-69
            7 => -2.0,                 // 70-79
            8 => -3.0,                 // 80-89
            _ => -4.0,                 // 90-100: roomy bin
        };
        score += class_penalty;
    }

    // Modular coupling: post_residual mod 20 — residuals that are multiples of 20
    // tend to accept common item sizes (10..80 streams) cleanly.
    let m = post_residual % 20;
    if m == 0 && post_residual > 0 {
        score -= 2.5;
    } else if m >= 11 {
        score += 1.5;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            // Harmonic pairing: next item leaves another multiple-of-10 residual
            let nm = post_residual.saturating_sub(next_item_size) % 10;
            if nm == 0 {
                score -= 3.0;
            } else {
                score += (nm as f64) * 0.4;
            }
        } else {
            // next item cannot go here: mild penalty scaled by overflow size
            let over = (next_item_size - post_residual) as f64;
            score += (over / 20.0).min(3.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + (bin_residual as f64 / cap) * 3.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless the current placement would
        // create tiny dead space in every existing bin. Base cost of a new bin:
        score += 30.0;
        // But if the item is large (harmonic class of item itself), a fresh bin
        // is fine since big items pair well with anything.
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            score -= 5.0; // consecutive big items: fresh bin good
        }
    }

    // Tight-fit reward: near-perfect fills are excellent.
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Slight preference for fuller bins overall (mean residual coupling):
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Progress-aware tiebreak: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 3.0;
    }

    // Prefer bins whose residual is below mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post residual can fit next item (lookahead friendly)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 1.5;
    }
    // Post residual too small for next item: dead space penalty, worse if tiny
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 150.0 * (10.0 - dead) / 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin unless current bin would leave near-perfect fit
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 300.0 * (1.0 - tightness);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 50.0;
        }
    }

    // Late in the stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: fill fraction of the bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 18.0 * fill * fill;

    // Leftover usability: if the next item fits into the post-residual,
    // this placement chains nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / cap);
        } else {
            // Dead space relative to the lookahead item.
            let waste = (post_residual as f64).min(next_item_size as f64);
            score += 0.35 * waste;
        }
    }

    // Last chance: only one open bin fits the item; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with slack: discourage spreading, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score += 0.02 * open_bins_count as f64 * (1.0 - progress);
    }

    // Compare bin residual to mean residual: prefer bins with below-average
    // residual (tighter bins) to keep the pool of usable space balanced.
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // and would leave big unusable fragments elsewhere.
    if bin_residual == bin_capacity {
        let base = 30.0 - 10.0 * fill;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let time_discount = 12.0 * (1.0 - progress);
        // If no bin fits, opening is mandatory (fitting_bins_count==0 case handled
        // implicitly since only the new bin is a candidate).
        if fitting_bins_count == 0 {
            score -= 1000.0;
        } else {
            score += (base - time_discount).max(0.0);
        }
    }

    // Small global smoothing term.
    score += 0.001 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;
    // Reward tight fits, scaled by progress
    score -= 8.0 * (1.0 - norm_pr) * (0.5 + progress);
    // Penalize last-chance bins less strongly as stream progresses
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress) + 4.0;
    }
    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        if post_residual >= next_item_size {
            let nx_norm = nxs / cap;
            score -= 6.0 * nx_norm * (1.0 - norm_pr * nx_norm);
        } else {
            score += 5.0 * (nxs / cap) * norm_pr;
        }
    }
    // Mean residual coupling: prefer bins deviating favorably from mean
    score += 0.05 * (pr - mean_residual);
    // Mild penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are gold, tiny remainders are silver,
    // mid-range remainders are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 8.0;
    } else if pr <= 50 {
        // awkward mid-range: penalize extra, scaled by class
        score += 10.0 + (50 - pr) as f64 * 0.2;
    }

    // Modulo arithmetic: remainders that are multiples of common item sizes are reusable.
    let reusable = |r: u32| (r % 10 == 0) || (r % 20 == 0) || (r % 25 == 0);
    if pr > 0 && reusable(pr) {
        score -= 12.0;
    }
    if pr > 0 && !reusable(pr) && pr < 50 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - slack * 0.3;
        } else {
            // next item cannot use this bin's remainder: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / cap;
        let mut penalty = 55.0;
        penalty -= (1.0 - crowded) * 40.0;   // low mean residual => new bin more OK
        penalty -= progress * 10.0;
        if fitting_bins_count > 2 {
            penalty += 20.0; // plenty of alternatives, keep new bin closed
        }
        if item_size >= 70 {
            penalty -= 15.0; // huge items justify fresh bins
        }
        score += penalty;
    }

    // Prefer bins whose residual is already below average (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Slight preference to keep number of open bins from exploding early.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (items >= 10, but interface allows >= 1) are
    // heavily penalized. Treat "unusable gap" as post_residual in 1..=10.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        // The smaller and more trapped the gap, the worse.
        score += (11.0 - pr as f64) * 12.0;
    } else if pr > 10 && pr <= 20 {
        // Marginal zone: mildly risky gap.
        score += (21.0 - pr as f64) * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (pr as f64) / (bin_capacity as f64);
        score -= tightness * item_size as f64 * 0.8;
    }

    // Perfect fit: strong reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; opening yet another bin is costly.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: an empty bin should only win when the
    // fit into existing bins is poor (large post_residual) or the item
    // would leave a dead gap in every open bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when few bins are open
        // (early stream: spreading is cheap) or when the stream is long.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + progress * 20.0;
        // If this is the only candidate that fits, opening a new bin is
        // effectively forced; make it attractive.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // If the next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that can fit the
    // item, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item would fit exactly into the post_residual,
    // reward this placement (creates a perfect follow-up slot).
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item cannot fit here anyway; mild penalty if we are
        // leaving a gap that wastes capacity relative to mean residual.
        if mean_residual > 0.0 && (pr as f64) < mean_residual * 0.3 {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalizing outliers that hoard space.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual large enough to also fit the next item: good chaining.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    }
    // Post residual too small for next item: penalize dead space proportionally.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = post_residual as f64 / next_item_size as f64;
        score += 10.0 + waste * 15.0;
    }

    // Reward tight fills relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Penalize leaving residuals below the minimum item size (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Compare against mean residual: bins below mean residual are tighter, prefer them.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - 1.0) * 0.5 * progress;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit bias: squared residual amplifies tight packing.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 1.5; // dead-end residual for the next item
        }
    } else {
        // Last item: pure best-fit, no reason to open new bins.
        if bin_residual < bin_capacity {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).clamp(0.0, 1.0)
        } else {
            1.0
        };
        score += 4.0 + 6.0 * (1.0 - pressure) + 2.0 * progress;
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size > post_residual && post_residual < item_size / 2 {
            score -= 5.0; // open bin is genuinely better than poor fits
        }
    }

    // Mild preference to drain bins with small residuals among many open bins.
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: waste after placement, normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (bins can still be filled); late, waste is costly.
    let waste_penalty = (post / cap).powi(3) * (1.0 + 2.0 * progress);
    score += waste_penalty;

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= (1.0 - post / cap).powi(2) * 0.5;

    // Penalize bins whose residual deviates strongly from mean residual
    // (prefer bins already "out of line" to be closed out)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual as u32 {
        score -= 1.5;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.4 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.0;
    }

    // New-bin candidate: baseline cost of opening a bin, modulated by how bad
    // the current fits are and stream progress (late streams consolidate more).
    if bin_residual == bin_capacity {
        score = 1.2 + 0.5 * progress;
        // If this is the only fitting option elsewhere handled; make new bin
        // attractive only when item is large relative to capacity.
        score -= 0.3 * (item_size as f64 / cap);
    }

    // Mild preference to fill already-open bins when many are open
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" residue classes (multiples of small sizes) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual (tight fit), especially perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0; // residue class divisible by 10 -> reusable by many sizes
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Penalize dead space in the awkward 1..=9 band via integer-division thresholds.
    if post_residual >= 1 && post_residual <= 9 {
        score += 15.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Coupling with the lookahead item: if next item fits exactly into the
    // post residual, strongly favor this bin (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 18.0;
            } else if nxt_post <= 10 {
                score -= 8.0;
            } else {
                score += (nxt_post as f64) * 0.15;
            }
        } else {
            // next item cannot follow here: mild penalty proportional to gap class
            let gap = next_item_size - post_residual;
            score += match gap {
                0..=5 => 2.0,
                6..=20 => 6.0,
                _ => 10.0,
            };
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0 + pr * 0.05;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when no open bin gives a decent fit. Penalize it more when many bins
    // are open and mean residual is large (we should consolidate).
    if bin_residual == bin_capacity {
        let consolidation = (open_bins_count as f64) * (mean_residual / cap);
        score += 35.0 + consolidation * 10.0;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild global pressure: many open bins -> favor filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual alignment: bins close to the mean residual are "typical"
    // targets; slightly favor them to keep the bin profile balanced.
    score += ((pr - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual can still fit the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Penalize bins far from the mean residual (scatter control).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when current item leaves a very tight fit
    // impossible or open-bin pressure is low; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && post_residual == bin_capacity - item_size;
        if tight_exists {
            score += 40.0; // an open bin gives an exact fit; don't open a new one
        }
        score += 10.0 + 1.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can host the lookahead item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (tight packing).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() <= 3.0 {
            // Perfect 2-chain: post_residual == next_item_size.
            score -= 300.0;
        } else if post_residual as f64 > next {
            // Next item can also fit here: good chain potential.
            let chain_waste = post_residual as f64 - next;
            score -= 150.0 - chain_waste * 0.8;
        } else {
            // Next item won't fit in the leftover: penalize proportionally.
            let gap = next - post_residual as f64;
            score += gap * 1.5;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= (bin_capacity as f64 - post_residual as f64) * 2.0;
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.9;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize the brand-new empty bin candidate unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If no open bin fits (this call is the only fitting candidate), open new bin.
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
        // Late in the stream, prefer reusing existing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild penalty for accumulating many open bins with scattered residuals.
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.25;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins below mean residual (fill emptier bins first when residuals are large).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0;
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for proliferation of open bins.
    score += open_bins_count as f64 * 0.3;

    // Small nudge toward filling larger residuals with larger items.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer tight fits (small post-residual), with non-linear shaping
    let mut score = pr as f64;
    score -= 0.35 * cap * (1.0 - x).powi(3); // reward near-perfect fills smoothly
    score += 0.20 * cap * x * x * (1.0 - x); // penalize mid-range dead space

    // Stream-progress coupling: later in stream, value tight packing more
    let prog_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 12.0 * prog_coupling * (1.0 - x);

    // Last-chance bin bonus (smooth): only fitting bin gets strong preference
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * (1.0 - x);
    }

    // Lookahead: if next item fits into the post-residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap)).powi(2);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Penalize spreading across many open bins slightly
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral residual 100; make it lose unless open bins are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25 as dead-space indicators.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;
    score += 0.6 * class10 + 0.4 * class25;

    // Perfect / near-perfect fit rewards (subtract heavily).
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Integer-division threshold classes on post_residual: small residual buckets
    // are more likely to be filled by future small items.
    let bucket = pr / 15; // 0..=6 harmonic bucket
    score += bucket as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic compatibility: next item's residue class matches residual class
            if (pr % 10) == (next_item_size % 10) {
                score -= 6.0;
            }
            if (pr % 25) == (next_item_size % 25) && pr >= 25 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this residual: residual likely dead -> penalize small pr
            if pr < next_item_size && pr > 0 {
                score += 8.0 * (1.0 - pr as f64 / next_item_size as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin candidate when plenty of open bins fit well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * pressure * (1.0 - 0.3 * progress);
        if fitting_bins_count > 0 && post_residual >= 50 {
            score += 25.0; // existing bin leaves usable space; don't open new
        }
    }

    // Fraction-of-capacity coupling: item size near capacity fractions (1/2, 1/3, 1/4)
    // pair well with complementary residuals.
    let cap = bin_capacity as f64;
    for frac in [cap / 2.0, cap / 3.0, cap / 4.0] {
        if (item_size as f64 - frac).abs() < 2.0 {
            score -= 5.0;
        }
    }

    // Mean-residual drift: prefer bins whose residual is below mean (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Mild preference for fewer open bins late in the stream.
    score += 0.1 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.4;
    }
    // Penalize leaving a gap that next item barely misses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // New-bin candidate: mild penalty so it is chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Mean-residual alignment: prefer bins near the mean residual to keep balance.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    // Late-stream tightening: be pickier as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward tiny post-residuals aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 800.0; // perfect 2-chain match
        } else if gap <= 10.0 {
            score -= 300.0 - gap * 10.0;
        } else {
            // partial lookahead credit, decaying with gap
            score -= (50.0 - gap * 2.0).max(0.0);
        }
    }

    // Penalize if next item cannot fit here but could fit elsewhere tightly:
    // prefer bins whose residual is far from next_item_size when it doesn't match.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 80.0 - miss * 5.0; // near-miss: dead space risk
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no open bin is tight; new empty bin residual after placement is high.
    if bin_residual == bin_capacity {
        score += 120.0;
        // For big items, opening a fresh bin is less bad.
        score -= item_size as f64 * 0.8;
        // Late in the stream, opening new bins is worse (waste at end).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Mild preference for filling bins with larger items.
    score -= item_size as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 45.0;
        } else {
            score -= 12.0 * (1.0 - (slack_after_next as f64 / bin_capacity as f64));
        }
    }
    // Penalize leaving a residual just below the next item size (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins with large residuals already (consolidate waste).
    if bin_residual < bin_capacity {
        score -= 6.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // New-bin candidate handling: opening a new bin is attractive when the item
    // fits poorly everywhere (large post_residual relative to mean residual)
    // or late in the stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_vs_mean = (post_residual as f64 - mean_residual).max(0.0);
        // Penalize new bins mildly by default, but discount when mean residual is high
        // (open bins are fragmented) or many bins already exist.
        score += 18.0 - 10.0 * progress - 0.15 * (open_bins_count as f64);
        if waste_vs_mean > 0.0 {
            score -= 0.25 * waste_vs_mean;
        }
        // Never open a new bin when a perfect fit exists elsewhere.
        if post_residual == 0 {
            score += 40.0;
        }
    }

    // Small global pressure: with many open bins, favor compacting into existing ones.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post_residual (tight fits)
    let mut score = pr as f64;

    // Smooth non-linear coupling: dead-space penalty grows quadratically with normalized post residual,
    // modulated by stream progress (later in stream => more penalty on wasted space).
    score += 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic coupling: strongly punish near-full-but-unusable residuals as stream progresses
    score += 40.0 * norm_pr.powi(3) * progress;

    // Interaction with mean residual: bins far from the mean residual are penalized smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 20.0 * dev * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits into post_residual, penalize otherwise (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = pr - nxt;
        if fit_gap >= 0.0 {
            score -= 15.0 * (1.0 - (fit_gap / cap).min(1.0)) * (1.0 - progress);
        } else {
            score += 10.0 * ((-fit_gap) / cap) * (0.5 + progress);
        }
    }

    // Many open bins: slight pressure to consolidate into existing bins rather than open new ones
    score += (open_bins_count as f64).ln1p() * 2.0 * norm_pr;

    // New-bin candidate: make empty bins mildly unattractive unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of small
    // item sizes are more reusable; penalize "dead" residues.
    let pr = post_residual;
    if pr > 0 {
        // Class A: divisible by small harmonics (very reusable)
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Dead space: residual too small for the smallest item (1..=3)
        if pr < 4 {
            score += 15.0;
        } else if pr < 10 {
            score += 5.0;
        }
        // Integer division threshold: residual in a "awkward middle band"
        let band = pr / 25; // 0..4 quartile band of capacity
        score += band as f64 * 1.5;
    } else {
        // Perfect fit — strongly reward
        score -= 40.0;
    }

    // Lookahead coupling: does this placement leave room for next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Pairing success: reward proportional to leftover slack after next item
            let slack = post_residual - next_item_size;
            score -= 6.0;
            if slack % 10 == 0 && slack > 0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot follow here; penalize more when residual is wasted
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: any fit is fine, prefer tight packing
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 10.0 * progress;
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            // No open bin can really absorb more; opening is fine
            score -= 15.0;
        }
    }

    // Prefer tighter fits generally (relative fill fraction)
    score -= (item_size as f64 / bin_capacity as f64) * 4.0;

    // Mild penalty for bin proliferation
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item (1..=12),
    // or if it is small relative to typical item sizes.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0; // unusable sliver
    } else if post_residual > 0 && post_residual <= 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Perfect fit bonus: reward tight packing strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 30.0; // near-perfect fit, gap still usable for tiny items
    }

    // Prefer bins whose residual was already small (good density) before placement.
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.05;

    // Open bins pressure: with many open bins, discourage spreading; favor filling existing bins
    // so that opening a new bin becomes less attractive.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += open_pressure * post_residual as f64 * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only prefer a fresh empty bin when the current item
    // would leave a large dead gap in every existing bin, or no bin fits well.
    if bin_residual == bin_capacity {
        // Neutral baseline; the dead-space penalties above already push bad fits away.
        // Slight penalty so that a decent fit in an open bin wins over a new bin,
        // but a bonus if open bins are crowded (high mean residual relative to capacity).
        let crowdedness = mean_residual / bin_capacity as f64;
        if crowdedness > 0.7 {
            score -= 20.0 * (crowdedness - 0.7) / 0.3;
        } else {
            score += 15.0;
        }
        // Late in the stream, avoid opening unnecessary bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 8.0 {
            score -= 25.0; // next item will fit almost perfectly here
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize if it becomes dead space.
        if post_residual <= 12 {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain fit: next item exactly fills remaining space -> huge reward.
            let gap = post_residual - next_item_size;
            let match_quality = 1.0 - (gap as f64 / bin_capacity as f64);
            score -= 2.5 * match_quality;
            // Exact closure bonus (item + next item perfectly fills bin).
            if gap == 0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot fit here: penalize proportional to leftover dead space.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.4 * overshoot;
        }
    }

    // Penalize small unusable post-residuals (dead space) unless next item can use them.
    if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        if post_residual < 10 {
            score += 8.0; // tiny sliver, almost certainly dead
        } else if post_residual <= 20 {
            score += 3.0;
        }
    }

    // Reward tight fits overall (low post-residual relative to capacity).
    score -= 1.5 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average open bin.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for opening new bins early when many bins are open and fit is poor.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline competitive score; good fits in existing bins beat it.
        score = 45.0 + 0.3 * item_size as f64 - 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, be conservative; later, be aggressive about filling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual is better (base term already does this),
    // but amplify the preference for very tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Lookahead: if the next item fits exactly or well in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 6.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
    }
    // If next item does NOT fit in post-residual, penalize creating stranded dead space,
    // more strongly when the dead space is small (unusable).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit in existing
    // bins is poor or few bins fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin by default.
        score += 10.0;
        // But if the item is large relative to capacity, opening fresh is safer.
        let size_ratio = item_size as f64 / bin_capacity as f64;
        score -= 14.0 * size_ratio;
        // Late in the stream, avoid proliferating bins.
        score += 8.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 3.0 * fitting_bins_count as f64;
        }
    } else {
        // Existing-bin bonus: reusing bins is generally good.
        score -= 2.0;
        // Prefer bins with residuals below the mean (consolidate emptier space).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Mild pressure to spread load when many bins are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) + x * x * x * t;
    score += 12.0 * poly;

    // Reward tight fits, more aggressively late in the stream
    let tightness = 1.0 - x;
    score -= (1.0 + 3.0 * t) * tightness * tightness * item_size as f64;

    // Penalize dead space relative to mean residual across open bins
    score += 0.05 * (pr - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * t;
    }

    // Lookahead: prefer leaving space for the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 1.5 * (next_item_size as f64 / cap);
    }

    // Slight preference for consolidating into fewer bins late
    score += 0.02 * open_bins_count as f64 * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual left behind: residues divisible by 10
    // are "harmonic" (easy to fill with typical item sizes).
    let pr = post_residual as u32;
    let residue_class = pr % 10;
    let harmonic = residue_class == 0;
    if harmonic {
        score -= 8.0; // reward clean harmonic residual
    } else {
        score += residue_class as f64 * 0.6; // penalize awkward residues
    }

    // Integer-division dead-space bands on post_residual.
    let band = pr / 10; // 0..=10
    match band {
        0 => score -= 5.0,               // nearly full: excellent
        1..=3 => score -= 2.0,           // good fill zone
        4..=7 => score += 1.5,           // mediocre
        _ => score += 0.0,               // mostly empty, neutral
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0; // perfect harmonic continuation
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score += (gap % 10) as f64 * 0.5 + gap as f64 * 0.05;
        } else {
            score += 3.0; // lookahead wasted on this bin
        }
    }

    // Last-chance bin before opening a new bin: strong bonus to avoid waste.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing bins are tight or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size > bin_capacity / 2;
        let tight_mean = mean_residual < item_size as f64;
        if large_item || tight_mean || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 15.0 + 10.0 * progress; // prefer open bins early
        }
    }

    // Slight preference for bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    // Fraction-of-capacity harmonic reward: post_residual close to capacity/2
    // is a classic dead zone for medium items.
    let half = bin_capacity / 2;
    if pr.abs_diff(half) <= 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Penalize creating a gap that fits neither current nor next item.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) && post_residual < 10 {
        score += 25.0;
    }

    // Open bins pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Progress-based tightening: as stream advances, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead reward: if the next item fits exactly into post_residual,
    // heavily favor this bin (perfect 2-item chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 + 30.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize creating dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);
    }

    // Prefer tight fits relative to mean residual: below-mean post_residual is good.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere.
    // An empty bin wastes capacity if open bins can take the item, so penalize it
    // unless the stream is early and bin count is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 10.0 + waste * 0.5 - 20.0 * (1.0 - progress) * (1.0 - open_bins_count.min(10) as f64 / 10.0);
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically relative to capacity.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 60.0;

        // Lookahead: if the next item fits the post residual, reward this bin.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 25.0 + (post_residual - next_item_size) as f64 * 0.5;
            } else {
                // Next item won't fit here; penalize leaving large unusable-ish gaps.
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the item
    // is large or current bins have little room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins mildly, more when few bins open or item small.
        score += 15.0 + 30.0 * (1.0 - pressure) - 10.0 * progress;
        // If mean residual is small, new bin is more justified.
        score -= 0.3 * mean_residual;
    } else {
        // Prefer bins whose residual is below the mean (consolidate space).
        score += 0.2 * (mean_residual - bin_residual as f64);
    }

    // Slight preference for bins with more remaining usable space overall.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighten residual preference as stream advances
    score *= (1.0 + 0.8 * progress * progress);

    // Penalize dead space relative to mean residual state (smooth quadratic coupling)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count <= 1 {
        score -= 0.35 * cap * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 0.4 * n * (1.0 - norm_pr * norm_pr);
        } else {
            score += 0.3 * (-gap);
        }
    }

    // Mild penalty when many bins are open: encourage consolidation
    score += 0.02 * (open_bins_count as f64) * norm_pr * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Residuals in the "dead zone" (small leftovers) are heavily penalized,
    // residuals that form a "harmonic slot" (fitting common item classes) are rewarded.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 10; // coarse class 0..=10
    match class {
        0 => score += 45.0,                 // 0..9: nearly perfect fill, but tiny dead space
        1 => score -= 20.0,                 // 10..19: excellent slot
        2 => score -= 30.0,                 // 20..29: prime slot (fits mid items)
        3 => score -= 25.0,                 // 30..39
        4 => score -= 12.0,                 // 40..49
        5 => score += 5.0,                  // 50..59: half-full, mediocre
        6 => score += 8.0,
        7 => score += 12.0,
        8 => score += 18.0,
        9 => score += 25.0,
        _ => {}                              // 100 residual = new bin, neutral
    }

    // Modulo arithmetic: residuals congruent to small common sizes mod 10 are
    // more reusable by typical item sizes (which cluster near multiples of 5/10).
    let m = post_residual % 10;
    if post_residual < bin_capacity {
        score -= match m {
            0 => 14.0,
            5 => 10.0,
            2 | 8 => 5.0,
            1 | 9 => 3.0,
            _ => 0.0,
        } as f64;
    }

    // Lookahead coupling: reward if post_residual can host next_item_size exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 40.0; // perfect lookahead fill
            } else if slack <= 5 {
                score -= 22.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / 40.0).max(0.0);
            }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted potential
            score += 6.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 40.0;
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: prefer keeping it closed unless current bins are crowded
    // or this fit is poor. Opening a bin when a good slot exists is penalized.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 8.0;
        if fitting_bins_count >= 1 {
            score += 12.0 * (fitting_bins_count as f64).min(4.0);
        }
        if frac > 0.15 { score += 10.0; } // we already left good slots elsewhere
    }

    // Stream progression: early on, be greedy about consolidation; later, tolerate spread.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * t;

    // Mean-residual coupling: if mean residual is large, discourage dumping into
    // already-loose bins; keep tight bins tight.
    if mean_residual > 30.0 && post_residual < mean_residual {
        score -= 8.0;
    } else if mean_residual > 30.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0; // tiny dead space is worst
        } else if pr < 20.0 {
            score += 25.0 * (20.0 - pr) / 10.0;
        } else if pr < 30.0 {
            score += 10.0 * (30.0 - pr) / 10.0;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0; // discourage new bin when alternatives exist
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 30.0; // open fresh bin if next item won't fit mean residual anyway
        }
    }

    // Lookahead: prefer leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - (next_item_size as f64 - pr) / cap);
        }
    }

    // Mild progression term: late in stream, be greedier about tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill reward: residual 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here: mild reward proportional to slack
            score -= 50.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // dead space: next item cannot use the leftover; penalize proportionally
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to bin residual (small waste fraction).
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 200.0 * fill_frac * fill_frac;

    // Penalize deviation from mean residual: prefer bins near average occupancy,
    // unless it's a last-chance bin, which we heavily favor to avoid opening a bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Late in the stream, consolidate: prefer already-open bins over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 60.0 + 120.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    // Slight penalty for too many open bins to encourage consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: later on, prefer using existing bins more aggressively.
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    score *= 1.0 + 0.35 * progress; // penalize leftover space more as stream advances

    // Reward tight fits: small post_residual gets a strong discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item could exactly fill this bin's
    // post-residual, reward heavily; if next item won't fit here, penalize
    // mildly (wasted capacity for the future).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item chain
        } else if next_item_size > post_residual {
            score += 6.0; // next item can't use leftover space
        } else {
            score -= 5.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the current item fits poorly
        // everywhere else (large post_residual in existing bins) and there
        // are already many open bins with fragmented space.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 10.0 + 8.0 * fragmentation + 0.5 * open_bins_count as f64;
        // But discourage opening new bins early when existing bins fit well.
        if fitting_bins_count > 0 && post_residual < 20 {
            score += 20.0;
        }
    } else {
        // Mild preference for bins whose residual deviates from the mean
        // (consolidate similar-fill bins, keep a spread of residual sizes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Encourage balancing: prefer bins with residual above the mean slightly,
    // so low-residual bins stay reserved for small items.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (pr / cap);

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits increasingly as the stream progresses
    score -= 60.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual).max(0.0);
    score += 0.35 * dead * dead / cap;

    // Lookahead: reward leaving space for the next item (smooth coupling)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = (pr - n) / cap;
        if fits_next >= 0.0 {
            score -= 25.0 * fits_next * (1.0 - progress);
        } else {
            score += 12.0 * (-fits_next) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - tightness * 0.5);
    }

    // Mild congestion penalty (quadratic in open bins, normalized)
    score += 0.02 * (open_bins_count as f64) * (open_bins_count as f64) / (cap * 0.1);

    // New-bin candidate: keep it slightly unattractive unless residuals are messy
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) - 10.0 * (mean_residual / cap - 0.5).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "clean" the leftover space is.
    // Residuals that are multiples of common item sizes (or near them) are reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-based dead-space penalty: residuals in awkward small ranges (1..10)
    // are nearly unusable; penalize them heavily via harmonic scaling.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post);
    }

    // Harmonic divisibility bonus: if post_residual is divisible by common size
    // classes (5, 10, 20, 25), the leftover is more likely reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 5 == 0 { score -= 3.0; }
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 20 == 0 || pr % 25 == 0 { score -= 3.0; }
    }

    // Integer-division threshold: classify post residual into quartile bands of capacity.
    let quartile = (post_residual * 4) / bin_capacity; // 0..3
    match quartile {
        0 => score += 8.0,          // nearly full bin: good, but tiny leftover -> slight bonus for tight packing
        1 => score -= 0.0,          // neutral
        2 => score -= 4.0,          // mid leftover: decent
        _ => score -= 8.0,          // large leftover: very reusable
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic decay of reward with slack distance
            score -= 12.0 / (1.0 + slack / 10.0);
        } else {
            // next item won't fit here; mildly penalize large leftovers that
            // fail the lookahead (dead space risk)
            if post_residual > 40 {
                score += 5.0;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer new bins only when the current item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by item size (large items justify new bins).
        score += 20.0 - 0.15 * item_size as f64;
        // If many open bins exist with slack, discourage opening yet another one.
        score += 0.5 * open_bins_count as f64;
        // But if the mean residual is small (bins nearly full), a new bin is fine.
        score -= (cap - mean_residual).min(cap) * 0.1;
    }

    // Tight-fit reward: small post residual relative to item size means efficient packing.
    let fill_fraction = item_size as f64 / cap;
    score -= 10.0 * fill_fraction * fill_fraction;

    // Progress-aware scaling: early in the stream, be slightly more conservative
    // about wasting space (many items remain to use leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (1.0 - progress) * 10.0; // dead space hurts more early on
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make empty bins less attractive unless current bins would waste space
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mean residual coupling: penalize placements far from mean residual usage
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // Stream progression: slightly favor consolidation late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);

        // Penalize leaving dead space too small for the next item
        if post_residual < next_item_size && post_residual > 0 {
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    } else {
        // Last item: reward tight fit
        score -= 40.0 / (1.0 + post_residual as f64);
    }

    // Reward perfect fill
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize tiny unusable residuals in absolute terms
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins with less residual than mean are
    // more "wasted" candidates; prefer placing into tighter-than-mean bins
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when open bins leave poor fits.
    // Penalize opening new bins mildly; the lookahead rewards above decide.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // big item followed by big item: fresh bin ok
        }
    }

    // Slight preference for filling older bins as stream progresses
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Exact fill: strong reward for perfectly closing a bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small dead-space thresholds: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Many alternatives: slight penalty to prefer the most fitting one.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // Next item fits current residual too: keep this bin flexible.
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Last item: closing bins is free value.
        score -= 15.0;
    }

    // Global state: prefer filling bins when many are open (consolidation pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * (open_bins_count as f64).ln().max(0.0);
    score -= 10.0 * progress;

    // Mean residual coupling: if this bin is far below mean residual, it's a poor filler.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev;

    // New-bin candidate: open only when item is large or fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if scarcity > 0.0 || (big_item && open_bins_count > 2) {
            score -= 18.0;
        } else {
            score += 22.0 + 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64;

    // Smooth non-linear coupling: normalized post-residual decayed waste
    let x = pr / cap; // 0..1
    score += 18.0 * x * x * (1.0 - 0.5 * progress); // penalize residual space, less so late in stream

    // Reward tight fits (small post_residual relative to capacity) with smooth term
    score -= 12.0 * (1.0 - x) * (1.0 - x) * (1.0 + 0.3 * progress);

    // Penalize post_residual that is too small to ever fit a plausible item (dead space)
    let dead_threshold = 10.0;
    if pr < dead_threshold {
        score += 8.0 * (1.0 - pr / dead_threshold);
    }

    // Lookahead: if next item fits exactly into the post_residual, reward strongly
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // next item won't fit here; mild penalty proportional to gap
        score += 4.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    score -= (fit / cap) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate handling: neutral-ish baseline; only prefer it when current
    // bins would waste a lot (high mean residual relative to item) or late stream
    if bin_residual == bin_capacity {
        let new_bin_base = fit * 0.35 + 20.0;
        score = new_bin_base
            + 6.0 * progress
            - 8.0 * (mean_residual / cap).min(1.0);
    }

    // Interaction of item size with stream progress: big items early should prefer
    // existing bins slightly more (save capacity), smooth polynomial coupling
    score += 3.0 * (fit / cap) * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: fraction of capacity
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space classes: residuals that few item sizes can use are bad.
    // Class boundaries at 1/4, 1/3, 1/2 of capacity.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, best possible outcome
    } else if post_residual < bin_capacity / 10 {
        // tiny sliver, nearly unusable but not zero
        score += 60.0;
    } else if post_residual < bin_capacity / 4 {
        // quarter-class dead zone
        score += 25.0 * (1.0 - frac * 4.0);
    } else if post_residual < bin_capacity / 3 {
        // third-class: usable by mid items
        score -= 5.0;
    } else if post_residual < bin_capacity / 2 {
        score -= 15.0;
    } else {
        // large residual: plenty of room, mild preference to fill big bins first
        score -= 5.0;
    }

    // Integer division harmonic: post_residual mod 10 -> alignment classes
    let m = post_residual % 10;
    score -= match m {
        0 => 12.0, // round residual, easy to fill exactly
        5 => 6.0,
        2 | 8 => 2.0,
        _ => 0.0,
    };

    // Lookahead coupling: reward residuals that exactly fit the next item,
    // penalize residuals that waste the next item's fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chains perfectly
        } else if post_residual >= next_item_size {
            score -= 20.0; // next item still fits
        } else {
            // next item won't fit here: this residual is terminal dead space
            score += 30.0 + 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    } else if fitting_bins_count > 1 {
        // among several candidates, prefer best-fit behavior: reward small post_residual harder
        score -= 0.5 * (bin_residual - post_residual) as f64;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 - 40.0;
        if fitting_bins_count == 0 {
            score -= 1000.0; // no alternative, must open
        } else if mean_residual < item_size as f64 * 1.2 {
            // open bins are nearly full anyway
            score -= 300.0;
        } else if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // opening allows pairing this item with the next one
            score -= 80.0;
        }
        // late in stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64 / total_items as f64) > 0.8 {
            score += 50.0;
        }
    }

    // Mild pressure to keep the number of open bins low
    score += 0.15 * open_bins_count as f64;

    // Slight preference to balance against mean residual (avoid extreme fragmentation)
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that still leave room for a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Creating a gap smaller than the lookahead item is dead space risk.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 10.0 + mean_residual * 0.5;
    } else {
        score -= open_bins_count as f64 * 0.3;
    }

    // Early stream: be greedy with existing bins; late stream: keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits with small slack left afterward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize by how much it misses.
        let miss = next_item_size - post_residual;
        score += 0.15 * miss as f64;
    }

    // Reward tight fits relative to current bin's own residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Penalize residual far below mean residual (this bin is unusually empty-ish choice).
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish, slightly penalized early, less penalized late
    // so late in the stream we allow opening fresh bins for better long-run packing.
    if bin_residual == bin_capacity {
        score = 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin leaves capacity - next_item_size after lookahead... fine.
        }
        if next_item_size > 0 && post_residual.wrapping_sub(next_item_size) > bin_capacity {
            // guard, no-op
        }
    }

    // Mild pressure to consolidate bins when many are open.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: strongly reward if the next item also fits in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.35 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Penalize if next item cannot follow into this bin.
        score += 4.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual already below the mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev;

    // Early in the stream: encourage opening bins that leave large flexible residuals;
    // late in the stream: pack tightly, accept small residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // With many open bins, discourage opening yet another bin.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0; // a fresh bin can host the next item too
        }
    }

    // Mild reward for filling a large fraction of the current residual.
    score -= 5.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.9 * t + 0.6 * t * t);

    // Penalize large dead space quadratically as the stream matures
    score += 0.8 * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits: small post_residual gets a discount
    score -= (1.0 - norm_pr).powi(3) * 0.5;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.7 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 0.3 * norm_pr;
    }

    // Slight preference to fill bins with larger residuals relative to mean
    score -= 0.15 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate: keep it neutral-ish, penalize slightly so we prefer reusing bins with good fits
    if bin_residual == bin_capacity {
        score += 0.4 + 0.5 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Class 0 (residual % 10 == 0) is most reusable; deeper classes are penalized.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 1.7;

    // Integer-division thresholds on post_residual: dead-space bands.
    let band = post_residual / 10; // 0..10
    match band {
        0 => score += 6.0,                 // nearly full bin: great, but residual class dominates
        1 => score -= 2.0,                 // 10..19 leftover: still useful for small items
        2 | 3 => score -= 4.0,             // 20..39: sweet spot
        4 | 5 => score += 1.0,             // 40..59: mediocre
        6 | 7 => score += 3.0,             // 60..79: poor
        _ => score += 5.0,                 // 80+: barely touched bin
    }

    // Fraction of capacity filled by this placement.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * 12.0;

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // harmonic match quality of lookahead
            let lm = (post_residual % next_item_size.max(1)) as f64;
            score -= 6.0 - lm * 0.8;
        } else {
            // next item won't fit here; penalize leaving a mid-range residual that traps it
            if post_residual >= next_item_size / 2 {
                score += 4.0;
            }
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open it when no decent open bin exists, but allow it when the item is
    // large relative to capacity (best-fit-against-open-bins is hopeless anyway).
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / cap) > 0.6;
        let pressure = mean_residual < (item_size as f64 * 0.5);
        let mut nb = 20.0;
        if large { nb -= 10.0; }
        if pressure { nb -= 6.0; }
        if fitting_bins_count == 0 { nb -= 30.0; }
        // early stream: opening bins early is fine
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            nb -= 5.0;
        }
        score += nb;
    }

    // Mild preference to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps only usable by tiny items: strong penalty.
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Large usable residuals are valuable: reward them.
        score -= (post_residual as f64 - 35.0) * 0.35;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item fits here now but not after this placement: mild penalty.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // few open bins -> tolerate opening new bins.
    let pressure = (open_bins_count as f64).ln() * 6.0;
    score += pressure;

    // Progress-aware: late in the stream, waste hurts more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    // Mean residual coupling: if mean residual across open bins is low,
    // bins are mostly full -> keep rewarding tight fits further.
    if mean_residual < 25.0 {
        score -= 5.0;
    } else if mean_residual > 60.0 {
        // Lots of slack overall: opening a new bin is cheaper, penalize
        // cramming into nearly-full bins slightly.
        score += (mean_residual - 60.0) * 0.05;
    }

    // New-bin candidate: neutral baseline; only prefer it when existing
    // bins have terrible fits. Give it a mild default so it wins only
    // when open bins are heavily penalized.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: minimize post_residual (tight fit reward already via small post_residual).

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff == 0.0 {
            score -= 45.0; // perfect chain: this bin's leftover fits the next item exactly
        } else if post >= next {
            score -= 18.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        } else {
            // leftover too small for next item: penalize dead space proportionally
            score += 10.0 + 0.35 * (next - post);
        }
    } else {
        // Last item: only tightness matters
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; avoid wasting them.
    let post = post_residual as f64;
    if post > mean_residual {
        score += 0.5 * (post - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_open_exists = fitting_bins_count > 0 && (post_residual as f64) <= mean_residual;
        let penalty = if good_open_exists { 60.0 } else { 8.0 };
        score += penalty + 10.0 * (1.0 - progress);
        // Opening a bin that can chain the next item is less bad
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) >= item_size {
            score -= 5.0;
        }
    }

    // Fractional waste term: quadratic in post_residual to discourage unusable slivers.
    score += 0.02 * (post * post) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0; // dead space below min item size is unusable
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * chain;
    }
    // Penalize leaving a residual that is *almost* but not enough for next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // New-bin candidate: discourage unless it's genuinely the better option.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // If this bin is the only fitting option and the fit is bad, allow opening.
        if fitting_bins_count == 1 && fit_ratio < 0.5 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins already -> discourage more.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Existing bin: slight preference when it is the last chance.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // Prefer bins with lower residual (tighter bins first).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Mild global pressure: when many bins are open, consolidate aggressively.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 2.0 * poly;
    // Reward tight fits (small post residual) more strongly as stream advances
    score -= (1.0 - norm_pr).powi(3) * (0.5 + progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.5 + progress;
    }
    // Penalize wasting large residual when mean residual is high
    score += 0.3 * (norm_pr - mean_residual / cap).abs();
    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.5 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
    }
    // Mild penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 0.8 * (1.0 - progress) + 0.2 * (open_bins_count as f64).sqrt();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: exact-fill classes (0, and small residues)
    // are the most valuable outcomes. Use integer division thresholds on post_residual.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: bin closed, zero waste
    } else if pr <= 5 {
        score -= 30.0;
    } else if pr <= 15 {
        score -= 12.0;
    } else if pr <= 30 {
        score -= 4.0;
    } else if pr <= 50 {
        score += 3.0;
    } else {
        // large leftover: likely dead space
        score += 10.0;
    }

    // Modulo-10 harmonic classes: residues divisible by 10 pair well with
    // common item sizes (multiples of 10 are frequent in many streams).
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Odd tiny residues are hard to reuse
    if pr % 2 == 1 && pr < 10 {
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            let over = (next_item_size - pr) as f64;
            score += 2.0 * (over / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer tightening the fullest bins
    // (low residual relative to mean) to consolidate.
    let res_f = bin_residual as f64;
    if open_bins_count > 1 {
        if res_f < mean_residual {
            score -= 8.0 * (mean_residual - res_f) / cap;
        } else {
            score += 4.0 * (res_f - mean_residual) / cap;
        }
    }

    // Early in the stream, be more willing to open new bins (keep options);
    // late in the stream, pack tighter to avoid spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // New-bin candidate: neutral baseline, mildly discouraged unless it
    // genuinely beats existing bins (handled by comparisons above).
    if bin_residual == bin_capacity {
        score += 5.0;
        // A new bin is attractive if nothing fits well (large item, no tight fit)
        if post_residual as f64 / cap < 0.2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small to host any item
    // (items >= 1) are waste; the smaller the gap, the more useless it is.
    if post_residual > 0 {
        // Quadratic penalty on tiny gaps: gap of 1..=10 is nearly dead space.
        let dead_zone = 12.0;
        if (post_residual as f64) < dead_zone {
            score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 8.0;
        }
        // If the next item cannot fit in the post residual, this placement
        // strands space the lookahead could have used.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // If next item fits exactly, reward leaving that exact gap.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // Pressure from open bins: when many bins are open, prefer filling
    // existing ones rather than spreading out.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late when bins are scarce.
        score += 120.0;
        // If few bins can fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // Early in the stream, a fresh bin is more tolerable.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 40.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean
    // (tight bins get priority to consolidate small gaps).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (chains a perfect second fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Near-match: next item leaves small dead space again
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize post_residual that cannot host the next item at all
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Compare post_residual relative to mean residual of open bins:
    // prefer bins that consume more slack than average (tightening the fleet).
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Penalize creating tiny unusable dead space (< 10) that no item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 150.0;
    }

    // New-bin candidate handling: keep empty bins attractive only when open bins
    // are tight on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        score += 80.0 + 120.0 * pressure - 60.0 * progress;
    }

    // Slight preference for larger residual bins early, tighter bins later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Fractional tightness term: reward small post_residual relative to capacity.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize leaving residuals that are too small for typical future items
    // but not zero (dead space zone: 1..=9 already handled; mid-range dead space).
    if post_residual > 10 && post_residual < 20 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // heavily reward this placement (creates a perfect follow-up).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 50.0 / (1.0 + slack as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly. Penalize new bins when there are open bins
    // with plenty of room, reward slightly when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        // crowd near 1 => open bins are nearly full => new bin is fine.
        score += 250.0 * (1.0 - crowd);
        // Mild time-based discount: early in the stream, avoid bin proliferation.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * (1.0 - t);
    } else {
        // Existing bin: mild reward for keeping bin count low.
        score -= 10.0 * (open_bins_count as f64).ln().max(0.0).min(20.0);
    }

    // Global state coupling: prefer filling bins with large residuals when the
    // mean residual is high (consolidation pressure).
    if bin_residual as f64 > mean_residual {
        score -= 15.0;
    } else {
        score += 5.0;
    }

    // Late-stream pressure: as the stream ends, be more greedy about tight fits.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 60.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;

    // Base: normalized post residual, non-linearly shaped
    let post_norm = post / cap;
    let mut score = post_norm.powf(1.5) * 10.0;

    // Reward tight fits (small post residual) more aggressively
    score -= (1.0 - post_norm).powf(3.0) * 4.0;

    // Smooth interaction: as stream progresses, penalize residual waste more
    score += post_norm * progress * 6.0;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    let mean_norm = mean_residual / cap;
    score += (post_norm - mean_norm).abs() * 2.0;
    score -= post_norm.max(mean_norm) * 1.5;

    // Lookahead: if next item fits the post residual, reward; else penalize
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post;
        if next_fits {
            score -= 2.5 * (1.0 - (next_item_size as f64) / post.max(1.0)).powf(2.0);
        } else {
            let gap = (next_item_size as f64 - post) / cap;
            score += gap * 3.0 * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    } else {
        // mild penalty for spreading across many fitting bins
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // New-bin candidate: make it attractive only when open bins would leave large waste
    if bin_residual == bin_capacity {
        let waste_elsewhere = mean_norm;
        score = 4.0 + post_norm * 2.0 - waste_elsewhere * 3.0 - fit_ratio * 2.0;
        if fitting_bins_count <= 1 {
            score -= 6.0;
        }
    }

    // Density reward: large items into tight bins
    score -= fit_ratio * (1.0 - post_norm) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: modulo arithmetic on residual space
        // Residuals divisible by small item classes (e.g. 10, 20, 25, 50) stay reusable.
        let pr = post_residual;
        let mut harmony_bonus = 0.0;
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 20 == 0 { harmony_bonus += 4.0; }
        if pr % 25 == 0 { harmony_bonus += 4.0; }
        if pr % 50 == 0 { harmony_bonus += 3.0; }
        score -= harmony_bonus;

        // Penalize dead space: residuals in awkward ranges (1..10) are nearly unusable
        if pr < 10 {
            score += 30.0 * (10 - pr) as f64;
        }

        // Lookahead coupling: does post_residual harmonize with next item?
        if next_item_size > 0 {
            if pr >= next_item_size {
                // next item fits exactly or leaves a harmonic residue
                let next_post = pr - next_item_size;
                if next_post == 0 { score -= 40.0; }
                else if next_post % 10 == 0 { score -= 12.0; }
                else if next_post < 10 { score += 8.0; }
            } else {
                // bin cannot serve next item; dead space likely
                score += 10.0;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 25.0;
        }

        // New-bin candidate: only attractive when residuals across open bins are poor
        if bin_residual == bin_capacity {
            let progress = step_index as f64 / total_items.max(1) as f64;
            let poor_fit = if mean_residual > 0.0 {
                (post_residual as f64 / mean_residual).min(3.0)
            } else { 1.0 };
            // penalize new bin mildly, more so early in the stream
            score += 15.0 + 20.0 * (1.0 - progress) - 5.0 * poor_fit;
            // but if item is large relative to capacity, new bin can be sensible
            if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
                score -= 30.0;
            }
        }

        // Tightness reward: fraction of bin consumed by this placement
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill_frac;

        // Integer division threshold: post_residual tiers
        let tier = pr / 25; // 0..4
        score += tier as f64 * 2.0; // lower residual (higher tier index? invert)
        score -= (3 - tier.min(3)) as f64 * 1.0;

        // Many open bins: prefer consolidation into existing bins
        if open_bins_count > 4 && bin_residual != bin_capacity {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the minimum item size are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; penalize if it blocks.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            score += (next_item_size as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage proliferation of bins with scattered residuals.
    score += open_bins_count as f64 * 0.4;

    // Prefer bins tighter than the mean residual (fill fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it unattractive unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0 + post_residual as f64 * 0.1;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits with small leftover: strong reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how much dead space remains.
        let unusable = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += 10.0 * (unusable / bin_capacity as f64);
    }

    // Tight packing reward: small post_residual relative to bin capacity.
    score += 15.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins below mean residual (fill emptier bins less; keep tight bins tight).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // New-bin candidate: only attractive late in the stream or when many bins open,
    // penalized otherwise so we prefer reusing open bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 25.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward near-perfect fills strongly (non-linearly)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Reward small post-residual quadratically (dead space penalty shaping)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 25.0 * chain;
    } else if next_item_size > post_residual {
        // Next item won't chain here: mild penalty proportional to wasted opportunity
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the current
    // item is large and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0 + 25.0 * (1.0 - t);
        // If item is small relative to capacity, opening a bin wastes capacity
        let size_waste = (bin_capacity - item_size) as f64;
        score += base_penalty + 0.1 * size_waste;
        // If no existing bin fits (fitting_bins_count == 0 means only new bin), soften penalty
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in stream with high pressure, opening new bins is more acceptable
        score -= 15.0 * t * pressure;
    }

    // Time horizon: early on, slightly favor keeping bins flexible (mid residuals);
    // late, favor maximal filling regardless.
    score += 8.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer bins that leave moderate residuals; later, minimize residual waste strongly.
    let prn = pr / cap;
    let coupling = prn * prn * (1.0 - progress) * 40.0 + prn * progress * 60.0;
    score += coupling;

    // Reward tight fits with a smooth saturating term.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 12.0;

    // Penalize residuals that cannot fit the lookahead item (dead space), smoothly.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let gap = (next_item_size - post_residual as u32) as f64 / cap;
        score += gap * gap * 50.0 + gap * 10.0;
    } else if next_item_size > 0 {
        score -= 4.0; // lookahead still fits: mild bonus
    }

    // Last-chance bin: smooth reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn);
    } else {
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // New-bin candidate: prefer opening a new bin only when residuals are large.
    if bin_residual == bin_capacity {
        let avg = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = 20.0 + prn * 30.0 + avg * 0.15 + open_pressure * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity.
    // Residuals that are "harmonically compatible" with common item sizes
    // (multiples of 10/20) are less likely to become dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let m10 = (pr % 10) as f64;
    let m20 = (pr % 20) as f64;
    // Penalize residuals off the harmonic grid (1..9 remainder is dead space risk).
    if pr > 0 {
        score += (10.0 - m10) * 0.6;
        if m20 != 0 { score += 1.5; }
    }
    // Zero residual is perfect packing.
    if pr == 0 { score -= 25.0; }

    // Tight-fit reward: small post_residual relative to capacity.
    let frac = pr as f64 / cap;
    if frac < 0.1 { score -= 12.0; }
    else if frac < 0.25 { score -= 5.0; }

    // Lookahead: harmonic class of next_item_size vs post_residual.
    if next_item_size > 0 && (next_item_size as u32) <= pr {
        let nxt = next_item_size;
        // Next item fits exactly -> strong reward.
        if nxt == pr { score -= 20.0; }
        // Next item leaves again a harmonic residual (mod 10 == 0).
        else if (pr - nxt) % 10 == 0 { score -= 8.0; }
        else { score -= 3.0; }
    } else if next_item_size > pr {
        // Next item cannot use this bin's leftover: leftover likely dead space.
        score += 6.0 + frac * 10.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild preference for reusing bins when many are open (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64) * 0.15 * (1.0 - progress);

    // Slight pull toward mean residual: prefer bins near average fill.
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    // Brand-new bin candidate: only attractive when item is large and no
    // open bin offers a harmonic fit.
    if bin_residual == bin_capacity {
        let large = item_size > bin_capacity / 2;
        if large || fitting_bins_count == 0 { score -= 8.0; }
        else { score += 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // are heavily penalized. Items are 1..100, but small gaps (<10) are
    // nearly unusable; gaps that can't hold the next item are also dead.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 18.0 + (next_item_size - post_residual) as f64 * 0.4;
    }

    // Reward near-perfect fits (small post_residual that is still usable).
    if post_residual > 0 && post_residual <= 15 {
        score -= 12.0;
    }

    // Tight-fit gradient: strongly favor bins where the item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // closing bins out (small post_residual closes a bin for good).
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the new-bin candidate wins on dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it mildly unattractive by default,
    // so it only wins when open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If the next item is large and this item is small, a fresh bin may
        // be a better home for the upcoming big item: soften the penalty.
        if next_item_size >= 60 && item_size <= 40 {
            score -= 20.0;
        }
    }

    // Lookahead synergy: reward placing the item so the next item also fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.1;
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // using them rather than opening new ones.
    score -= mean_residual * 0.05;

    // Slight early-stream flexibility: keep options open at the start.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead fit: strong reward.
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits in the leftover: reward proportionally to tightness.
            score -= 40.0 * (1.0 - diff / nxt.max(1.0));
        } else {
            // Next item won't fit in leftover: penalize wasted residual.
            score += 15.0 + 0.3 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual of open bins.
    // Leaving much more than the mean residual is dead space.
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage opening yet another one.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But if no open bin fits well (huge waste otherwise), new bin is attractive.
        if fitting_bins_count > 0 {
            let best_possible = (bin_residual - item_size) as f64;
            if post_residual as f64 > 0.6 * bin_capacity as f64 {
                score -= 30.0;
            }
            let _ = best_possible;
        }
        // Exact-fit potential of fresh bin for next item.
        if next_item_size > 0 && next_item_size == item_size {
            score -= 10.0;
        }
    }

    // Mild tie-break: prefer tighter fits overall.
    score += 0.1 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't fit the smallest plausible item (1..100 range).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Lookahead: if next item fits into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / 100.0 + 0.5);
        } else {
            // penalize leaving a gap that blocks a large next item
            let overshoot = (next_item_size as f64 - post_residual as f64) / 100.0;
            score += 8.0 * overshoot;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // prefer the bin where the item is proportionally largest
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global pressure: many open bins -> consolidate; few open bins -> spread.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * pressure * (1.0 - (item_size as f64 / bin_residual.max(1) as f64).min(1.0));

    // Mean residual coupling: prefer bins deviating below mean (fill the emptier bins less).
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Time horizon: early stream -> prefer new bins for flexibility; late stream -> fill existing bins hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score -= 10.0 * (1.0 - progress);
        score += 30.0 * progress;
        if fitting_bins_count == 1 && post_residual >= 0 {
            score += 40.0; // never open new bin when it's the last chance
        }
    } else {
        score -= 15.0 * progress;
    }

    // Nonlinear coupling between tightness and progress.
    score -= 10.0 * tightness * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * (1.0 - norm_pr);
    score += 20.0 * poly;

    // Tight fits rewarded, more so late in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 15.0 * progress);

    // Penalize dead space relative to mean residual
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Mild penalty for proliferation of open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // "dead zones" via integer division thresholds.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the residual into harmonic buckets of capacity/8.
    let class = post_residual / (bin_capacity / 8).max(1); // 0..=8
    let class_penalty = match class {
        0 => -60.0,          // tiny leftover: excellent packing
        1 => 0.0,            // small leftover
        2 => 10.0,           // medium: mildly wasteful
        3 => 25.0,           // awkward zone
        4 => 40.0,           // half-empty: wasteful
        5 => 20.0,           // recoverable
        6 => 5.0,            // large residual still usable
        7 => -15.0,          // nearly full bin: good compaction
        _ => -5.0,
    };
    score += class_penalty;

    // Dead-space trap: leftover too small for the smallest plausible item (1..100 range)
    // but nonzero -> pure waste. Penalize leftovers below ~10 harshly unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the leftover
            score -= 30.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            // leftover can't host next item: slight penalty scaled by waste
            score += 10.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.75 + 50.0;
        // Cheaper to open a bin early when few bins are open (spread load).
        score -= 15.0 * (open_bins_count as f64).sqrt().recip();
        // If next item is large and current fit is tight, new bin more attractive.
        if next_item_size > 50 && post_residual > 0 && post_residual < 20 {
            score -= 60.0;
        }
        // Late in stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild preference for fuller bins overall (tie-break by mean residual context).
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100)
    // can realistically use are heavily penalized.
    if post_residual > 0 {
        // "Unusable" gap: smaller than typical small items and unlikely to be filled.
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual < 35 {
            score += 5.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward near-perfect fits proportionally.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover gap -> penalize dead space more.
        score += 12.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (concentrate filling, keep large residuals for large future items).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Early stream: be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional lookahead fit, penalize large leftover slack
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item cannot fit here; penalize proportionally to how wasted the space is
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / 100.0);
        }
    } else {
        // Last item: prefer minimal post_residual strongly
        score -= 8.0 * tightness;
    }

    // Relative to mean residual: prefer bins with residual already below average
    // (consolidating space), unless it is a fresh empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 5.0 * rel;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin generally, but less so early
    // in the stream or when many bins are open and fragmented.
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 14.0 * (1.0 - progress);
        if open_bins_count > 3 {
            penalty -= 2.0 * (open_bins_count.min(10) as f64 - 3.0);
        }
        // If the item is large, opening a fresh bin is more attractive
        penalty -= 0.05 * item_size as f64;
        score += penalty.max(2.0);
    }

    // Mild penalty for leaving dead space that no plausible item (min size 1) can use
    if post_residual > 0 && post_residual < 10 && !is_new_bin {
        score += 3.0; // tiny dead space is bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 30.0 * dead;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // If next item can't fit here, mildly penalize unless residual is near zero.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be pickier (penalize loose fits);
    // late in the stream, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * t * (post_residual as f64) / (bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins over opening new ones.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins would be left with large, awkward residuals and few
    // alternatives exist.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0 || (fitting_bins_count <= 1 && post_residual > 35);
        if desperate {
            score -= 5.0; // allow new bin
        } else {
            score += 40.0; // prefer reusing open bins
        }
        // Late in stream with many open bins, avoid new bins even more.
        score += 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic coupling of post_residual with item share.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let tight_bonus = (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0 * (0.5 + fill_ratio);
    score -= tight_bonus;

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 25.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0 + 18.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item cannot use.
        score += 8.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (consolidate emptier bins).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize mildly early, more when open bins are plentiful.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 55.0 - 30.0 * scarcity - 10.0 * progress;
    }

    // Smooth stream-progress shaping: later items tolerate residual less.
    score *= 1.0 + 0.25 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // "harmonic" with the classic size grid and easier to fill later.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 6.0;
    } else {
        // Odd/awkward residuals create dead space; penalize proportionally.
        score += (post_residual % 10) as f64 * 0.8;
    }

    // Integer-division thresholds on post_residual.
    let q = post_residual / 25;
    score -= q as f64 * 2.5; // larger usable chunks are valuable

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic match between next item and post residual
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - post_residual).min(20) as f64 * 0.3;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (mean_residual - item_size as f64).max(0.0);
        score = 100.0 - poor_fits * 1.5 - progress * 10.0
            - if post_residual % 10 == 0 { 5.0 } else { 0.0 };
        // discourage hoarding new bins when many are already open
        score += open_bins_count as f64 * 1.2;
    }

    // Mild tie-break: prefer filling bins with below-average residual (compact them).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gap too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead-space pressure grows as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 40.0 * progress;

    // Prefer bins whose residual matches the item size (tight fit)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // New-bin candidate: prefer reusing open bins unless fit is terrible
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.2;
    }

    // Slight preference for fuller bins (relative to mean residual)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (two items perfectly fill the bin).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Perfect 2-step fit: strong reward.
        let gap = (post - nxt).abs();
        if gap < 0.5 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of match.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space that is too small
            // to be useful (wasted residual).
            let wasted = post;
            if wasted < 10.0 {
                score += 20.0; // tiny unusable sliver
            } else {
                score += 5.0 + 0.1 * wasted;
            }
        }

        // If the next item fits *only* here among fitting bins, encourage using it.
        if next_item_size <= post_residual && fitting_bins_count <= 2 {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize post_residual (best-fit behavior).
        score -= 10.0;
    }

    // Last-chance bin for the current item: strong incentive to use it
    // rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize bins whose residual is far below the mean (already tight bins
    // are valuable; wasting them on a loose fit is bad), reward bins with
    // residual near the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 110.0
            - 20.0 * (step_index as f64 / total_items.max(1) as f64)
            - 2.0 * open_bins_count as f64;
        // If next item would fit perfectly in the residual of an existing bin,
        // opening a new bin is unattractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score = base + 40.0;
        } else {
            score = base + (post_residual as f64 - mean_residual).abs() * 0.2;
        }
    }

    // Mild preference for filling bins early in the stream.
    score -= 3.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if (bin_residual as i64 - next_item_size as i64) >= item_size as i64 {
            // Better to reserve this bin for the next item.
            score += 18.0;
        }
        // Pairing efficiency: item + next item nearly fills bin.
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() <= 5.0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 30.0;
    } else {
        // Mild competition pressure among many fitting bins.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: many open bins with slack -> prefer consolidating into high-residual bins.
    let slack = mean_residual - bin_residual as f64;
    score += 0.3 * slack;

    // Time horizon: late in stream, be conservative; avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 40.0 * progress;
        // But allow new bin early or when open bins are nearly full on average.
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 25.0;
        }
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Fragmentation-aware: prefer bins whose post_residual stays "usable"
    let usable = |r: u32| if r >= 10 { 0.0 } else { 15.0 };
    score += usable(post_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let t = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early: mild penalty for large residual waste; Late: strong penalty.
    let progress_weight = 0.4 + 1.6 * t * t;
    score += progress_weight * (pr / cap) * (pr / cap) * cap * 0.3;

    // Reward tight fits (small post_residual) with smooth saturation.
    let tight = (-pr / (0.25 * cap)).exp();
    score -= 6.0 * tight;

    // Penalize residuals that are too small to hold the next item but nonzero
    // (dead space), smoothly scaled by lookahead size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = (nx - pr) / cap;
        let dead = if unusable > 0.0 { unusable } else { 0.0 };
        score += 3.0 * dead * (1.0 + t);

        // Reward bins whose post_residual can still fit the next item.
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 2.5 * fits_next * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - (pr / cap));
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Pull toward mean residual: prefer bins with residual close to mean,
    // keeping the pool of usable residuals balanced (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 1.2 * dev * dev * cap * 0.1;

    // New-bin candidate: neutral-ish baseline, penalized mildly so it is
    // chosen only when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: integer division thresholds.
    // Post-residual classes: 0 (perfect), 1..=10 (nearly perfect), 11..=30 (usable),
    // 31..=60 (degraded), >60 (large waste, likely fine for future big items though).
    let post_class: f64 = if post_residual == 0 {
        -60.0
    } else if post_residual <= 10 {
        -25.0
    } else if post_residual <= 30 {
        -5.0
    } else if post_residual <= 60 {
        10.0
    } else {
        25.0
    };
    score += post_class;

    // Modulo-style coupling: leftover that is a "harmonic" fraction of capacity
    // (25/50/75) is more likely reusable by typical items.
    let harmonics = [0u32, 10, 20, 25, 30, 40, 50, 60, 75];
    if harmonics.contains(&post_residual) {
        score -= 12.0;
    }
    // Exact multiple-of-10 leftovers pair well with items drawn from 10..80 grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a further remainder: penalize by leftover quality.
            let nxt_post = post_residual - next_item_size;
            score -= 15.0 - (nxt_post as f64) * 0.25;
        } else {
            // Next item cannot use this bin's leftover: dead-space penalty grows.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: make it attractive only when the item is large
    // or current bins would leave terrible fragmentation.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Opening a bin for a big item is good; for a tiny item it wastes capacity.
        score = 100.0 - frac * 70.0;
        if fitting_bins_count > 0 && item_size < 40 {
            score += 45.0; // discourage new bin for small items when alternatives exist
        }
        if next_item_size > 0 && next_item_size >= post_residual.max(0) && item_size >= 50 {
            score -= 20.0; // big item followed by another big item: fresh bin is fine
        }
    }

    // Congestion control: many open bins with high mean residual -> prefer compacting.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 40.0 && open_bins_count > 3 {
        score += (mean_residual - 40.0) * 0.15 * (1.0 - progress);
    }

    // Prefer tighter bins generally: scale by how full the bin already is.
    score -= (1.0 - bin_residual as f64 / cap) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small nonzero gaps are likely unusable
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.15);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Lookahead: gap too small for the next item is dead space
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
    }

    // Reward using a bin whose residual was already small (tight fit)
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Last-chance bonus: only bin that fits -> strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins exist (open-bin pressure)
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 25.0 + 5.0 * (open_bins_count as f64).ln();
        }
        // Opening a bin is fine if the item is huge and fits perfectly
        if item_size == bin_capacity {
            score -= 200.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (consolidate emptier space)
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: residual left exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item almost fits what remains.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer filling the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins would waste a lot.
    if bin_residual == bin_capacity {
        let waste = mean_residual - item_size as f64;
        if waste > 20.0 {
            score -= 30.0;
        } else {
            score += 20.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64) / (bin_residual as f64).max(1.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large dead space non-linearly (quadratic waste)
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / bin_capacity as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: penalize if next item could not use the leftover space
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // leftover usable by next item: reward
            score -= 0.10 * (next_item_size as f64).min(post_residual as f64);
        }
    } else {
        // last item: strongly prefer filling an existing bin
        score -= 30.0;
    }

    // Last-chance bin: this is the only bin that fits; strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: mild penalty to encourage tightest fit via base residual ordering
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global pressure: many open bins with large mean residual -> prefer reusing bins
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 0.05 * mean_residual;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let would_waste = post_residual as f64;
        // Opening a new bin is attractive early, or when no bin fits well,
        // or when the leftover would be dead space unusable by the next item
        let poor_fit_elsewhere = fitting_bins_count == 0;
        let dead_leftover = next_item_size > 0 && post_residual < next_item_size && post_residual > 15;
        let early = t < 0.25;
        if poor_fit_elsewhere || dead_leftover || early {
            score -= 35.0 + 20.0 * (1.0 - t);
        } else {
            // mid/late stream: discourage opening bins when reuse is possible
            score += 15.0 * t + 2.0 * open_bins_count as f64;
        }
        // never open a new bin for a tiny item late in the stream
        if item_size < 30 && t > 0.4 {
            score += 40.0;
        }
    }

    // Prefer bins whose residual is close to item size (tight packing)
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    // Small time-horizon modulation: later in stream, be greedier about closing bins
    score -= 5.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr);

    // Tight-fit reward: small post residual relative to capacity, stronger late in stream
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * (1.0 + progress) * (1.0 + 0.5 * tightness * tightness);

    // Penalize post residual that can't fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 0.3 * (pr - nx) / cap;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64) * 0.15;

    // Align with mean residual: prefer bins below mean residual (more filled)
    score += 0.2 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by capacity quarters are "usable".
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward residuals that are harmonic (nice) sizes: multiples of quarter or half.
    if post_residual > 0 {
        if post_residual % half == 0 {
            score -= 12.0; // perfect harmonic residual (50, 100)
        } else if post_residual % quarter == 0 {
            score -= 6.0; // quarter-harmonic (25, 75)
        } else if post_residual % 10 == 0 {
            score -= 2.0; // decade-aligned residual
        } else {
            score += 4.0; // non-harmonic dead space penalty
        }
    } else {
        score -= 30.0; // perfect closure, strongly favored
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / quarter; // 0..=4
    match class {
        0 => score -= 8.0,          // tiny leftover: near-perfect packing
        1 => score += 2.0,          // smallish residual: moderate utility
        2 => score -= 4.0,          // half-full residual: very reusable
        3 => score += 1.0,          // large residual
        _ => score += 6.0,          // nearly empty bin: wasteful placement
    }

    // Lookahead coupling: does next item fit the post residual exactly or at all?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // next item seals this bin perfectly
        } else if next_item_size <= post_residual {
            score -= 5.0; // next item still fits
        } else {
            score += 3.0; // next item won't fit here
        }
        // Harmonic pairing: next_item_size + post_residual lands on a class boundary
        let pair = post_residual + next_item_size;
        if pair % half == 0 {
            score -= 4.0;
        } else if pair % quarter == 0 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tightest fit (already via post_residual),
        // slight penalty scaled by crowd to break ties toward best fits.
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // New-bin candidate handling: only attractive early in stream or when open bins
    // are collectively full / the item fits no open bin well.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // Cheaper to open bins early in the stream (amortization).
        score -= (1.0 - progress) * 18.0;
        // More expensive when many bins already open and healthy.
        score += open_bins_count as f64 * 2.0;
        // If this bin is the only option, new bin is bad.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // If mean residual is large, open bins have room; penalize new bin less
        // only if item is large relative to mean residual (poor fits elsewhere).
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 10.0;
        }
        // Large items justify fresh bins late in the stream less.
        if item_size > 60 {
            score -= 5.0;
        }
    }

    // Mild stream-phase modulation: tighten packing as stream progresses.
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }
    // Penalize gaps that can't hold the lookahead item when a lookahead exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // New-bin candidate: penalize mildly so it's chosen only when no open bin fits well,
    // but reward it when open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
        if post_residual < 10 {
            score -= 1000.0; // opening a fresh bin beats leaving tiny gaps
        }
    }
    // Open-bin pressure: with many open bins, prefer tighter consolidation.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already favored).

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size exactly (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Exact chain match is a big win; near matches get graded reward.
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 20.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 {
        // Post-residual too small for next item: dead space unless tiny.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 8.0; // nearly-full bin is fine to "close"
        } else {
            score += 6.0 + dead * 0.15; // penalize stranded mid-size space
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let tightness = (bin_residual as f64) - mean_residual;
    score += 0.05 * tightness; // looser-than-average bins deprioritized

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if open_bins_count == 0 {
            -100.0 // must open first bin
        } else if fitting_bins_count == 0 {
            -10.0 // nothing else fits; new bin is fine
        } else {
            // open bins can fit: make new bin unattractive unless item huge
            40.0 + 0.5 * item_size as f64 * (1.0 - progress)
        };
        score += pressure;
    }

    // Mild preference for filling older/fuller bins early in stream.
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty scaled by capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += (post * post) / cap;

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize leaving a residual that exactly invites a wasteful
    // split with the next item, but reward residuals that can host next item
    // snugly (residual == next_item_size means next item fills this bin).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post as f64 - nxt;
            // Small gap after next item => good chaining; large gap => dead space.
            score += gap * 0.35;
            if gap == 0.0 {
                score -= 12.0;
            }
        } else {
            // Residual too small for next item: it becomes dead space unless tiny.
            if post_residual > 0 {
                score += 6.0 + (nxt - post) * 0.1;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make fresh bins less attractive unless the
    // item is huge relative to residual landscape or many bins are open with
    // large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        // Prefer new bin when item is large (would leave big post_residual anyway)
        // or existing bins are highly fragmented late in the stream.
        let item_frac = item_size as f64 / cap;
        let new_bin_bias = 18.0
            - 20.0 * item_frac
            - 15.0 * fragmentation * (0.5 + progress)
            - (open_bins_count as f64).min(10.0) * 0.4;
        score += new_bin_bias.max(-10.0);
    } else {
        // Slight preference for fuller bins among open ones.
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 8.0 * fill;
    }

    // Mild global pressure: when many bins are open, discourage spreading.
    score += (open_bins_count as f64).sqrt() * 0.6;

    // Time horizon: early in stream, slightly favor consolidation; late,
    // accept imperfect fits to avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: quadratic penalty on post residual, scaled by stream progress
    let mut score = prn * (1.0 + prn) * (0.5 + progress);

    // Cubic coupling: dead space increasingly costly as stream advances
    score += 2.0 * prn * prn * prn * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= (1.0 - prn) * (1.0 - prn) * progress * 0.5;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Penalize opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 0.3 + mean_residual * 0.02;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).max(0.0) * 1.5;
    }

    // Mild penalty for leaving residual near unusable small zone
    score += 1.0 / (1.0 + (prn * 10.0 - 3.0) * (prn * 10.0 - 3.0)) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 and mod 25
    let pr = post_residual;
    let class10 = pr % 10;
    let class25 = pr % 25;

    // Penalize dead space in "awkward" harmonic classes (small odd residues)
    let awkward10 = match class10 {
        1 | 2 | 3 | 4 | 6 | 7 | 8 | 9 => 8.0,
        5 => 3.0,
        _ => 0.0,
    };
    score += awkward10;

    // Reward residuals in highly reusable classes (multiples of 25, 20, 10)
    if class25 == 0 {
        score -= 12.0;
    } else if pr % 20 == 0 {
        score -= 6.0;
    } else if class10 == 0 {
        score -= 4.0;
    }

    // Integer-division tier of post_residual relative to a lookahead item
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size;
        if fits_next {
            // How many times does next item's "half" fit? finer granularity = better
            let tiers = pr / (next_item_size.max(1) / 2).max(1);
            score -= (tiers.min(4) as f64) * 5.0;
            // Perfect wrap: post residual exactly matches next item
            if pr == next_item_size {
                score -= 15.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many fitting bins: prefer tightest fit; add small penalty scaled by count
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Coupling with mean residual: penalize bins far from the mean (outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late in stream: be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual - post_residual) as f64 * 0.1 * (0.5 + progress);

    // New-bin candidate: only attractive if current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 {
            (mean_residual / bin_capacity as f64).min(1.0)
        } else {
            0.0
        };
        // Prefer new bin when open bins are mostly empty (fragmentation high)
        score -= fragmentation * 25.0 - 30.0 * (1.0 - fragmentation);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // future item (minimum item size 1, but realistically small gaps) are waste.
    // Penalize sharply when post_residual falls into a "dead zone".
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty.
            score += 30.0 + (10.0 - pr) * 3.0;
        } else if post_residual < 25 {
            // Marginal zone: moderate penalty.
            score += 8.0 + (25.0 - pr) * 0.6;
        } else {
            // Usable gap: mild reward proportional to flexibility.
            score -= (post_residual as f64).sqrt() * 1.5;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Tightness reward: the smaller the gap relative to the item, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 6.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; penalize new-bin candidate.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // unless the item is large relative to capacity.
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score += 10.0 + open_pressure * 2.0 - large_item_bonus * 12.0;
    } else {
        // Existing bin: slight reward when open bins are numerous.
        score -= (open_pressure / (open_pressure + 4.0)) * 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.2;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a gap the next item can't use.
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (closer to full), keeping high-residual bins flexible for future items.
    let my_residual = post_residual as f64;
    score += (mean_residual - my_residual) * 0.15;

    // Stream progression: late in the stream, be more aggressive about closing
    // bins tightly (dead space matters less as fewer items remain).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills relative to capacity scale.
    score *= 0.5 + 0.5 * (bin_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Strong reward for perfect two-item packing (post_residual == next_item_size).
            score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item doesn't fit: penalize leftover dead space.
            score += 0.15 * (nxt - post);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps bins interchangeable (flexible).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-preferred when the stream is early
    // and current bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is attractive if the item is small relative to capacity
        // and remaining bins are fragmented (high mean residual).
        score = 25.0 + 0.3 * mean_residual * (1.0 - progress) - (item_size as f64);
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 - item_size as f64 {
            score -= 20.0; // new bin can host current + next item together
        }
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Mild penalty proportional to how many other options exist.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0; // creates a sliver that likely wastes space
        }
        // Bonus if post_residual exactly accommodates the next item (chain fit).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // no good option exists (large item, few fitting bins, poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 {
            0.0 // forced new bin anyway
        } else {
            // Penalize opening when open bins exist; relax late in the stream.
            40.0 - 15.0 * progress
        };
        score += desperation;
        // If the item is huge relative to capacity, a fresh bin is natural.
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
        // If next item is also large, a fresh bin gives more room.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 5.0;
        }
    } else {
        // Reward using already-open bins to avoid fragmentation.
        score -= 4.0;
        // Prefer bins with residual below mean (consolidate fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Global pressure: many open bins -> favor filling existing ones harder.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score -= 1.5 * pressure.min(10.0);

    // Time horizon: early in stream, be pickier about tight fits; late, just fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: quadratic in post_residual, warped by stream progress.
    let mut score = pr * (1.0 + progress * norm_pr) + 40.0 * norm_pr * norm_pr;

    // Smooth coupling: prefer bins whose post residual matches the next item size.
    let fit_gap = (pr - nxt) / cap;
    score -= 25.0 * (-fit_gap * fit_gap * 12.0).exp();

    // Penalize tight fits that waste capacity when many bins compete.
    let tightness = item / bin_residual.max(1) as f64;
    score += 15.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus decays smoothly with progress.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress) + 6.0;
    }

    // Slight preference for bins below mean residual (consolidating slack).
    score += 5.0 * ((pr - mean_residual) / cap).tanh();

    // New-bin candidate: penalize mildly so it wins only for large items
    // or when no open bin fits well.
    if bin_residual == bin_capacity {
        score = cap - item * 0.9 + 10.0 * (1.0 - progress);
        if nxt > 0.0 && nxt > pr {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (able to hold small/medium future items) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // class A: post_residual divisible by 10 (nice round residual) -> reward
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // class B: post_residual in [1..9] tiny dead space -> penalize strongly
        if pr < 10 {
            score += 25.0 * (1.0 - pr as f64 / 10.0);
        }
        // class C: residual can host a mid-size item (>= 30) -> reward scaled
        if pr >= 30 {
            score -= 4.0 + (pr as f64 / cap) * 8.0;
        }
        // harmonic ladder: reward residuals that are exact multiples of 25
        if pr % 25 == 0 {
            score -= 5.0;
        }
    } else {
        // perfect fit: zero waste is the best outcome
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: residual quality matters, penalize big leftover after that
            let after = pr - next_item_size;
            score -= 10.0 - (after as f64 / cap) * 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline penalty so we
    // only open when existing bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 2.0;
        // but if nothing else fits well, opening is fine: soften when item is large
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Tightness reward: bins that become very full are preferred
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * fill * 12.0;

    // Mean-residual coupling: prefer bins below mean residual (denser bins)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Stream progression: late in the stream, avoid leaving medium dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item (<= 3 units),
    // or if it's a small sliver that likely wastes capacity.
    let pr = post_residual;
    if pr > 0 && pr <= 3 {
        score += 60.0; // completely unusable sliver
    } else if pr > 0 && pr <= 10 {
        score += 25.0; // near-dead gap: only tiny items could use it
    } else if pr > 10 && pr < 20 {
        score += 8.0; // awkward mid-range gap
    }

    // Reward near-perfect fits strongly (waste close to zero).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 12.0;
    }
    // Penalize if post-residual is just barely too small for the lookahead item (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (new-bin candidate has bin_residual == bin_capacity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        score += 40.0 + 8.0 * open_bins_count as f64 + 30.0 * progress;
        // But if no open bin gives a decent fit (all would leave tiny gaps),
        // opening a fresh bin is fine: soften the penalty.
        if post_residual == bin_capacity - item_size && item_size >= bin_capacity / 2 {
            score -= 55.0; // large item deserves a fresh bin
        }
    } else {
        // Existing bin: slight reward for consolidating when many bins are open.
        score -= 2.0 * open_bins_count.min(20) as f64 * 0.5;
    }

    // Prefer bins with below-mean residual (they are the "tight" bins to fill first).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Exact match for the next item is highly desirable.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Bin can also host the next item: reward tight chained fits.
            score -= 8.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 4.0 * diff / (bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let resid = bin_residual as f64;
    score += (resid - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large relative to capacity (poor fit elsewhere) or no real bin fits.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * large;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin can host the item
        }
    }

    // Mild progression scaling: early in the stream, be slightly more willing
    // to spread items (keep residuals flexible for future variety).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual non-linearly (dead space grows superlinearly bad)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Perfect / near-perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            // post_residual too small for next item: penalize proportionally to waste
            score += 10.0 * (post_residual as f64 / next_item_size as f64);
        }
        // If next item fits perfectly in post_residual, extra reward
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item in stream: strongly prefer filling existing bins, avoid opening new bins
        score += 15.0 * frac;
    }

    // Global state: when many open bins with slack, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, reduced when open bins are fragmented
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 55.0 + 40.0 * (1.0 - fragmentation) - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with large items coming
        }
    } else {
        // Existing bin: slight preference when its residual is below mean (well-packed bin)
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
        // Encourage closing out nearly-full bins as stream progresses
        score -= 12.0 * (1.0 - frac) * (0.5 + 0.5 * progress);
    }

    // Mild pressure to consolidate when bin count is high
    score += 0.3 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress in [0, 1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;

    // Non-linear polynomial coupling: tight fits are rewarded more as the stream progresses.
    // Perfect fit (post_residual == 0) gets a strong discount, modulated by progress.
    let perfect_fit = 1.0 - (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= perfect_fit * (10.0 + 40.0 * progress_sq);

    // Penalize residual space in a non-linear way: small leftovers (dead space) are
    // quadratically worse as stream progresses, since remaining capacity to fill them shrinks.
    let dead = post_residual as f64 / bin_capacity as f64;
    let dead_penalty = dead * dead * (1.0 - dead);
    score += dead_penalty * (30.0 + 50.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoids opening a new bin), scaled smoothly by progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 35.0 * progress_sq;
    }

    // Lookahead coupling: if the next item exactly fits the post residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= (1.0 - gap) * (15.0 + 25.0 * progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is low
    // (bins are nearly full already); smooth interaction with progress.
    let mean_coupling = (mean_residual / bin_capacity as f64).powi(3);
    score += mean_coupling * 10.0 * (1.0 - progress);

    // New-bin candidate: empty bin gets a baseline cost so it's only chosen when
    // open bins are genuinely poor fits; cost grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 5.0 + 30.0 * progress_sq;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 act as "dead space classes"
    let post = post_residual as i64;
    let residue_class = (post % 10) as i64;
    // Penalize residuals that fall into awkward classes (1..9 not multiples of 5/10)
    let awkward = if residue_class == 0 { 0.0 }
        else if residue_class % 5 == 0 { 2.0 }
        else { 5.0 };
    score += awkward;

    // Reward near-perfect fits strongly
    if post == 0 { score -= 60.0; }
    else if post <= 5 { score -= 25.0; }
    else if post <= 10 { score -= 12.0; }

    // Fraction of capacity wasted
    let waste_frac = post as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post as u32 { score -= 45.0; }
        else if next_item_size <= post as u32 { score -= (post - next_item_size as i64) as f64 * 0.5; }
        else { score += 3.0; }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 30.0; }

    // Penalize opening new bins when open bins can fit, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
        if fitting_bins_count > 0 { score += 20.0; }
    }

    // Prefer bins below mean residual (consolidate emptier bins' usage)
    score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.4;

    // Slight preference for bins with larger current residual when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - post as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are dead space; residuals below a "practical" threshold are heavily penalized.
    let practical_min = 10u32;
    if post_residual < practical_min {
        score += 25.0; // unusable sliver
    } else if post_residual < 2 * practical_min {
        score += 8.0; // risky small gap
    }

    // Reward near-perfect fits (waste < 5).
    if post_residual < 5 {
        score -= 15.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins would waste a lot
    // or the fit is poor. Penalize opening bins when a decent fit exists.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            // opening a new bin while others fit: penalize unless fit would be terrible
            score += 20.0 + 30.0 * (1.0 - fit_quality);
        }
        // lookahead: if next item is small, keep a fresh bin anyway (reward)
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 10.0;
        }
    } else {
        // Reward using an existing bin whose residual matches next item size well.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize leaving a gap that next item cannot use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + 0.5 * progress);

    // Prefer bins with residuals close to the mean (keeps bin states balanced).
    score += ((post_residual as f64 - mean_residual) / (bin_capacity as f64)).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect two-item fill: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too: reward tightness of the two-item chain
            let chain_waste = post_residual - next_item_size;
            score -= 25.0 - (chain_waste as f64).min(25.0);
        } else {
            // Next item does NOT fit: penalize by how far off the match is
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * miss;
        }
    } else {
        // Last item: prefer leaving zero residual
        score += 0.2 * post_residual as f64;
    }

    // --- Relative-to-mean coupling ---
    // Bins with residual below mean are tighter; reward packing them further down.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 {
        // Only this bin can fit the item: strongly favor using it to avoid a new bin
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Many options: mild penalty to encourage diversity of choice among tightest bins
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // --- Dead-space penalty (non-linear) ---
    // Small residuals that can't hold the minimum item (1) are fine; but residuals
    // in an awkward mid-range create unusable dead space.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0; // tiny slivers are dead space
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus pressure from open bins.
        // Prefer new bin only late in stream when open bins are mostly full (high mean fill).
        let mean_fill = bin_capacity as f64 - mean_residual;
        score = 70.0 - 0.2 * mean_fill + 3.0 * open_bins_count as f64 * (1.0 - progress);
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0; // fresh bin perfectly set up for next item
        }
        if fitting_bins_count == 1 {
            score += 100.0; // never open a new bin when an existing one is a last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that no plausible future item can fill:
    // post-residual smaller than the smallest item (1) is perfect; otherwise
    // penalize residuals that are too small for typical items but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // nearly unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 4.0; // next item can still go here
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.15 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is reasonable when the item is large or fits poorly elsewhere.
        let load = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins for big items late in the stream; penalize for small items early.
        score -= 30.0 * load * (0.5 + progress);
        score += 12.0 * (1.0 - load) * (1.0 - progress);
        // If many bins are open with slack, discourage yet another bin.
        if open_bins_count > 3 && mean_residual > (item_size as f64) * 1.5 {
            score += 20.0;
        }
        // Never open a new bin if this is the last chance bin elsewhere.
        if fitting_bins_count >= 1 {
            score += 5.0 * (fitting_bins_count as f64);
        }
    }

    // Mild preference for fuller bins relative to the fleet average residual.
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // Time horizon: early on, be slightly conservative (keep bins flexible);
    // late in the stream, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear (quadratic) waste growth
    let mut score = post + 12.0 * post * norm_post;

    // Smooth coupling: tight fits matter more as the stream progresses
    let tightness = 1.0 - norm_post; // 1 = perfect fit
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Reward using an existing bin vs opening a new one (new bin has full residual)
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 6.0 + 10.0 * (1.0 - progress);
    } else {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor it to avoid opening a bin for one item
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (0.5 + progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 6.0 * (1.0 - (post - next) / cap);
        } else {
            score += 4.0 * (next - post) / cap;
        }
    }

    // Contextual coupling with mean residual: prefer bins near the mean (smoothness)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * tightness * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "nice"
    // residue classes (multiples of 10 / small divisors of capacity) are
    // more reusable, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let pr_f = pr as f64;

    // Perfect fit: zero dead space is ideal.
    if pr == 0 {
        score -= 200.0;
        return score;
    }

    // Harmonic class: post_residual divisible by 10 (aligned leftovers).
    if pr % 10 == 0 {
        score -= 15.0;
    }
    // Divisible by 5 but not 10: second-tier alignment.
    else if pr % 5 == 0 {
        score -= 7.0;
    }

    // Small residues are hard to fill: penalize tiny dead space
    // (anything < 10 is likely unusable since min item is small but
    // fragmentation still wastes capacity).
    if pr < 10 {
        score += 25.0;
    } else if pr < 20 {
        score += 8.0;
    }

    // Modular bucket of post_residual relative to capacity quarters:
    // leftover in the top quarter means the bin stays broadly usable.
    let quarter = cap / 4.0;
    if pr_f >= 3.0 * quarter {
        score -= 12.0;
    } else if pr_f < quarter {
        score += 10.0;
    }

    // Integer-division threshold: does next_item_size fit exactly into
    // the leftover? Reward exact lookahead fit (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // reward proportional to how well next item divides the leftover
            let rem = pr % next_item_size;
            if rem == 0 {
                score -= 25.0;
            } else {
                score -= (next_item_size as f64 / pr_f) * 10.0;
            }
        } else {
            // next item cannot use this bin anyway; mild penalty if the
            // leftover is large and would strand capacity
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when the
    // stream is early (lots of future items to fill it) and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 60.0 * progress - (item_size as f64) * 0.3;
        // prefer new bin when existing bins are fragmented
        score += mean_residual * 0.15;
    }

    // Mild global pressure: many open bins -> prefer consolidating into
    // existing ones (penalize new-bin style large leftovers).
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 2.0;
    } else if post_residual == 0 {
        // Perfect closure is ideal: strongly reward.
        score -= 30.0;
    } else {
        // Usable gap: mild quadratic penalty to prefer tighter fits.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 4.0);
    }

    // Reward fitting into a bin whose gap exactly anticipates the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap can't host the next item: penalize proportionally to how close it is to being useful.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: bins far below the mean residual are "loose"; prefer them slightly.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // New-bin candidate: only attractive when the current item is large relative to capacity
    // (poor fit anywhere) or late in the stream where tight packing has stabilized.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        let stream_phase = step_index as f64 / (total_items.max(1) as f64);
        score -= large_item_bonus + stream_phase * 5.0;
        // But if a last-chance open bin exists, opening new is bad.
        if fitting_bins_count <= 1 && bin_residual < bin_capacity {
            score += 50.0;
        }
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (small post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect match: next item exactly fills the post residual
        if post == next {
            score -= 120.0;
        }
        // Next item fits in the post residual: reward closeness of the
        // double-fill (residual after both items would be small)
        else if post > next {
            let second_residual = post - next;
            score -= 60.0 * (1.0 - second_residual / bin_capacity as f64);
            // Extra bonus for near-perfect double fit
            if second_residual <= 5.0 {
                score -= 40.0;
            }
        }
        // Next item does NOT fit here: penalize proportionally to how
        // much dead space remains relative to the next item's size
        else {
            let gap = next - post;
            score += 0.8 * gap;
            // If the leftover is tiny (unusable dead space), penalize hard
            if post <= 5.0 {
                score += 30.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are
    // "denser" — placing here consolidates space and is favored.
    let rel = (post_residual as f64) - mean_residual;
    score += 0.35 * rel;

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize it mildly so tight existing
    // fits win, but not so much that a hopeless existing bin is chosen.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, keep bins consolidated: empty bins less attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins that are already fairly full
    score -= 0.2 * ((bin_capacity - bin_residual) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(2) * 20.0;

    // Penalize post-residuals that are too small to be useful for future items
    // (dead space below the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer zero waste absolutely.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    score -= (bin_residual as f64 / bin_capacity as f64) * pressure * 10.0;

    // Global residual alignment: reward bins below mean residual (fuller than average).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Time horizon: early in the stream, be pickier (penalize large post-residuals more);
    // late in the stream, just close bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (1.0 - t) * 0.5;

    // New-bin candidate: only attractive when no open bin fits well
    // (this bin is empty, so post_residual == capacity - item_size is large).
    if bin_residual == bin_capacity {
        let best_open_penalty = if fitting_bins_count == 0 { -40.0 } else {
            // discourage opening new bins when existing ones fit, scaled by how many
            10.0 + fitting_bins_count as f64 * 5.0 + mean_residual * 0.1
        };
        score += best_open_penalty;
        // Opening a bin is worse late in the stream (fewer chances to fill it).
        score += t * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress) * 0.5;

    let mut score = pr + poly * cap;

    // Penalize opening a new bin early, less so later
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (10.0 + 20.0 * (1.0 - progress)) + new_bin * pr * 0.1;

    // Reward tight fits: subtract when post_residual is small relative to item size
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tightness * 15.0 * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: penalize if next item could use this residual better
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 2.0 * ((nxt - pr) / cap);
        }
    }

    // Mild pressure toward bins below mean residual (compactness)
    score += 0.3 * ((pr - mean_residual) / cap).max(-1.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (<10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score += 15.0;
    }

    // Reward if the leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = 70.0 + 0.5 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in stream, opening fresh bins is cheap; later it is costly.
        score += 30.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild tie-breaking toward bins with residual close to item size (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Slight nudge using mean residual: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post_residual (perfect chaining), mild penalty for overshoot.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap == 0.0 {
            score -= 40.0; // next item fits perfectly -> excellent chain
        } else if gap > 0.0 {
            score -= 25.0 * (-gap / 20.0).exp(); // next item fits, decaying reward
        } else {
            score += (-gap) as f64 * 0.6; // next item won't fit: penalize wasted chain
        }
    } else {
        // Last item: only post_residual matters; squeeze maximally.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tight"
    // resources; placing there preserves loose bins for awkward items.
    let rel = post_residual as f64 - mean_residual;
    score += 0.35 * rel;

    // Dead-space penalty: post_residual too small for any future item
    // (min size 1, but typical small items ~10): strongly discourage
    // residuals in the awkward 1..=9 band.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early in the stream and when
        // many bins are already open; relax late when consolidation fails.
        score += 60.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if the next item is huge, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Slight preference to keep open-bin count low.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already does this; amplify non-linearly)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits into post_residual, reward this bin strongly
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let chain_tightness = (post_residual as u32 - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * (1.0 - chain_tightness);
    } else if next_item_size > 0 {
        // Next item cannot chain here; penalize leaving medium-size dead space
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 0.35 * (next_item_size as f64 - dead);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residuals below the mean (compact bins), penalize above-mean
    let dev = bin_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Mild preference for using existing bins over opening new ones as stream grows
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream
        score += 6.0 + 10.0 * progress + 0.4 * open_bins_count as f64;
    } else {
        score -= 2.0 + 3.0 * progress;
    }

    // Penalize very small unusable slivers unless item nearly fills bin
    if post_residual < 10 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on mid-size gaps.
    let mut score = post * (1.0 + 0.9 * (post / cap) * (1.0 - post / cap));

    // Smooth coupling of post_residual with stream progress:
    // early on, tolerate larger gaps slightly; later, penalize them more.
    score += 12.0 * (post / cap).powi(2) * (0.3 + 0.7 * progress);

    // Lookahead synergy: reward residual that can host the next item.
    if next > 0.0 && post >= next {
        let fit_ratio = next / post;
        score -= 8.0 * fit_ratio * (1.0 - fit_ratio) * (1.0 - 0.5 * progress);
    } else if next > 0.0 {
        // penalize blocking the next item
        score += 4.0 * (next - post) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balance),
    // scaled smoothly by number of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - (-open_bins_count as f64 / 8.0)).min(1.0);

    // New-bin candidate: make empty bins moderately attractive only when
    // existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        score = post + 20.0 - 18.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction of post residual
    let frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic classes: classify post_residual into residue classes mod small integers.
    // Residuals that are "perfect fill" classes (0, or tiny) get strong rewards.
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;
    let mod50 = post_residual % 50;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space is bad if it can't host a typical small item (min size 10).
        if post_residual < 10 {
            score += 40.0; // unusable sliver
        }
        // Harmonic class rewards: residuals divisible by 10/25/50 are reusable
        if mod10 == 0 { score -= 6.0; }
        if mod25 == 0 { score -= 10.0; }
        if mod50 == 0 { score -= 14.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize by leftover after next placement
            let next_left = post_residual - next_item_size;
            score += next_left as f64 * 0.4;
            if next_left % 10 == 0 && next_left > 0 { score -= 3.0; }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Integer-division threshold on fill ratio of the item itself
    let quarters = (item_size * 4) / bin_capacity; // 0..3 integer division class
    match quarters {
        3 => score -= 12.0,           // item >= 75%: good packing
        2 => score -= 4.0,            // 50-75%
        1 => score += 3.0,            // 25-50%
        _ => score += 6.0,            // tiny item into big residual: wasteful
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when residuals are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits are preferred.
        score += 30.0;
        // But if mean residual is small (open bins nearly full), opening new bin is fine.
        score -= mean_residual * 0.5;
        // Late in the stream, prefer consolidating.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Mild preference for bins with residual close to item size (tight fit)
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score += tight * 0.05;

    // Penalize creating residual just below common item sizes (dead zones)
    for threshold in [10u32, 20, 30, 40, 50] {
        if post_residual < threshold && bin_residual >= threshold {
            score += 8.0;
        }
    }

    // Fractional tie-breaker on capacity fraction
    score += frac * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1, but practically small gaps) are waste.
    // Penalize gaps below a "useful threshold" superlinearly.
    let gap = post_residual as f64;
    let useful_threshold = 12.0;
    if gap < useful_threshold {
        score += (useful_threshold - gap) * (useful_threshold - gap) * 1.5;
    }

    // Reward near-perfect fits.
    if gap <= 3.0 {
        score -= 30.0;
    } else if gap <= 8.0 {
        score -= 10.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: prefer spreading load when few bins are open,
    // prefer consolidation (avoid opening new bins) when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += bin_pressure * 0.8 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item: penalize.
        score += 6.0;
    }

    // New-bin candidate: only attractive when the current item is large
    // relative to remaining residuals (poor fit everywhere) or no bins fit.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64) - (item_size as f64);
        // Base cost of opening a bin; reduced when item is big.
        score = 40.0 - 0.3 * (item_size as f64) + 0.5 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        let _ = poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins where the next item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 45.0 + slack_after_next as f64 * 0.25;
        } else {
            // Penalize dead space that the next item cannot use,
            // scaled by how wasted the gap is.
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += gap * 0.35;
        }
    } else {
        // Last item: just prefer the tightest fit.
        score += post_residual as f64 * 0.5;
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make it attractive only when no open bin
    // offers a good fit (post_residual would be large / dead space high).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slight penalty so open bins with tight fits win.
        score += 55.0;
        // But if the item is large relative to mean residual, opening fresh
        // may be better than fragmenting.
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    // Penalize leaving residuals that are awkwardly small but nonzero
    // (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 18.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 12.0;
        } else {
            // Next item won't fit here; slight penalty for leaving a large unusable gap.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Penalize opening a new bin unless it's early in the stream or no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let good_fit_exists = fitting_bins_count > 1 || (fitting_bins_count == 1 && post_residual < 15);
        let open_bonus = (open_bins_count as f64).sqrt() * 3.0;
        score += 45.0 + open_bonus;
        if !good_fit_exists {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 20.0;
    }

    // Mild preference for bins with below-average residual (keep very full bins tight,
    // prefer to drain emptier bins so they can be closed out).
    score += ((bin_residual as f64) - mean_residual) * 0.08;

    // Small penalty for large leftover space relative to item sizes.
    score += (post_residual as f64).powf(1.3) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // wasted space becomes increasingly costly as the stream matures.
    let w = 0.5 + 2.5 * progress * progress;
    score += w * pr * pr / cap;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead: reward if the next item fits the post-residual exactly-ish,
    // penalize if next item cannot use the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill = nxt / pr.max(1.0);
            score -= 6.0 * fill * (1.0 + progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 4.0 * gap * gap * cap / cap.max(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening new bins mildly, more when
    // open bins exist and the item fits comfortably elsewhere.
    if bin_residual == bin_capacity {
        let base_penalty = 10.0 + 20.0 * progress;
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += base_penalty * (1.0 - mean_fill * 0.5) * (1.0 + open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Slight preference for bins with residuals close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (10,20,25,50) are "reusable" classes and get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr > 0 {
        if pr % 50 == 0 { harmonic_bonus += 18.0; }
        else if pr % 25 == 0 { harmonic_bonus += 10.0; }
        else if pr % 20 == 0 { harmonic_bonus += 8.0; }
        else if pr % 10 == 0 { harmonic_bonus += 5.0; }
        // dead-space penalty: tiny unusable remainders
        if pr < 10 { harmonic_bonus -= 30.0 + (10 - pr) as f64 * 3.0; }
    } else {
        // perfect fit
        harmonic_bonus += 25.0;
    }
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain completion).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if pr >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted class
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor. Base its score on mean residual pressure and stream phase.
    if bin_residual == bin_capacity {
        let phase = step_index as f64 / (total_items.max(1) as f64);
        // later in the stream, prefer consolidating into open bins
        score += 20.0 + 25.0 * phase + 0.15 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Tight fit reward: reward bins whose residual is consumed to a low
    // harmonic fraction of capacity (<= 20% left).
    let frac = post_residual as f64 / cap;
    if frac <= 0.2 && post_residual > 0 {
        score -= 10.0 * (0.2 - frac) * 5.0;
    }

    // Mild pressure to close nearly-full bins when many bins are open.
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64 * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical future items
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Last-chance bonus: avoid opening a bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Slight pull toward mean residual alignment
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // New-bin candidate: mildly penalize so only clearly better fits open new bins
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space matters super-linearly).
    let dead = post_residual as f64;
    score += 0.08 * (dead * dead) / bin_capacity as f64;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect 2-item chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // Last item: only current fit matters; reward tight fits.
        score -= 15.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Reward bins whose residual is already below average (consolidating small bins).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Discourage opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * (item_size as f64) / bin_capacity as f64;
        score += 20.0 + 15.0 * (1.0 - progress) + pressure;
        // If item is large relative to mean residual, new bin is more acceptable.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed: dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core tightness reward: strongly favor bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead (k=2): reward if the next item can fit into the resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chains nicely, but keep some slack awareness.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            // Next item barely misses: small penalty for near-miss residual.
            score += 3.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * tightness;
        if post_residual > bin_capacity / 2 {
            score += 6.0; // but a very wasteful fit loses the advantage
        }
    }

    // Crowding: with many open bins, prefer consolidating into existing ones
    // (penalize opening new bins when the bin pool is already large).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Global residual pressure: if mean residual across bins is low, opening
    // a fresh bin (which has bin_residual == bin_capacity) is relatively cheap;
    // if mean residual is high, discourage wasting a mostly-empty bin.
    let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 5.0 * mean_residual / bin_capacity as f64 * (1.0 - tightness);

    // Late in the stream, be more conservative: penalize residual waste more.
    score += post_residual as f64 * 0.1 * progress;

    // Mild penalty when this bin's residual is much larger than needed
    // (prefer bins whose residual is close to the item size).
    let slack_ratio = (bin_residual as f64 / item_size.max(1) as f64).min(10.0);
    score += 1.5 * slack_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: penalize wasted space non-linearly (quadratic dead space)
    let mut score = r * (1.0 + 0.9 * norm_r * norm_r);

    // Smooth polynomial coupling of residual waste with stream progress:
    // early on, waste is cheap; later, tight packing matters more.
    let coupling = r * (1.0 - progress) * 0.35 - r * progress * 0.55;
    score += coupling * (0.5 + norm_r);

    // Reward filling bins nearly exactly, smoothly via cosine-like polynomial term
    let fill = 1.0 - norm_r;
    score -= 12.0 * fill * fill * (2.0 - fill);

    // Last-chance bonus: strongly favor the only bin that fits, scaled by progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (0.4 + progress);
    }

    // Lookahead: reward leaving room for the next item (smooth residual match)
    if next_item_size > 0 {
        let diff = (r - next_item_size as f64).abs();
        score += 0.15 * diff * (1.0 + progress);
    }

    // Slight penalty for spreading across many open bins when residuals are large
    score += 0.02 * open_bins_count as f64 * (mean_residual - r).abs() / cap;

    // New-bin candidate: penalize opening a bin mildly, more as stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (multiples of small divisors) are more valuable.
    let pr = post_residual;
    let usable = if pr == 0 { 4.0 }
        else if pr % 10 == 0 { 2.0 }
        else if pr % 5 == 0 { 1.0 }
        else { 0.0 };
    score -= usable * 12.0;

    // Penalize dead space: post_residual too small for the smallest item (1..100 unknown,
    // assume min ~10) but nonzero => likely waste.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit bonus scaled by how tight the fit is.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * tightness * 20.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, big reward (chained placement).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.1;
        } else {
            // Next item cannot use leftover; penalize proportionally to waste.
            score += pr as f64 * 0.15;
            // If next item would exactly fill a fresh bin, opening a new bin is attractive.
            if next_item_size == bin_capacity {
                score += 20.0;
            }
        }
    }

    // Harmonic division thresholds on post_residual (quarters of capacity).
    let q = bin_capacity / 4;
    if pr == q || pr == 2 * q || pr == 3 * q {
        score -= 8.0;
    }

    // Prefer consolidating into few bins early; allow spreading later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Mean residual coupling: placing into a bin far below mean residual is fine;
    // avoid draining bins well below the mean (keeps flexibility).
    if (bin_residual as f64) < mean_residual - 20.0 {
        score += 6.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score -= 4.0;
    }

    // New-bin candidate: neutral baseline, only chosen when it beats existing bins.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity - 5 {
            score -= 25.0; // next item nearly fills a bin; fresh bin is good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are heavily penalized.
    let min_gap = 1u32;
    if post_residual < min_gap {
        score += 1000.0;
    } else if post_residual <= 10 {
        // Tiny dead space (below min item size) is wasted forever.
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // Extra reward for near-exact next-fit.
            let gap_next = post_residual - next_item_size;
            if gap_next <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: residual likely becomes dead space.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: encourage filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 1.4 * progress);

    // New-bin candidate calibration: make empty bin attractive only when
    // current bin would leave a large, next-item-unusable residual.
    if bin_residual == bin_capacity {
        // Neutral-ish base; dead-space penalties above apply via post_residual.
        score -= 5.0;
        // Prefer new bin early in stream when few bins open.
        score -= (open_bins_count as f64) * 2.0;
    }

    // Slight preference for bins with below-average residual (tighter bins first).
    let diff = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += diff * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect 2-step fill is highly desirable.
            let exact = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - exact / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize dead space creation.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter or looser than average adaptively.
    let residual_f = bin_residual as f64;
    let dev = residual_f - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins can fit, more so early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
    }

    // Slight penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    score -= 60.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize leaving dead space that nothing (typical min size ~1) could use later.
    if post_residual < 10 {
        score -= 25.0; // nearly full bin is excellent
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use this bin's leftover: mild penalty for wasting space
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless it is the only option
    // or the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        score += 70.0 - 40.0 * pressure * pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins harder (avoid fragmentation).
    if open_bins_count > 2 {
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 10.0 * crowding * (open_bins_count as f64).ln();
    }

    // Time horizon: early on, keep bins balanced (mild); late, greedy tight fits dominate.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (low post residual), scaled by a smooth
    // progress-dependent polynomial coupling.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty on very small post residual relative to capacity:
    // dead space that nothing can use is worse late in the stream.
    let dead = (pr / cap).powi(3);
    score += 40.0 * dead * (0.5 + progress);

    // Reward filling a bin deeply (item large relative to residual).
    let fill = it / bin_residual.max(1) as f64;
    score -= 12.0 * fill * (1.0 - fill) * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 10.0 * (1.0 - (nxt / cap)) * (1.0 + 0.5 * (1.0 - progress));
        } else {
            // post residual too small for the next item: penalize proportionally
            score += 8.0 * ((pr - nxt).abs() / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    // Deviation from mean residual: prefer bins that are outliers (nearly full
    // or nearly empty) to consolidate waste.
    let dev = (pr - mean_residual) / cap;
    score -= 6.0 * dev * dev.abs() * (0.5 + progress);

    // New-bin candidate: slight bias so a new empty bin is chosen only when
    // open bins are genuinely poor fits (its pr is high, so base score already
    // penalizes it; add a small opening cost that fades as stream progresses).
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification by modulo classes
    let pr = post_residual;
    let small_dead = if pr == 0 { 0.0 } else if pr < 10 { 3.0 } else { 0.0 };
    score -= 6.0 * (pr == 0) as i32 as f64; // perfect fit strongly rewarded

    // Modulo-10 harmonic class: residuals in {0,10,...} are reusable by typical sizes
    let harmonic = (pr % 10) as f64;
    score += 0.35 * harmonic;

    // Integer division thresholds: post_residual bucket
    let bucket = pr / 20; // 0..5
    score += match bucket {
        0 => 2.0,   // tiny residual, nearly dead unless 0
        1 => 0.0,
        2 => -0.5,
        3 => -1.0,
        _ => -1.5,  // large residual still flexible
    };

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 1.5;
    }
    // Reward residual that exactly matches next item (chain fit)
    if next_item_size > 0 && pr == next_item_size {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: keep it neutral-good only when current fit is bad
    if bin_residual == bin_capacity {
        score += 12.0; // default: prefer existing bins
        if fitting_bins_count <= 1 {
            score -= 10.0; // but allow new bin if no real alternative
        }
    }

    // Small dead-space penalty for very tight fits creating <10 residue
    score += small_dead;

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.02;

    // Prefer bins with below-mean residual (consolidate emptiness)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a future
    // item (min item size = 1 here, but practically small gaps are waste).
    // Penalize gaps that are unusable for the known next item.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Dead space relative to lookahead: gap can't fit next item.
            score += 12.0 + 0.35 * post_residual as f64;
        }
        // Absolute tiny-gap penalty (dead space regardless of lookahead).
        if post_residual <= 3 {
            score += 18.0;
        } else if post_residual <= 8 {
            score += 8.0;
        }
    } else {
        // Perfect fit: heavily reward.
        score -= 30.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure on number of open bins: when many bins are open, prefer
    // consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.25 * progress);

    // New-bin candidate: neutral-ish but penalize opening new bins while
    // mean residual across open bins is still large enough to be useful.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.10 * mean_residual;
    } else {
        // Slight preference for existing bins whose residual is close to mean
        // (avoid starving one bin while others stay fat).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // If this bin can also fit the next item, small bonus for flexibility.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain: post_residual == next_item_size -> big bonus
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to overshoot
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 * (miss / look).min(1.0);
        }
    } else {
        // Last item: just minimize post residual
        score -= 10.0;
    }

    // Penalize large dead space relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin wastes capacity; penalize unless
    // current bin fit is very poor (large post_residual) and many bins open
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score = waste + 30.0;
        // If no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Small bonus for keeping number of open bins low
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
        // Exact chaining: perfect pair fit.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        let threshold = 15.0 + 25.0 * (1.0 - progress);
        if fragmentation > threshold {
            score -= 18.0; // open a fresh bin rather than fragment further
        } else {
            score += 10.0; // prefer reusing open bins
        }
    }

    // Mild preference for filling bins with larger residuals when many bins are open.
    score -= 0.05 * bin_residual as f64 / open_bins_count.max(1) as f64;

    // Late-stream pressure: consolidate as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - x) * (1.0 - x));

    // Penalize dead space non-linearly, more so late in the stream
    score += 12.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post_residual) with cubic term
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for consolidating bins when many are open
    score += 0.3 * open_bins_count as f64 * x;

    // Deviation from mean residual: prefer bins near the mean
    let dev = (pr as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize mildly so it is chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small divisors
    // capture "nice" leftover spaces that pair well with common item sizes.
    let post = post_residual as i64;
    let mod5 = post % 5;
    let mod10 = post % 10;
    let mod20 = post % 20;

    // Reward residuals that are multiples of 10 (harmonic with capacity 100)
    if mod10 == 0 && post > 0 {
        score -= 6.0;
    } else if mod5 == 0 {
        score -= 3.0;
    } else {
        // penalize awkward residues, worse near small primes
        score += (mod5 as f64) * 0.8;
    }

    // Integer-division thresholds on post_residual: dead-space zones
    let quarter = bin_capacity / 4;      // 25
    let eighth = bin_capacity / 8;      // 12
    if post < eighth && post > 0 {
        score += 10.0; // nearly-unusable sliver
    } else if post < quarter && post > 0 {
        score += 4.0;
    }

    // Coupling with lookahead: does the next item fit the post-residual?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt <= post {
            // prefer exact harmonic match: post % nxt small
            let r = (post % nxt.max(1)) as f64;
            score -= 5.0 - r * 0.3;
            if nxt == post {
                score -= 12.0; // perfect fill
            }
        } else {
            score += 3.0; // next item can't use this bin's leftover
        }
    } else {
        // last item: maximize fill
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it neutral-ish unless open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // open new bin when mean residual across open bins is small (fragmented)
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 {
            score -= 4.0 + 6.0 * (1.0 - progress);
        } else {
            score += 8.0 + fragmentation * 10.0;
        }
    }

    // Mild pressure toward tight packing as stream progresses
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Tie-break toward bins with residuals close to item size (best fit flavor)
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score += gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized (they become waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward snug fits relative to the item size (small slack ratio).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 20.0 * fit_ratio.min(3.0);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize adding more bins when many are open,
    // making consolidation attractive.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: if the next item fits into the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would NOT fit in post-residual, mild penalty for blocking.
    if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Prefer reusing existing bins unless current bin is a bad fit.
        // Base cost for opening a new bin, reduced early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 40.0 * progress - 0.3 * open_bins_count as f64;
        // If no open bin can even fit the item, opening is mandatory-ish.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 40.0;
        }
    }

    // 2-step lookahead: reward if next item exactly fits post_residual,
    // penalize if next item can't fit into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > post_residual {
            // Dead space the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 3.0;
        } else {
            // Next item fits: prefer leaving room proportional to its size.
            score -= (post_residual - next_item_size) as f64 * 1.5;
        }
    }

    // Compare against mean residual: prefer bins below-average residual
    // (fill the fullest bins first, keeping large residuals for large items).
    score += (mean_residual - bin_residual as f64).max(0.0) * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when other
    // bins fit and the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 150.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 250.0;
        }
        // Late in the stream, opening a fresh bin is less costly (fewer
        // future items to serve), so relax the penalty slightly.
        new_bin_penalty *= 1.0 - 0.3 * progress;
        // Large items relative to capacity deserve fresh bins.
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 100.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Slight preference for bins whose residual is close to item_size
    // (best-fit style refinement).
    let waste = (bin_residual - item_size) as f64;
    score += waste * waste / (bin_capacity as f64 * 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can still host the lookahead item.
            score -= 1.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
        } else {
            // Dead space penalty: wasted residual below next item size.
            score += 3.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Discourage opening new bins when plenty of open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with congestion.
        score += 15.0 + 2.0 * (open_bins_count as f64);
        // Early in the stream, new bins are cheaper; later, avoid proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.4 * mean_residual;
    }

    // Mild preference for bins below mean residual (consolidate fragmented space).
    score += 0.2 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits, with non-linear (quadratic) penalty on leftover space
    let mut score = pr + 0.9 * (pr / cap) * (pr / cap) * cap;

    // Smooth coupling: as stream progresses, tighten preference for small residuals
    score += progress * 6.0 * (pr / cap).powi(2) * cap;

    // Penalize bins whose residual is much larger than the mean (poor consolidation)
    score += 0.5 * (br - mean_residual).abs() * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 3.0 * (1.0 - snug / cap) * (1.0 - progress);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space that cannot serve the next item
        score += 1.5 * (pr / cap) * cap * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are nearly full
    if bin_residual == bin_capacity {
        let waste = (pr) as f64; // residual of a fresh bin = capacity - item
        score = cap - it + 10.0 + 0.3 * open_bins_count as f64;
        // open new bin more willingly early in the stream
        score -= 6.0 * (1.0 - progress);
        // if many open bins have slack, discourage a new bin
        score += 0.2 * mean_residual * (open_bins_count as f64).sqrt();
        // if item is small, a new bin wastes proportionally more
        score += 4.0 * (1.0 - it / cap);
        let _ = waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small divisors) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual (tight fit) nonlinearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 30.0;
    } else {
        // dead-space penalty grows for unusable leftovers
        let dead = if post_residual < 10 { 0.0 } else { pr };
        score += 0.35 * dead;
    }

    // Modulo arithmetic on post_residual: leftovers divisible by small
    // harmonics (2,4,5,10) are more likely reusable by future items.
    let h = if post_residual % 10 == 0 {
        0.0
    } else if post_residual % 5 == 0 {
        3.0
    } else if post_residual % 2 == 0 {
        6.0
    } else {
        10.0
    };
    score += h;

    // Fraction of capacity used by this item: reward large fill fractions.
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 12.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item cannot fit here; leftover likely wasted
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 55.0 + 5.0 * open_bins_count as f64 };
        score += pressure;
        // If mean residual is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual;
    }

    // Late-stream conservatism: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / cap);

    // Mild penalty for too many open bins (fragmentation control).
    score += 0.8 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize moderately small gaps that few items can use.
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // but allow consolidation when many bins are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 10.0 + (open_bins_count as f64).min(20.0) * 0.5;
        // If an existing bin fits well, opening a new bin is costly.
        if post_residual == bin_capacity - item_size {
            score += 5.0;
        }
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // dead space relative to lookahead item
    }

    // Late-stream tightening: as stream progresses, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit_gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - next_fit_gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving large unusable slack
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter bins)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement would waste a lot
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if lookahead suggests a perfect two-item fill, allow opening
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize leaving a residual too small for the next item (dead space),
    // reward residuals that can still host the lookahead item.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * post_residual as f64;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to mean available space (poor fits everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (mean_residual.max(1.0));
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Penalize new bins by default; discount when open bins are tight.
        score += 25.0 - 20.0 * tightness.min(2.0) - 10.0 * (1.0 - progress);
        // Opening a bin when few are open is cheap; when many are open, wasteful.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild penalty for very small post-residuals that likely become dead space
    // unless the item was a near-perfect fit (handled above via fit_ratio).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference for bins with residual close to mean (keep bins balanced).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping.
    let mut score = pr + 12.0 * norm_pr * norm_pr + 30.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in the stream, penalize wasted space more.
    let prog_coupling = 1.0 + 2.0 * progress * progress;
    score *= prog_coupling;

    // Reward filling bins deeply: subtract a smooth function of item_size relative to capacity.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill;

    // Penalize bins whose residual deviates from mean residual (smooth coupling).
    score += 3.0 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 / (1.0 + gap * gap);
    }

    // Last-chance bin: strong smooth reward to use it.
    if fitting_bins_count == 1 {
        score -= 40.0 / (1.0 + norm_pr);
    }

    // Mild penalty for many open bins (encourage consolidation, smoothly scaled).
    score += open_bins_count as f64 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10
    let post_class = post_residual % 10;
    // Residuals that are "harmonically useful" (multiples of common item sizes 10,20,25,50)
    let harmonic_bonus = match post_residual {
        0 => 40.0,
        r if r % 50 == 0 => 25.0,
        r if r % 25 == 0 => 18.0,
        r if r % 20 == 0 => 14.0,
        r if r % 10 == 0 => 10.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Penalize dead space in awkward residue classes (1..9 fragments)
    if post_class > 0 && post_residual < 10 {
        score += 15.0 + (10 - post_class) as f64 * 2.0;
    }

    // Perfect fit coupling with lookahead: if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item leaves a residue whose class matters
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            }
            if next_post < 5 && next_post > 0 {
                score += 6.0;
            }
        } else {
            // next item cannot use this bin's residue: mild penalty for large waste
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // last item: strongly prefer zero waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: only fitting bin, avoid opening a new bin unless waste is big
    if fitting_bins_count == 1 && post_residual <= 20 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild bias so we only open when
    // existing bins would waste a lot
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.1;
        // open new bin early in stream when few bins exist
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Prefer tight bins among many fitting candidates (best-fit flavor)
    if fitting_bins_count > 1 {
        score += (bin_residual as f64) * 0.02;
    }

    // Progress-based mild pressure to consolidate late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold
    // typical items (<= 10 units) are effectively unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward" dead zone: residuals that few item sizes can fill.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Prefer bins whose residual was already small (compact bins first),
    // keeping large-residual bins flexible for later big items.
    score += (bin_residual as f64 - post_residual as f64) * 0.3;

    // Open-bin pressure: discourage spreading across many bins;
    // encourage using existing bins when several can fit.
    if fitting_bins_count > 1 {
        score -= 5.0;
    }
    if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        score -= 25.0;
    }

    // Pressure proportional to number of open bins: consolidating is good.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: when mean residual is high, prefer filling
    // loose bins rather than creating new ones.
    score += mean_residual * 0.2;

    // Lookahead (k=2): if the next item fits exactly in the post_residual,
    // this placement sets up a perfect follow-up -> reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize leaving a residual the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no existing bin offers a decent fit. Penalize the empty-bin call
    // progressively with how many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 20.0 + fitting_bins_count as f64 * 30.0;
        // But if stream is early, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            // next item can also fit here afterwards: strong bonus scaled by tightness
            let tightness = next / (post_residual as f64);
            score -= 300.0 * tightness;
        } else {
            // leftover dead space relative to next item: penalize unusable slivers
            let waste = next - post_residual as f64;
            if waste > 0.0 && post_residual > 0 {
                score += 80.0 * (waste / bin_capacity as f64);
            }
        }
        // exact match: next item fills bin perfectly
        if post_residual == next_item_size {
            score -= 500.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize new-bin candidate unless current open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 150.0;
        // open a new bin early in the stream if item is large (avoid fragmentation)
        if item_size > bin_capacity / 2 {
            score -= 120.0;
        }
    }

    // Progression: later in the stream, be more conservative (prefer tight fills)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose leftover becomes small.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - frac).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: reward if the next item fits exactly or well in the leftover.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize small unusable leftovers.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good open bins exist, but allow it
    // early in the stream or when mean residual is already high (fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
        if mean_residual > 30.0 {
            score -= (mean_residual - 30.0).min(25.0) * 0.3;
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual == bin_capacity {
            // new bin is empty; neutral
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Prefer bins whose residual deviates from mean (consolidate fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * dev;
    }

    // Mild penalty for spreading across many bins.
    score += 0.2 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Base: post residual (favor tight fits)
    let mut score = pr as f64;

    // Smooth polynomial coupling: mid-sized residuals get a quadratic penalty bump,
    // tiny residuals are rewarded (near-perfect fit), large residuals mildly penalized.
    let quad = x * x * (1.0 - x) * (1.0 - x); // peaks mid-range
    score += 18.0 * quad;

    // Stream progress coupling: later in stream, punish waste more strongly (quadratic in progress)
    score += 10.0 * progress * progress * x;

    // Lookahead: reward if next item fits into post residual (smooth falloff)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = (x - nx).max(0.0);
        score -= 12.0 * fit * (1.0 - fit);
        // exact fit for next item strongly rewarded
        if (x - nx).abs() < 0.01 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - x);
    }

    // Mean residual coupling: if this bin's residual deviates below mean (tighter than average), reward
    let mean_x = mean_residual / cap;
    score -= 6.0 * (mean_x - x).max(0.0);

    // Many open bins: mild penalty to prefer consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * x;

    // New-bin candidate: penalize unless item is large and current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_x * (open_bins_count as f64);
        let large_item = item_size as f64 / cap;
        score += 25.0 - 30.0 * large_item * (fragmentation / (fragmentation + 3.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10
    let r = post_residual % 10;
    // Residues near 0 (perfect fits) are excellent; penalize awkward residues
    let residue_penalty = match r {
        0 => -25.0,
        1 | 9 => -8.0,
        2 | 8 => -3.0,
        3 | 7 => 2.0,
        4 | 6 => 5.0,
        _ => 8.0,
    };
    score += residue_penalty;

    // Reward tight fits strongly (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // If next item can exactly fill this bin's post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let nr = (post_residual - next_item_size) % 10;
            if nr == 0 { score -= 20.0; } else if nr <= 3 { score -= 8.0; }
        } else {
            // next item won't fit here; small penalty if post_residual becomes dead space
            if post_residual < 10 {
                score -= 10.0; // tiny dead space is fine
            } else {
                score += 6.0;
            }
        }
    } else {
        // Last item: just minimize post residual
        score -= 15.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its full residual minus a bonus
        score = bin_capacity as f64 - 20.0;
        // If the item leaves a "harmonious" residual in a fresh bin, slightly better
        let rr = (bin_capacity - item_size) % 10;
        if rr == 0 { score -= 15.0; }
        // If many bins fit the item, discourage opening a new one
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below mean (consolidate waste)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild preference to spread load when many bins open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Integer-division threshold: bins with post_residual < item_size/2 are near-dead
    if post_residual < item_size / 2 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..=15)
    // are toxic — they will almost never be filled by future items.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 + (15 - post_residual) as f64 / 15.0);
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    } else if post_residual > 50 {
        // Large residual is healthy, keep it flexible.
        score -= 10.0;
    }

    // Dead space is worse when the bin is already deep in the stream
    // (few chances left to fill the gap).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward; if the
    // post-residual is just barely below the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins when few are open.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if the average residual is large, prefer bins
    // that consume more slack (tighter fits) to consolidate.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the dead space is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when every open bin would create unusable dead space.
    if bin_residual == bin_capacity {
        // Baseline mild penalty so tight fits in open bins win.
        score += 20.0;
        // But if the item is large relative to capacity and open bins are
        // fragmented, a new bin is attractive.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
