pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize creating dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fits snugly afterwards
        let next_post = post_residual as i64 - next_item_size as i64;
        score -= (next_post.max(0) as f64).min(10.0) * 0.4;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual unusable by next item: penalize proportionally
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // no good fit exists among open bins or item is large.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.6
            + (mean_residual / bin_capacity as f64) * 10.0;
        score += 30.0 + pressure;
        // Large items are hard to place later; opening fresh bin is ok
        if item_size > 60 {
            score -= 18.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference for filling bins with larger residuals first
    score -= (bin_residual as f64) * 0.05;

    // Global state: many open bins with slack -> encourage consolidation
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer minimal post-residual, with smooth non-linear shaping
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 40.0;

    // Non-linear coupling with stream progress: tighten packing more aggressively later
    let progress_gain = (t * t) * (1.0 - norm_pr) * 30.0;
    score -= progress_gain;

    // Perfect-fit reward (smooth bump around zero residual)
    score -= (1.0 - norm_pr).powi(6) * 50.0;

    // Penalize residuals that are too small to be useful (dead space) — smooth term
    let dead = (norm_pr * (cap / (item_size.max(1) as f64))).min(1.0);
    score += (1.0 - dead) * (1.0 - dead) * 10.0;

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= (1.0 - gap.min(1.0)) * 15.0 * (1.0 - t);
        score += gap * gap * 20.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 - t * 0.5);
    }

    // Mild penalty for proliferating bins vs mean residual state
    let mean_norm = mean_residual / cap;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - mean_norm).max(0.0);

    // Slight preference for fuller bins overall (smooth sigmoid on fill ratio)
    let fill = 1.0 - norm_pr;
    score -= (fill * fill * fill) * 12.0;

    // New-bin candidate shaping: make empty-bin score competitive only when fits are poor
    if bin_residual == bin_capacity {
        score = 55.0 + fit * 20.0 + t * 10.0;
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (mod classes) are far more reusable than odd remnants.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                bonus += 8.0;
            }
        }
        score -= bonus;

        // Small dead space classes (1..=9) are nearly unusable: penalize hard.
        if pr < 10 {
            score += 25.0;
        }
        // Sweet spot: residual in [10, 30] matches typical small items.
        if pr >= 10 && pr <= 30 {
            score -= 10.0;
        }
    } else {
        // Perfect fill: heavily reward.
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 && pr >= next_item_size {
        if pr == next_item_size {
            score -= 30.0;
        } else if (pr - next_item_size) < 10 {
            score += 5.0; // leaves tiny dead space after next item
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are poor fits
    // (high mean residual fragmentation) or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0; // base cost of opening a new bin
        score -= fragmentation * 0.5;
        score -= (open_bins_count as f64) * 2.0;
        // Late in the stream, prefer consolidating into existing bins.
        score += progress * 20.0;
        if fitting_bins_count <= 1 {
            score -= 35.0; // no good alternative -> new bin is fine
        }
    }

    // Mild preference for tighter existing bins as pressure grows.
    score += (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 15.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using existing bins over opening new ones (new-bin candidate has
    // bin_residual == bin_capacity, i.e. post_residual = capacity - item).
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid stranding capacity.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item almost fits (small gap), slight penalty for near-miss waste.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: mild penalty scaling with number of open bins to
    // encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            // partial lookahead match: reward proportional to how much of the
            // residual the next item consumes (leaves less dead space later).
            let consumed = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * consumed * consumed;
        } else {
            // next item cannot fit here: penalize large leftover that likely
            // becomes dead space relative to mean residual.
            let dead = (post_residual as f64 - mean_residual).max(0.0);
            score += 0.5 * dead;
        }
    }

    // Compare post_residual against mean residual: creating an atypical
    // (too small) residual is bad for future flexibility.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge and
    // nothing else fits well (poor fit into any open bin).
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else {
            ((item_size as f64) / (bin_residual as f64)).min(1.0)
        };
        // Opening a new bin only wins when the item is very large relative to
        // residual space and few bins can fit it.
        let pressure = if item_size > 70 { 1.0 } else { 0.0 };
        score = 150.0 - 100.0 * poor_fit * pressure - 10.0 * (fitting_bins_count == 0) as i32 as f64;
        // late in the stream, mildly discourage opening extra bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight preference to fill bins that are already mostly full.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    let tight = 1.0 - post_residual as f64 / bin_capacity as f64;

    // Reward tight fits (subtract), stronger as stream progresses
    score -= 40.0 * tight * tight * (0.5 + t);

    // Penalize small dead space that nothing can use later:
    // dead space is "wasted" if post_residual is tiny but nonzero
    if post_residual > 0 && post_residual < 12 {
        score += 25.0 * (12.0 - post_residual as f64) / 12.0;
    }
    // Perfect closure bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to prefer the best-fit among many
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward heavily; if next item cannot fit, penalize wasted residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // next item fits but leaves more fragmentation if residual barely fits
            let slack = post_residual - next_item_size;
            score += 0.3 * slack as f64 * (1.0 - t);
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins rather than opening new ones
    let crowded = (open_bins_count as f64).ln1p();
    score += crowded * (mean_residual / bin_capacity as f64) * 5.0;

    // New-bin candidate handling: empty bin should only win when it's
    // genuinely better (no open bin fits well). Penalize it by default.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - t);
        // but early in the stream, or when many bins are open and residual
        // of this item would be large, allow exploration
        if post_residual as f64 > mean_residual {
            score -= 12.0 * t;
        }
    }

    // Mild preference for bins whose residual is close to the item
    let mismatch = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * mismatch;

    // Time horizon: late in stream, be conservative, minimize spread
    score += t * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    let mut score = post + 40.0 * post_norm * post_norm;

    // Smooth interaction: as the stream progresses, tighten the fit requirement
    score += 30.0 * post_norm * post_norm * (0.5 + progress);

    // Reward bins whose residual closely matches the item (tight fit coupling)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize wasting a nearly-full bin on a small item (non-linear coupling)
    let waste = (bin_residual - item_size) as f64 / cap;
    score += 20.0 * waste * waste * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - post_norm);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward
    if next_item_size > 0 && next_item_size <= post_residual as u32 {
        let next_fit = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - next_fit * next_fit);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0 * post_norm;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // increasingly acceptable late in the stream or when mean residual is large
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 45.0 * (1.0 - progress) + 20.0 * (1.0 - mean_norm) * (1.0 - progress);
        score -= 10.0 * progress * progress;
    }

    // Slight preference for consolidating among many open bins
    score += 2.0 * (open_bins_count as f64).ln() * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: harmonic class 0 (post_residual divisible into clean classes)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual space: classify post_residual into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in "dead zones" (too small to hold common items 10..80)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // unusable sliver
    }

    // Integer-division threshold: how many standard items (>=10) could still fit
    let slots = post_residual / 10;
    score -= 15.0 * slots as f64;

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0; // chain placement possible
            // harmonic match: next item exactly fills post residual class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 40.0;
            }
        } else {
            score += 25.0; // next item won't fit here; residual likely wasted
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 300.0;
    }

    // Last-chance bin: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate logic: only open a new bin when current bins are fragmented
    if bin_residual == bin_capacity {
        // compare against mean fragmentation of open bins
        let tight_fit_exists = (bin_capacity as f64 - mean_residual) >= item_size as f64;
        if open_bins_count > 0 && tight_fit_exists {
            score += 350.0; // keep using existing bins when reasonably tight fits exist
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // must open a new bin
        }
        // early stream: bias toward opening bins to build flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // penalize opening new bin when many bins already open with slack
        score += 10.0 * open_bins_count as f64;
        // harmonic penalty: opening a bin whose residual class is awkward
        let r = item_size % 10;
        if r != 0 {
            score += 20.0 * r as f64; // non-multiple-of-10 items create awkward classes
        }
    } else {
        // prefer bins whose residual class matches item's harmonic class
        let item_class = item_size / 20; // coarse class: 0..4
        let bin_class = bin_residual / 20;
        if item_class == bin_class {
            score -= 30.0;
        }
    }

    // mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // modulo arithmetic on post_residual: reward residuals near capacity fractions
    let quarter = bin_capacity / 4;
    for k in 1..4 {
        let t = quarter * k;
        if post_residual.abs_diff(t) <= 2 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..=10) are almost certainly wasted; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward bins whose residual can still host the lookahead item after this
    // placement (chained fits), penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when the count is large.
    score += 4.0 * open_bins_count as f64;

    // Slight bonus when this bin's residual is below the mean (denser bin).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when nothing fits reasonably,
    // i.e., when it provides a large, reusable residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // Cheapen it if the current item is large and would leave existing
        // bins with dead space anyway.
        if item_size >= 70 {
            score -= 40.0;
        }
        // Late in the stream, prefer closing out open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when the NEXT item exactly fills the residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 60.0; // perfect chain: this bin becomes exactly usable next step
        } else {
            score += gap as f64 * 0.8; // penalize mismatch proportional to gap
        }
        // Bonus if next item fits with room to spare but small waste
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0; // next item can't use this residual -> dead space risk
        }
    } else {
        // Last item: only current fit matters
        score -= 5.0;
    }

    // Tight fit reward: small post_residual is good, but not zero-waste-obsessed
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 20.0;

    // Relative to mean residual: prefer bins with residual close to (or below) mean
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with smaller residual overall (best-fit flavor) when many bins fit
    if fitting_bins_count > 3 {
        score += 0.15 * post_residual as f64;
    }

    // New-bin candidate: open a new bin only if item is large and no good tight fit exists
    if bin_residual == bin_capacity {
        if item_size > 60 {
            score -= 12.0; // large items: fresh bin is fine
        } else {
            score += 18.0; // small items: prefer packing into existing bins
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that can't fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly for the lookahead item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (-gap / 20.0).exp();
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins have slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress) + 0.6 * mean_residual;
        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
    }

    // Mild preference for bins whose residual is below average (fill emptier bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Reward using bins that would otherwise be wasted (small residual hard to fill).
    if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 9.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Tightness of fit: fraction of the bin consumed by this item
    let fill = item_size as f64 / cap;
    let tight_fit = 1.0 - (post_residual as f64 / cap); // high when item nearly fills bin

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    // (later in stream, closing bins cleanly matters more)
    let progress_coupling = progress * (1.0 + progress * (1.0 - progress) * 4.0);
    score -= 12.0 * tight_fit * tight_fit * (1.0 + 1.5 * progress_coupling);

    // Penalize dead space non-linearly: small post_residual is fine, large is bad,
    // and worse late in the stream
    let waste_frac = post_residual as f64 / cap;
    score += 8.0 * waste_frac * waste_frac * (0.5 + progress);

    // Lookahead: bonus if the next item fits the resulting residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_score = (-gap / (cap * 0.25)).exp();
        score -= 10.0 * match_score * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure to prefer fuller bins when many bins are open
    score -= (bin_residual as f64 - mean_residual).abs().min(20.0) * 0.05 * (open_bins_count as f64).sqrt().min(3.0);

    // New-bin candidate handling: penalize opening a fresh bin, but relax the penalty
    // when it would leave lots of usable space for future items early in the stream
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        score += 18.0 * (1.0 - 0.6 * openness * (1.0 - fill));
        // If no open bin fits well, opening a new bin becomes relatively attractive
        if post_residual as f64 / cap > 0.5 {
            score -= 10.0 * openness;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common divisors (2,4,5,10)
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // Dead-space penalty grows when residual falls into "awkward" harmonic classes
        let class = r % 10;
        let awkward = match class {
            1 | 2 | 3 | 6 | 7 | 8 | 9 => 1.0,
            _ => 0.0,
        };
        score += awkward * 8.0;

        // Fractional-capacity classes: residual near simple fractions of capacity
        let c = bin_capacity as f64;
        let rf = r as f64;
        let frac_targets = [c / 2.0, c / 4.0, c / 3.0, c / 5.0, c / 10.0];
        let mut near_frac = f64::INFINITY;
        for t in &frac_targets {
            let d = (rf - t).abs();
            if d < near_frac { near_frac = d; }
        }
        score += near_frac * 0.4;

        // Integer-division threshold: small residuals (< 10) are nearly dead
        if r < 10 {
            score += (10 - r) as f64 * 3.0;
        }

        // If next item can exactly fill this residual, strongly favor
        if next_item_size > 0 && next_item_size == r {
            score -= 80.0;
        } else if next_item_size > 0 && next_item_size <= r {
            // harmonic match: next item leaves a residue in a "good" class (multiple of 10)
            let nxt_post = r - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 15.0;
            }
            if next_item_size + r > bin_capacity {
                score += 0.0;
            }
        } else if next_item_size > r {
            // next item won't fit here; residual likely wasted
            score += (next_item_size - r) as f64 * 0.3;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 12.0;
        // but if no good fit exists (mean residual high), opening fresh is fine
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild trend term: later in stream, prefer tighter packing
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * t;

    // Prefer bins already below mean residual (more roomy bins absorb big items later)
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it cannot hold even a mid-sized item (threshold ~10)
    // or cannot hold the lookahead item.
    if post_residual > 0 {
        let dead_threshold = 9u32;
        if post_residual <= dead_threshold {
            score += 40.0 * (dead_threshold as f64 - post_residual as f64 + 1.0);
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Gap unusable for the known next item: partial dead-space penalty.
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Usable residual: mild reward proportional to remaining space.
            score -= 0.2 * post_residual as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements into already-crowded bin pools,
    // but reward using last-chance bins (fitting_bins_count == 1).
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Neutral baseline: prefer it over dead-space-creating fits,
        // but lose to tight fits in open bins.
        score = 15.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= 50 {
            // Large item starting a fresh bin is fine.
            score -= 5.0;
        }
    }

    // Progression coupling: early in the stream, allow slightly more
    // aggressive bin opening to build good residual structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // Mean residual coupling: if open bins are already loose on average,
    // discourage adding more slack.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base preference: tighter packing (small post_residual).
    score += (post_residual as f64).powi(2) * 0.004;

    // 2-step lookahead: reward post_residual that closely matches next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let match_gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - match_gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally.
        score += 4.0 + 0.05 * (next_item_size - post_residual) as f64;
    }

    // Relative-to-mean coupling: bins with more residual than average are
    // better targets for the current item (preserve tight bins).
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
        // Especially when the bin is nearly exhausted.
        if post_residual <= 10 {
            score -= 15.0;
        }
    }

    // Late in the stream, avoid opening new bins; early, prefer fresh bins for big items.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost + discourage when many open bins exist late.
        score = 45.0 + open_bins_count as f64 * (2.0 + 4.0 * progress);
        if next_item_size > 0 && next_item_size >= bin_capacity as f64 * 0.5 {
            score -= 10.0; // big upcoming item benefits from fresh capacity
        }
    }

    // Discourage leaving tiny unusable slivers unless perfectly matched.
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: if the next item cannot fit in the post-residual, this bin
    // would be "closed" anyway -> placing here is cheap; reward it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score -= 6.0 + 0.05 * (next_item_size as f64);
        } else {
            // Residual still useful for the next item: slight penalty to keep
            // space for it if this bin is a marginal fit.
            let slack = (post_residual - next_item_size) as f64;
            score += 0.02 * slack;
        }
    } else {
        // Last item: dump into any bin with enough room; prefer fullest.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin opening more when many bins are already open and
    // their mean residual is large (wasted capacity accumulating).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress + 0.1 * mean_residual;
        // Opening a new bin is acceptable if no tight option exists:
        // reduce penalty slightly as mean residual shrinks.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    } else {
        // Mild reward for consolidating into open bins when they are crowded.
        score -= 0.02 * open_bins_count as f64;
    }

    // Time-horizon coupling: late in the stream, favor closing bins out
    // (small residuals) to avoid stranding capacity.
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let poly = fit_norm * fit_norm * (1.0 - p) + fit_norm * p * p;
    score += 8.0 * poly;
    // Reward tight fits, stronger as stream progresses
    score -= (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 + 2.0 * p) * 6.0;
    // Penalize post residual that can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 10.0 * (nxt - pr) / cap * (1.0 + p);
        } else {
            score -= 3.0 * (1.0 - (pr - nxt) / cap) * p;
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }
    // Prefer using existing bins over opening new ones, more so early on
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - p);
    }
    // Mild mean-residual coupling
    score += 0.05 * (mean_residual - pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    // into "usable" classes. Residuals divisible into large chunks are valuable.
    let harmonic_class = post_residual / 10; // 0..10 class index
    let class_value: [f64; 11] = [
        0.0,  8.0,  6.0,  5.0,  4.5,  4.0,
        3.5,  3.0,  2.0,  1.0, -20.0, // near-full residual (post==100 impossible, but high class = full bin = great)
    ];
    // Reward (subtract) when post_residual falls in a high harmonic class
    score -= class_value[(harmonic_class as usize).min(10)] * 1.5;

    // Modulo arithmetic: post_residual divisible by common item sizes is reusable
    for m in [10u32, 20, 25, 50].iter() {
        if post_residual > 0 && post_residual % m == 0 {
            score -= 6.0;
        }
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space: post_residual too small for typical next item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use the leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, keep it usable
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in stream with many open bins, closing them out is better
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
        score += open_bins_count as f64 * 0.5;
    } else {
        // Favor tighter bins (small pre-residual) mildly
        score += (bin_residual as f64) * 0.05;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing)
    score += (mean_residual - bin_residual as f64).abs() * 0.1;
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Harmonic threshold on item_size classes (integer division)
    let item_class = item_size / 20; // 0..4
    score -= match item_class {
        0 => 2.0,       // tiny item: flexible, place anywhere cheap
        1 => 0.0,
        2 => -2.0,      // large item: reward placing it (subtract more)
        _ => -4.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fit
    } else if post_residual < 10 {
        score += 200.0; // dead space: nothing can ever use this gap
    } else if post_residual < 25 {
        score += 40.0; // likely dead space
    } else {
        // Larger residuals are mildly penalized proportional to waste,
        // but reward if the next item can fit into the leftover.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        score += (post_residual as f64) * 0.5;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 50.0;

    // Open-bin pressure: discourage scattering across many bins when
    // mean residual is already high; encourage consolidating into bins
    // with low residual.
    let pressure = (open_bins_count as f64).ln() * 5.0;
    score += pressure * (1.0 - fit_ratio).max(0.0);

    if (bin_residual as f64) < mean_residual {
        score -= 15.0; // prefer fuller bins
    } else {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it attractive only when the item is large
    // or all existing fits are poor.
    if bin_residual == bin_capacity {
        let base = 80.0 + (item_size as f64) * 0.3;
        score += base;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: must open a new bin
        } else if item_size >= 60 {
            score -= 60.0; // large items justify fresh bins
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 50.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 20.0; // leftover too small for lookahead item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if the NEXT item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 45.0 * next_fit * next_fit;
        // Perfect 2-chain: post_residual exactly matches next item
        if next_item_size == post_residual {
            score -= 80.0;
        }
    } else if next_item_size > 0 {
        // Penalize post_residual that can't host the next item (likely dead space),
        // scaled by how close it came (small unusable gaps are worst).
        let waste = post_residual as f64;
        score += 0.5 * waste;
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0; // tiny dead gap penalty
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving a residual near the mean is neutral; far below mean (very tight) is good.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // or current bins are all poor fits.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its residual is maximal, so discourage by default.
        score += 40.0;
        // But if item is big relative to capacity, a fresh bin is reasonable.
        score -= 0.4 * item_size as f64;
        // If many bins already open and mean residual is high, prefer packing into them.
        score += 0.15 * mean_residual;
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference to fill more-opened bins first (keeps bin count stable).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < item_size {
        score += 12.0; // nearly unusable sliver
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0; // can't fit the lookahead item either
    }

    // Reward exact or near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if this placement leaves room exactly for the next item, favor it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin mildly,
    // unless the item fits badly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0;
        // If the item is large relative to capacity, opening a fresh bin is fine.
        if (item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
        // Many open bins with large mean residual: avoid adding another.
        if mean_residual > (item_size as f64) && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Favor bins with residual close to item (best-fit style) via coupling with mean.
    let dev = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * dev;

    // Slight preference for using bins with below-average residual (balance avoidance of fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual (0..1)
    let pr = post_residual as f64 / bin_capacity as f64;
    let ir = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: penalize large post_residual quadratically,
    // scaled by stream progress (later in stream => tighter packing desired).
    let progress_sq = progress * progress;
    score += 40.0 * pr * pr * (0.5 + progress_sq);

    // Reward near-full fits with a smooth saturating term
    score -= 25.0 * (1.0 - pr) * (1.0 - pr) * ir;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins far from mean residual (prefer balanced residuals)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 8.0 * dev * dev;

    // Lookahead coupling: if next item fits in the post-residual, reward; otherwise penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            let slack = (post_residual as f64 - nx) / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nx - post_residual as f64) / bin_capacity as f64;
            score += 12.0 * gap * gap;
        }
    }

    // Mild penalty for many open bins, smoothed by progress
    score += 0.5 * open_bins_count as f64 * (0.3 + progress);

    // New-bin candidate handling: only attractive early or when residual would be wasted
    if bin_residual == bin_capacity {
        let waste = 20.0 * pr * pr * (1.0 - progress);
        score = 35.0 + progress * 30.0 + waste - (1.0 - ir) * 10.0;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when a unique fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "usable bands" via integer division on quarter-capacity buckets.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..4 harmonic band
    let next_class = if next_item_size > 0 { next_item_size / quarter } else { 0 };

    // Reward when the leftover band matches the next item's band exactly
    // (perfect harmonic coupling: leftover can host the next item).
    if next_item_size > 0 && next_item_size <= post_residual {
        let band_match = if post_class == next_class { 12.0 } else { 6.0 };
        score -= band_match;
        // Extra reward if next item fits snugly (residual - next small)
        let snug = (post_residual - next_item_size) as f64;
        score -= (quarter as f64 - snug).max(0.0) * 0.08;
    } else if next_item_size > 0 {
        // Penalize leftover that the next item cannot use at all
        score += 4.0;
    }

    // Dead-space penalty: tiny leftover (worst harmonic class 0) is waste
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Modulo-arithmetic class on post_residual mod (capacity/8): residues
    // near 0 mod small units are more likely reusable by typical items.
    let unit = bin_capacity / 8;
    let m = post_residual % unit;
    score -= (unit as f64 / 2.0 - m as f64).abs() * 0.05;

    // Last-chance bin: strongly prefer using it rather than opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins
    // would leave badly fragmented (high harmonic class) leftovers.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let fragmentation = (mean_residual / bin_capacity as f64).powi(2);
        score += 8.0 * pressure - 30.0 * fragmentation;
        if fitting_bins_count <= 1 {
            score -= 10.0; // nothing else fits well -> open new bin
        }
    }

    // Late-stream conservatism: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * tightness * (item_size as f64);

    // Reward bins whose residual closely matches the item (near-exact fill).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 15.0 / (1.0 + gap);

    // Open-bin pressure: discourage spreading across many open bins.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the resulting residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 8.0; // next item would create dead space here
    }

    // Mild penalty when this bin's residual is far below mean (already fragmented).
    if (bin_residual as f64) < mean_residual - 15.0 {
        score += 5.0;
    }

    // Early in the stream, be more willing to open fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits in the post residual (chainable placement).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Next item cannot use the residual: penalize proportionally to wasted slack.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    let bin_res_f = bin_residual as f64;
    score += 0.5 * (bin_res_f - mean_residual);

    // Penalize large dead space quadratically.
    score += 0.02 * (post_residual as f64).powi(2) / 10.0;

    // Slight preference for reusing existing bins over opening new ones
    // as stream progresses (bin consolidation late in the stream).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    // If this bin exactly fits the item (residual becomes 0), huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fits: reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 300.0;
        } else {
            score -= 50.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // Penalize leaving a residual that the next item cannot use (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // is a good home (i.e., this call IS the empty bin and fits are loose).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 120.0;
        // Scale with how many bins already fit the item: more alternatives = worse.
        score += 30.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
        // If open bins have large mean residual, prefer reusing them.
        score += mean_residual * 0.5;
        // If the item is large relative to capacity, opening a fresh bin is fine.
        score -= 0.3 * item_size as f64;
    }

    // Prefer bins with residual close to the item (best-fit coupling).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.2;

    // Slight preference for bins below mean residual (consolidate emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Many open bins: encourage consolidation to avoid bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: waste penalty, mildly convex in post residual
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate slack; later, penalize large residuals more strongly
    let progress_coupling = (progress * std::f64::consts::PI).sin();
    score += 12.0 * x * x * (1.0 - progress_coupling);

    // Reward near-perfect fits, stronger as stream progresses
    let tightness = 1.0 - x;
    score -= 8.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * tightness;
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - diff / cap).max(0.0);
        // penalize leaving residual that barely fails to fit next item
        if next_item_size as f64 > pr {
            score += 3.0 * (1.0 - (next_item_size as f64 - pr) / cap);
        }
    }

    // Mild penalty for spreading across too many bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: make it slightly unattractive unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 4.0 - 3.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes of post_residual: reward near-zero waste classes.
    // Class A: perfect fit (post == 0) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    } else {
        // Integer-division thresholds on post_residual: usable vs dead space.
        let quot = post_residual / 20; // classes 0..5 (0-19,20-39,...)
        score -= quot as f64 * 2.0;
        // Dead space penalty grows quadratically for unusable remainder.
        let rem = (post_residual % 20) as f64;
        score += rem * rem / 20.0;
    }

    // Coupling with next item: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize leaving large stranded residual.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening unless current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = if post_residual == 0 { 1.0 } else { post / cap };
        // If an existing bin fits well, discourage new bin.
        score += 20.0 + fit_quality * 30.0;
        if fitting_bins_count <= 1 {
            // only this (new) bin fits -> opening is fine
            score -= 55.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0;

    // Slight reward for filling fuller bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - post / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly unusable
    // for future items (sizes 1..100), so penalize them super-linearly.
    if post_residual > 0 {
        if post_residual < 10 {
