    // scaled by how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 25.0 + tightness * 15.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // Extra push when the leftover gap stays usable (>= next item size).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Dead space that cannot host the lookahead item is even worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += next_item_size as f64 * 0.8;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, slightly relaxed when few bins
        // are open, penalized when many bins are open (consolidate instead).
        score = 40.0 + pressure * 3.0 - mean_residual * 0.2;
        // If no existing bin can host the lookahead either, opening fresh
        // is more attractive.
        if next_item_size > 0 && fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // Existing bins get a mild bonus that grows with open-bin pressure.
        score -= pressure * 0.6;
    }

    // Alignment with mean residual: bins deviating strongly from the mean
    // residual are less predictable; prefer bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item exactly fills the remaining space, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it packs the remainder.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 30.0;
        } else {
            // Next item won't fit here: penalize leaving a residual that is too small
            // to be useful (dead space relative to the minimum item size).
            if post_residual < 10 {
                score += 60.0;
            } else if next_item_size > post_residual {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Compare residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 25.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 15.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin when existing bins fit well, unless residual is tiny.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus mild penalty so only opened when
        // all open bins are poor fits (their lookahead/fit bonuses outweigh this).
        score += 70.0;
        // Late in the stream, be slightly more willing to keep bins tight.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty for fragmenting many bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual) but penalize useless slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead space too small for any item (min size 1..100, small slivers rarely useful)
    }

    // Tightness ratio: reward high fill fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Lookahead: if the next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving large gaps that waste capacity
            score += 0.05 * post_residual as f64;
        }
    } else {
        // Last item: prefer fullest packing possible.
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large/fragmented and the item fits poorly anywhere.
    if bin_residual == bin_capacity {
        // A fresh bin has perfect flexibility; make it competitive when the
        // current bin would leave a big gap or when bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 35.0 + 0.3 * post_residual as f64;
        if fit_ratio > 0.8 {
            score += 20.0; // item fits current bin very well -> discourage new bin
        }
        if fragmentation < 10.0 && post_residual <= 20 {
            score += 25.0; // current bin packs well -> keep it
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Mild bonus for using existing bins as they accumulate.
        score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Global state coupling: when mean residual is high, encourage consolidating
    // into fuller bins (lower post_residual relative to mean).
    score += 0.08 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 8.0 * coupling;

    // Penalize tight-but-wasted residuals more as stream advances
    score += 4.0 * (1.0 - progress) * (norm_pr - (norm_pr * norm_pr));

    // Reward near-perfect fits with a saturating term
    let fit_quality = 1.0 - (pr / cap);
    score -= 6.0 * fit_quality * fit_quality * (0.5 + 0.5 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Lookahead: penalize leaving residual that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 3.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap) * progress;
        }
    }

    // Mean residual alignment: prefer bins close to the fleet mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * (1.0 - progress);

    // New-bin candidate: mildly penalize opening fresh bins early, allow later
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Harmonic class of the leftover: leftovers that are "reusable"
        // (divisible into common small item sizes) are less penalized.
        let pr = post_residual;
        let mut reusability = 0.0;
        if pr % 10 == 0 { reusability += 3.0; }
        if pr % 25 == 0 { reusability += 2.0; }
        if pr % 20 == 0 { reusability += 1.5; }
        if pr >= 10 && pr <= 30 { reusability += 2.0; }
        score -= reusability;

        // Dead-space penalty for tiny unusable leftovers.
        if pr < 10 {
            score += 12.0;
        }
    }

    // Fractional fill of the bin: reward high utilization.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill * fill;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - next_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty proportional to overshoot.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline cost that
    // scales with how many bins are already open and stream progress.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64
            + 6.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // Still allow opening a new bin if the fit would be terrible elsewhere.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Mild tie-breaker toward bins below mean residual (balance workload).
    if bin_residual as f64 > mean_residual {
        score += 1.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1..100 stream => assume ~10 as typical floor)
    // are "dead" and should be heavily penalized unless exactly 0.
    let min_useful = 10u32;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else if post_residual < min_useful {
        // Unusable sliver: penalize hard, scaled by how much capacity wasted.
        score += 300.0 + 3.0 * (min_useful - post_residual) as f64;
    } else {
        // Usable leftover: mild reward proportional to tightness.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward bins that can also accommodate the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here: penalize slightly more.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, new-bin opening is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += 0.05 * pressure;

    // Compare against mean residual: bins tighter than average are attractive.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it unattractive unless current fit is awful.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if the item is huge and few bins fit it, allow new bin.
        if item_size > bin_capacity / 2 {
            score -= 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // 2-step lookahead: reward if the next item fits into post_residual,
    // extra reward for a near-exact match (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.35 * slack;
        if slack == 0.0 {
            score -= 15.0; // perfect 2-item chain fill
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving dead space.
        score += 0.25 * post_residual as f64;
        // If next item is small, dead space is more forgivable.
        if next_item_size <= post_residual + 10 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins with less residual than average
    // are "dirtier" — prefer filling them to consolidate waste.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.30 * diff;
    } else {
        // New-bin candidate: penalize mildly so it only wins when
        // no open bin offers a decent fit or a lookahead chain.
        score += 6.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 3.0;
        }
        // Early in stream, opening bins is cheaper; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for bins that are relatively full already.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill;

    // Many open bins: consolidate harder.
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that leave little dead space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item can still fit in the remaining space,
    // this placement keeps the bin useful — reward it proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.3 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item is more costly.
        let gap = next_item_size as f64 - post_residual as f64;
        score += 0.15 * gap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * fit_ratio * (bin_capacity as f64);
    }

    // New-bin candidate handling: opening a bin should only win when the current
    // fit is poor or the fleet is heavily loaded already.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more when mean residual is high (existing space is usable).
        score += 30.0 + 0.4 * mean_residual + 20.0 * (1.0 - progress);
        // But if item is large and mean residual is small, new bin is attractive.
        score -= 0.2 * item_size as f64 * (mean_residual / bin_capacity as f64);
        // Opening a new bin when many bins are already open is mildly discouraged.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer placing into bins with below-average residual (consolidate waste).
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.1 * diff;
    }

    // Late in the stream, prefer filling bins as tightly as possible to avoid
    // scattering residual capacity across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus as post_residual approaches zero.
    let pr = post_residual as f64;
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer leaving flexible space; late, prefer near-perfect packing.
    let coupling = (pr / 100.0) * (1.0 - progress) * (1.0 - progress);
    score += 30.0 * coupling;

    // Perfect-fill bonus: strongly favor bins whose residual exactly matches.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 15.0 * (1.0 + progress);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // penalize leaving residual too small for the next item
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are open with usable residual.
    if bin_residual == bin_capacity {
        let waste_penalty = (mean_residual / bin_capacity as f64) * (1.0 - progress);
        score += 25.0 + 20.0 * waste_penalty + 3.0 * open_bins_count as f64 * (1.0 - progress);
        // but allow opening if residual is tiny and item large
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Penalize bins whose residual is far from mean (outliers) mildly.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class residuals into buckets of 10 (capacity fractions): 0-9 (prime),
    // 10-19 (usable for smallest items), 20-39, 40+ (half-bin+ waste).
    let class = post_residual / 10;
    let frac = post_residual % 10;
    match class {
        0 => { score -= 12.0 - frac as f64; }        // near-perfect fit: strongly reward
        1 => { score -= 4.0 + frac as f64 * 0.3; }   // still fits a min item
        2 => { score += 2.0 + frac as f64 * 0.2; }   // mildly wasteful
        3 => { score += 6.0 + frac as f64 * 0.25; }
        _ => { score += 10.0 + frac as f64 * 0.4; }  // >= half bin wasted: heavy penalty
    }

    // Parity/oddness of residual: odd residuals can never be exactly filled
    // by even items — small extra penalty in low classes.
    if post_residual % 2 == 1 && post_residual < 20 {
        score += 1.5;
    }

    // --- Lookahead coupling: reward residuals that fit the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic threshold: exact fill or close fill of next item is gold.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 15.0;
            } else if gap < 10 {
                score -= 8.0 - gap as f64 * 0.5;
            } else {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; residual likely becomes dead space.
            score += post_residual as f64 * 0.15;
        }
    }

    // --- Last-chance bonus: only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are all tight
        // (mean residual small) or nothing useful can be made of them.
        let tightness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // New bin baseline score: high when open bins have usable space.
        score = 60.0 + 60.0 * (1.0 - tightness) + open_bins_count as f64 * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable gaps (below the minimum item size 1..10 range)
    // are worthless; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Moderate residual (10..=20) is partially reusable but risky: mild penalty
    // unless the lookahead item can use it.
    if post_residual >= 10 && post_residual <= 20 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // lookahead fits into the gap: reward
        } else {
            score += 8.0;
        }
    }

    // Tight fit reward: fraction of bin consumed.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 40.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one
    // and encourage consolidating into existing bins.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, minus lookahead escape.
        score += 30.0 + pressure * 2.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item may pair with a fresh bin
        }
    } else {
        score -= pressure.min(10.0) * 1.5;
    }

    // Prefer bins whose residual is close to the mean (keep residuals uniform),
    // which preserves flexibility for future items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Early in the stream, be more willing to open bins (keep options open);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 20.0;
    } else {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when leftover exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // leftover usable by next item: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += 40.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins with residuals near mean (balanced),
    // but prefer tighter-than-mean bins for large items.
    let res_f = post_residual as f64;
    let dev = res_f - mean_residual;
    score += 0.5 * dev.abs();
    score -= 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 5.0 * open_bins_count as f64;
    }

    // Early stream: slightly prefer keeping residuals flexible (large post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * res_f * 0.1;
    score += progress * res_f * 0.1;

    // New-bin candidate: penalize opening a new bin unless current bins fit badly.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0; // fresh bin still useful for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post_residual is small.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that cannot be used by the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // residual unusable by next item: penalty proportional to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        } else if post_residual == next_item_size {
            // perfect lookahead fit: big reward
            score -= 25.0;
        } else {
            // next item fits with room left: mild reward
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // crowding: slight penalty to spread selection pressure
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Time horizon: later in the stream, prefer filling existing bins
    // more aggressively; early on, allow more exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tight;

    // Global state coupling: many open bins -> discourage opening more;
    // penalize the new-bin candidate (bin_residual == bin_capacity) when
    // open bins are plentiful and this is not a tight placement.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item justifies a fresh bin
        }
    }

    // Mean residual coupling: if this bin's residual deviates favorably
    // from the mean (smaller), reward it; if much larger, penalize.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Prefer bins whose post_residual is a "usable" size bucket
    // (residuals near common item sizes are less wasteful).
    if post_residual >= 10 && post_residual <= 80 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = r
        - 12.0 * (1.0 - rn) * (1.0 - rn) * r
        + 6.0 * rn * rn * r * progress;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - rn;
    score -= 20.0 * tightness * tightness * tightness * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening new bins mildly, more when good fits exist
    if bin_residual == bin_capacity {
        let spread = (mean_residual - r).abs();
        score += 25.0 + 15.0 * (1.0 - progress) - 5.0 * spread / cap;
        // If next item is large, a fresh bin is more attractive
        score -= (next_item_size as f64) * 0.15;
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing)
        score += 0.08 * (r - mean_residual).abs();
    }

    // Lookahead: penalize leaving residual that barely fails next item
    if next_item_size > 0 {
        let gap = r - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score += 8.0 * (1.0 - gap / 10.0);
        }
        // Reward residuals that exactly accommodate next item
        if (gap as i64) == 0 {
            score -= 15.0;
        }
    }

    // Slight penalty for proliferating open bins
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits (small post_residual) non-linearly.
    score -= 20.0 * (-post_residual as f64 / 15.0).exp();

    // Harmonic class: exact-fill and divisible residuals are golden.
    if post_residual == 0 {
        score -= 50.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0; // residual in standard granularity is reusable
    }

    // Lookahead coupling: if the next item exactly consumes the residual,
    // this bin is a perfect two-step match.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            score -= 12.0 * (-nxt_left as f64 / 12.0).exp();
            if nxt_left % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot use the leftover; penalize by overflow amount
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: when many bins are open, prefer consolidation (lower mean
    // residual bins absorb items to reduce bin count).
    if open_bins_count > 3 {
        let tightness = (mean_residual - post_residual as f64) / cap;
        score -= 8.0 * tightness.clamp(-1.0, 1.0);
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large relative to capacity (would leave open bins badly
    // fragmented) or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // base penalty for opening a new bin
        score += 30.0;
        // large items waste less in a fresh bin; ease penalty
        score -= 25.0 * frac * frac;
        // early in the stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // if next item is huge and won't fit leftovers anyway, new bin helps
        if next_item_size > 0 && next_item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Mild penalty for very large dead space (unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10) can
    // practically use are heavily penalized. A gap of 1..=9 is "dead" unless a
    // tiny item arrives later; treat small gaps as wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    }

    // Tight-fit reward: fraction of residual consumed.
    let fill_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    score -= 25.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or open-bin residuals are bloated.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let bloat = mean_residual / bin_capacity as f64;
        // Base cost of a fresh bin, discounted by stream pressure and bloat.
        let mut new_bin_score = 85.0 - 20.0 * progress + 30.0 * bloat;
        // Large items waste less in a fresh bin.
        new_bin_score -= 0.4 * item_size as f64;
        // Lookahead: if next item pairs well with the leftover (post_residual),
        // a fresh bin is more attractive.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                new_bin_score -= 15.0;
            } else {
                new_bin_score += 10.0;
            }
        }
        // If this bin is a last chance elsewhere, discourage opening a new one.
        if fitting_bins_count >= 1 {
            new_bin_score += 25.0;
        }
        score = score.min(new_bin_score + 200.0); // keep ordering sane
        score = new_bin_score;
    } else {
        // Open-bin count pressure: mildly discourage spreading across many bins.
        score += 1.5 * open_bins_count as f64;
        // Lookahead coupling: if leftover after placement can host the next item,
        // this placement is chain-friendly; reward it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect chain: leftover exactly matches next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: leftover nonzero but too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Exact fit bonus (bin fully consumed).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer tight fits relative to the mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin unless it is truly necessary:
    // new-bin candidate gets a penalty that shrinks as the stream progresses
    // and when existing bins are too fragmented (high mean residual waste).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_penalty = 55.0 - 15.0 * progress;
        if next_item_size > 0 && post_residual == next_item_size {
            new_penalty -= 70.0; // fresh bin perfectly chains with next item
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            new_penalty -= 20.0; // open bins are roomy enough anyway
        }
        score += new_penalty.max(-30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // residual usable by next item: reward proportionally
            score -= 4.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
        } else {
            // next item cannot use this residual: penalize dead space
            score += 2.0 * (post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // or nothing else fits.
    if bin_residual == bin_capacity {
        let frac = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin
        } else if frac > 0.5 {
            // large items pack better in fresh bins
            score -= 6.0 * frac;
        } else {
            score += 10.0 + 8.0 * (1.0 - frac);
        }
    }

    // Global state coupling: when mean residual is high, prefer bins that
    // reduce fragmentation (below-mean residuals are precious).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5 * ((bin_residual as f64) - mean_residual) / 100.0;
    }

    // Time horizon: early in the stream, be more conservative with bins;
    // late in the stream, just close out residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * tightness;

    // Mild preference to fill bins when many are open (consolidation).
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear coupling: post_residual interacts with stream progress.
    // Early on, larger residuals are acceptable; later, punish leftover space harder.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Smooth reward for good fill ratio relative to capacity
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 25.0 * fill * fill * (0.5 + progress);

    // Dead-space penalty if residual is too small for the lookahead item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 6.0 * (gap / cap) * (1.0 + progress);
        // Reward when post_residual still fits the next item
        if pr >= next_item_size as f64 {
            score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for proliferation of open bins late in stream
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Alignment with mean residual: prefer bins near mean (keeps flexibility)
    score += 0.15 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral baseline with slight early-stream preference
    if bin_residual == bin_capacity {
        score = 20.0 + 30.0 * (1.0 - progress) + 0.8 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact-fill and small-waste classes are golden.
    let pr = post_residual as i64;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 60.0;   // near-perfect, dead space negligible
    } else {
        // Penalize residuals that fall into "awkward" modulo classes of capacity.
        // Residuals mod 10 small => many future items (sizes often multiples/small) fit.
        let m = post_residual % 10;
        score -= (10 - m as f64) * 2.0;
        // Penalize mid-range residuals that are too large to be closed soon.
        if pr > 30 && pr < 60 {
            score += 8.0;
        }
        // Harmonic division thresholds: residual divisible by common item granularities.
        if post_residual % 20 == 0 { score -= 12.0; }
        if post_residual % 25 == 0 { score -= 12.0; }
        if post_residual % 50 == 0 { score -= 10.0; }
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 {
        // Next item won't fit here: residual becomes dead space for one step.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Baseline cost of a fresh bin ~ typical wasted space.
        let mut new_bin_score = 55.0 + open_bins_count as f64 * 2.0 + pressure * 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_score -= 5.0;
        }
        // Late in stream, prefer filling existing bins.
        new_bin_score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
        score = new_bin_score;
    } else {
        // Tightness reward: favor bins with least residual (best-fit flavor).
        score -= (bin_capacity - bin_residual) as f64 * 0.4;
        // Slight penalty when this bin's residual is far above mean (fragmentation).
        if (bin_residual as f64 - mean_residual).abs() > 25.0 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: near-perfect fits heavily favored.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - 4.0 * tightness).max(-1.0) * (1.0 - tightness);

    // Penalize small unusable dead space: gaps that likely cannot host future items.
    let min_item = 1.0;
    if (post_residual as f64) < min_item.max(next_item_size as f64) && next_item_size > 0 {
        score += 25.0; // dead gap: space wasted entirely
    } else if post_residual > 0 && post_residual < item_size.min(bin_capacity / 4).max(1) {
        score += 8.0; // awkward small gap
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 5.0; // this placement destroys ability to fit next item here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual close to mean residual (balanced filling),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when item barely fits anywhere or bins are very full.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let best_possible = if fitting_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        let desperate = fitting_bins_count == 0 || mean_residual < item_size as f64 * 1.2;
        if desperate {
            score -= 15.0;
        } else {
            // Opening new bin wastes mean_residual worth of space; penalize.
            score += mean_residual * 0.6 + 10.0;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 4.0; // new bin can still host the next item
            }
        }
        let _ = best_possible;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the NEXT item fits the post-residual perfectly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            if gap == 0.0 {
                score -= 500.0;
            } else {
                score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item won't fit: penalize proportionally to wasted lookahead potential.
            score += 30.0 * (nxt - post_residual as f64) / nxt.max(1.0);
        }
    }

    // Penalize leaving residuals below the minimum item size (unusable dead space),
    // unless post_residual is 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter;
    // prefer filling tighter bins to consolidate waste.
    let cap = bin_capacity as f64;
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score -= 25.0 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make empty bins mildly attractive only when item is large
    // and current bin fit is poor; otherwise discourage spreading across bins.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        if fit_ratio > 0.7 {
            score -= 20.0 * (fit_ratio - 0.7) * 10.0;
        } else {
            score += 40.0;
        }
    }

    // Late-stream consolidation: as stream progresses, favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 14.0 * fit_ratio;

    // Penalize leaving large dead space relative to capacity (wasted capacity).
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * dead_frac * dead_frac;

    // Lookahead (k=2): if the next item can fit into the post residual,
    // reward this placement (chaining); else mild penalty for blocking.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * (0.5 + chain);
        } else {
            // Penalize more if the leftover is tiny and useless for the next item.
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is reasonable when few bins fit the item or
        // existing residuals are poorly matched (item much smaller than mean residual gap).
        let mismatch = (mean_residual - item_size as f64).abs();
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin.
        score += 20.0;
        // Discount new-bin cost when fits are scarce or the stream is early/late.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score -= 15.0;
        }
        score -= 8.0 * (1.0 - progress);
        // If item fits poorly everywhere (large mismatch), new bin is more attractive.
        score -= 0.05 * mismatch;
        // Many open bins: discourage hoarding new bins.
        score += 1.2 * open_bins_count as f64 * (0.3 + progress);
    } else {
        // Existing bin: compare its residual against the mean residual.
        // Prefer bins tighter than average (better consolidation).
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
        // Mild pressure to close bins as the stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Global consolidation: when many bins are open, favor placements that
    // reduce open-bin count potential (near-emptying a bin).
    if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: post_residual weighted by stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * (1.0 - progress);
    score += 60.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 25.0 * (1.0 - pr / nx) * (0.5 + progress);
        } else {
            score -= 10.0 * (pr / nx - 1.0).min(1.0);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 2.0 * open_bins_count as f64 * progress * 0.1;

    // Prefer bins with residuals deviating favorably from the mean residual
    score += 5.0 * (mean_residual - bin_residual as f64) / cap;

    // New-bin candidate: neutral-to-slightly-high default, overcome only by good fits
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic discount for small leftover space.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr).powi(2) * 0.015;

    // Harmonic class of post_residual: residues divisible by common size
    // classes are more reusable, others are dead space.
    let res = post_residual;
    if res > 0 {
        let reusable = (res % 10 == 0) || (res % 20 == 0) || (res % 25 == 0);
        if reusable {
            score -= 8.0;
        } else if res < 10 {
            // tiny unusable sliver
            score += 12.0;
        } else {
            score += 4.0;
        }
    }

    // Lookahead: penalize if the next item could have fit in the space we
    // are about to waste, reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual && post_residual > 0 {
            // wasting space that the lookahead needs
            score += 6.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        }
        if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score -= 5.0; // sliver is fine since next item can't use it anyway
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Discourage opening new bins early in the stream when open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 25.0 * (1.0 - progress) * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (i.e., fuller bins) to keep many mid-size bins available.
    score += (pr - mean_residual).max(-50.0).min(50.0) * 0.1;

    // Integer-division threshold: bins whose residual is in the "awkward"
    // 11..19 band after placement are penalized (fits few item classes).
    if (11..=19).contains(&post_residual) {
        score += 7.0;
    }
    if (20..=34).contains(&post_residual) {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => big subtraction; near match => graded reward.
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            score -= 40.0 / gap.max(1.0);
        } else {
            // Next item cannot fit: post_residual becomes dead space; penalize.
            score += 12.0 + gap * 0.35;
        }
    }

    // Penalize residual far below mean (fragmenting a good bin) mildly,
    // reward leaving residual near mean (keeps bins uniform).
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins tightly: squared penalty on large leftover.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.25;

    // Late in stream, consolidate: favor bins with small residual before placement.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - item_size as f64) * 0.05;

    // Many open bins: encourage closing them out (favor low post_residual extra).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Brand-new empty bin candidate: neutral baseline; only attractive when
    // item is huge relative to capacity or nothing else fits well.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.15 * item_size as f64;
    }

    score
}
